def get_motw_channel_id(guild_id: int) -> int:
    value = guild_config_get(guild_id, "motw_channel_id")
    if value is not None:
        return int(value)
    if legacy_fallback_allowed(guild_id):
        legacy = db_meta_get("motw_channel_id")
        if legacy:
            return int(legacy)
        if len(bot.guilds) <= 1:
            return MOTW_CHANNEL_ID
    return 0


