# Registro de actividad de miembros. Las acciones de moderación se identifican
# mediante la auditoría de Discord; ante falta de permisos se clasifica como salida.
async def classify_member_departure(member):
    guild = member.guild
    observed = datetime.now(timezone.utc)
    if not guild.me or not guild.me.guild_permissions.view_audit_log:
        return "member_leave", None, None, "No se pudo confirmar la causa: falta acceso a la auditoría."
    audit_checked = False
    for delay in (2, 3, 5):
        await asyncio.sleep(delay)
        try:
            for action, event in ((discord.AuditLogAction.ban, "member_ban"),
                                  (discord.AuditLogAction.kick, "member_kick")):
                async for entry in guild.audit_logs(limit=25, action=action, after=observed - timedelta(seconds=20)):
                    if (getattr(entry.target, "id", None) == member.id
                            and abs((entry.created_at - observed).total_seconds()) <= 20):
                        return event, entry.user, entry.reason, None
            audit_checked = True
        except discord.Forbidden:
            return "member_leave", None, None, "No se pudo confirmar la causa: acceso a auditoría denegado."
        except discord.HTTPException:
            continue
    if not audit_checked:
        return "member_leave", None, None, "No se pudo confirmar la causa: fallaron las consultas a la auditoría."
    return "member_leave", None, None, "Salida observada; no se encontró una expulsión o baneo en la auditoría consultada."



def member_departure_description(
    member: discord.Member, kind: str, *,
    moderator: discord.abc.User | None = None,
    reason: str | None = None,
    uncertainty: str | None = None,
    ban_duration_known: bool = False,
    ban_duration_minutes: int | None = None,
    ban_expires_at: datetime | None = None,
    extra: list[tuple[str, str]] | None = None,
) -> str:
    """Tarjeta compacta con hechos comprobados del evento, sin enlaces ficticios."""
    guild = member.guild
    joined = discord.utils.format_dt(member.joined_at, "R") if member.joined_at else "No disponible"
    roles = [role.mention for role in member.roles if role.id != guild.default_role.id]
    shown: list[str] = []
    for role in roles:
        if len(", ".join((*shown, role))) > 850:
            break
        shown.append(role)
    roles_text = ", ".join(shown) if shown else "Ninguno"
    if len(shown) < len(roles):
        roles_text += f" y {len(roles) - len(shown)} más"
    name = discord.utils.escape_markdown(str(member.display_name))[:100]
    lines = [
        f"> **Usuario:** {name} ({member.mention})",
        f"> **ID:** \u0060{member.id}\u0060",
        f"> **Ingresó:** {joined}",
        f"> **Roles:** {roles_text}",
        f"> **Miembros:** {guild.member_count if guild.member_count is not None else 'No disponible'}",
    ]
    if kind in {"member_kick", "member_ban"}:
        if reason:
            clean_reason = discord.utils.escape_markdown(str(reason)[:500]).replace("\n", " ")
            lines.append(f"> **Motivo:** {clean_reason}")
        if moderator is not None:
            lines.append(f"> **Responsable:** {moderator.mention}")
    if kind == "member_ban":
        if ban_duration_known:
            duration = format_duration(ban_duration_minutes) if ban_duration_minutes else "Permanente"
            lines.append(f"> **Duración:** {duration}")
            if ban_duration_minutes and ban_expires_at:
                lines.append(f"> **Finaliza:** {discord.utils.format_dt(ban_expires_at, 'R')}")
        else:
            lines.append("> **Duración:** No consta en los registros disponibles")
    if kind == "member_leave" and uncertainty:
        lines.append(f"> **Clasificación:** {discord.utils.escape_markdown(uncertainty[:220])}")
    for label, value in (extra or []):
        lines.append(f"> **{label}:** {value}")
    return "\n".join(lines)


def member_departure_embed(member: discord.Member, kind: str, **kwargs) -> discord.Embed:
    """Respeta el editor de plantillas existente, con avatar por defecto."""
    title = dict(LOG_EVENT_CATALOG["members"])[kind]
    body = member_departure_description(member, kind, **kwargs)
    embed = build_log_template_embed(
        member.guild, title, body,
        discord.Color.red(),
        category="members", event_key=kind,
    )
    if not embed.thumbnail.url:
        embed.set_thumbnail(url=member.display_avatar.url)
    return embed


def member_departure_ban_details(
    guild_id: int, user_id: int, when: datetime, reason: str | None,
) -> tuple[bool, int | None, datetime | None]:
    """Mostrar duración solo si un expediente reciente confirma el mismo baneo."""
    try:
        cases = moderation_case_list(guild_id, user_id, case_type="BAN", limit=5)
    except (sqlite3.Error, ValueError):
        return False, None, None
    for case in cases:
        try:
            created = datetime.fromisoformat(case["created_at"])
            if created.tzinfo is None:
                created = created.replace(tzinfo=timezone.utc)
            if abs((when - created).total_seconds()) > 90:
                continue
            if reason and (case["reason"] or "").strip() != reason.strip():
                continue
            duration = int(case["duration_minutes"]) if case["duration_minutes"] else None
            expiration = datetime.fromisoformat(case["expires_at"]) if case["expires_at"] else None
            return True, duration, expiration
        except (ValueError, TypeError, KeyError):
            continue
    return False, None, None


# Evitar dos tarjetas por la misma expulsión de verificación, sin ocultar
# expulsiones externas ni perder el único registro cuando falle su publicación.
_ORIENTATION_KICK_REASON = "No definió su personalidad"
_ORIENTATION_LOG_WINDOW = 30.0
_orientation_kick_log_pending: dict[tuple, asyncio.Event] = {}
_orientation_kick_log_sent: dict[tuple, float] = {}


def orientation_kick_log_key(member: discord.Member) -> tuple:
    # La fecha de entrada distingue dos sesiones del mismo usuario.
    return (member.guild.id, member.id, getattr(member, "joined_at", None))


def orientation_prune_kick_log_markers(now: float | None = None) -> None:
    now = time.monotonic() if now is None else now
    for key, observed in list(_orientation_kick_log_sent.items()):
        if now - observed > _ORIENTATION_LOG_WINDOW:
            _orientation_kick_log_sent.pop(key, None)


async def orientation_departure_has_detailed_log(
    member: discord.Member, kind: str, moderator: discord.abc.User | None, reason: str | None,
) -> bool:
    """Solo omitir el log genérico si la tarjeta detallada YA fue enviada."""
    if kind not in {"member_kick", "member_leave"}:
        return False
    if kind == "member_kick":
        bot_user = bot.user
        if (bot_user is None or getattr(moderator, "id", None) != bot_user.id
                or (reason or "").strip() != _ORIENTATION_KICK_REASON):
            return False
    key = orientation_kick_log_key(member)
    pending = _orientation_kick_log_pending.get(key)
    if pending is not None:
        try:
            await asyncio.wait_for(pending.wait(), timeout=5)
        except asyncio.TimeoutError:
            pass  # Evitar bloquear la auditoría cuando Discord no responde.
    now = time.monotonic()
    orientation_prune_kick_log_markers(now)
    logged_at = _orientation_kick_log_sent.pop(key, None)
    return logged_at is not None and 0 <= now - logged_at <= _ORIENTATION_LOG_WINDOW



def exit_comments_enabled(guild_id: int) -> bool:
    return guild_config_get(guild_id, "exit_comments_enabled") == "1"


def exit_comment_private(channel: discord.TextChannel) -> bool:
    guild = channel.guild
    if channel.permissions_for(guild.default_role).view_channel:
        return False
    for role in guild.roles:
        if role.is_default() or not channel.permissions_for(role).view_channel:
            continue
        if not any(getattr(role.permissions, p, False) for p in
                   ("administrator", "manage_guild", "manage_messages",
                    "moderate_members", "kick_members", "ban_members")):
            return False
    # Un overwrite individual puede abrir el canal a un usuario que no tiene rol
    # de moderación. No enviar comentarios privados a un destino así configurado.
    for target, overwrite in channel.overwrites.items():
        if overwrite.view_channel is not True or isinstance(target, discord.Role):
            continue
        # La caché puede no resolver un usuario con acceso explícito. En caso
        # de incertidumbre se rechaza este canal para comentarios privados.
        if not isinstance(target, discord.Member) or not verification_is_exempt(target):
            return False
    me = guild.me
    return bool(me and all((channel.permissions_for(me).view_channel,
                             channel.permissions_for(me).send_messages,
                             channel.permissions_for(me).embed_links,
                             channel.permissions_for(me).read_message_history)))


async def exit_comment_audit_safe(member: discord.Member) -> bool:
    """Segunda lectura tras el evento: no inferir salida voluntaria por un único sondeo.

    Discord no ofrece un evento que pruebe directamente una salida voluntaria;
    ante cualquier consulta fallida o sanción reciente se cancela la encuesta.
    """
    guild = member.guild
    if not guild.me or not guild.me.guild_permissions.view_audit_log:
        return False
    # Dar margen a que Discord publique entradas de auditoría diferidas.
    await asyncio.sleep(4)
    observed = datetime.now(timezone.utc)
    try:
        for action in (discord.AuditLogAction.ban, discord.AuditLogAction.kick):
            async for entry in guild.audit_logs(
                limit=50, action=action, after=observed - timedelta(seconds=95)
            ):
                if (getattr(entry.target, "id", None) == member.id
                        and abs((entry.created_at - observed).total_seconds()) < 95):
                    return False
    except (discord.Forbidden, discord.HTTPException):
        return False
    return True


async def exit_comment_apply(row) -> bool:
    guild = bot.get_guild(int(row["guild_id"]))
    channel = guild.get_channel(int(row["log_channel_id"])) if guild else None
    if not isinstance(channel, discord.TextChannel) or not exit_comment_private(channel):
        return False
    try:
        original = await channel.fetch_message(int(row["log_message_id"]))
        if not original.embeds:
            return False
        embed = original.embeds[0].copy()
        old = embed.description or ""
        comment = discord.utils.escape_markdown(
            discord.utils.escape_mentions(str(row["comment"]))).replace("\n", " ")
        addition = "\n> **Comentario:** " + comment
        if len(old) + len(addition) > 4096:
            return False
        if addition not in old:
            # No reemplazar campos existentes ni asumir que otro «Comentario»
            # pertenece a esta respuesta.
            if "**Comentario:**" in old:
                return False
            embed.description = old + addition
            await original.edit(embed=embed, allowed_mentions=discord.AllowedMentions.none())
    except (discord.HTTPException, discord.Forbidden, discord.NotFound):
        return False
    with closing(db_connect()) as conn:
        exit_comments.mark_applied(conn, guild_id=int(row["guild_id"]),
                                   log_message_id=int(row["log_message_id"]))
    return True


async def exit_comment_retry() -> None:
    with closing(db_connect()) as conn:
        rows = exit_comments.pending_edits(conn)
    for row in rows:
        try:
            await exit_comment_apply(row)
        except Exception:
            traceback.print_exc()


@tasks.loop(minutes=15)
async def exit_comment_maintenance_loop() -> None:
    # Ninguna respuesta no aplicada se elimina automáticamente.
    try:
        with closing(db_connect()) as conn:
            exit_comments.purge_expired(conn)
        await exit_comment_retry()
    except (sqlite3.Error, discord.HTTPException):
        print("Advertencia: mantenimiento de comentarios pendiente de reintento.")


class ExitCommentModal(discord.ui.Modal, title="Comentario de salida"):
    comment = discord.ui.TextInput(
        label="¿Por qué abandonaste el servidor?",
        style=discord.TextStyle.paragraph, required=True, max_length=500)

    def __init__(self, dm_message_id: int):
        super().__init__(timeout=300)
        self.dm_message_id = dm_message_id

    async def on_submit(self, interaction: discord.Interaction):
        content = str(self.comment.value).strip()
        if not content or len(content) > exit_comments.COMMENT_LIMIT:
            await interaction.response.send_message(
                "Escribe un comentario de entre 1 y 500 caracteres.", ephemeral=True)
            return
        try:
            with closing(db_connect()) as conn:
                row = exit_comments.find_by_dm(
                    conn, dm_message_id=self.dm_message_id, user_id=interaction.user.id)
                if row is None or not exit_comments.submit_comment(
                        conn, dm_message_id=self.dm_message_id,
                        user_id=interaction.user.id, comment=content):
                    await interaction.response.send_message(
                        "Solicitud caducada o ya respondida.", ephemeral=True)
                    return
                conn.row_factory = sqlite3.Row
                saved = conn.execute(
                    "SELECT * FROM member_exit_comments WHERE dm_message_id=?",
                    (self.dm_message_id,)).fetchone()
        except sqlite3.Error:
            await interaction.response.send_message(
                "No fue posible guardar tu comentario. Inténtalo más tarde.",
                ephemeral=True)
            return
        success = await exit_comment_apply(saved)
        await interaction.response.send_message(
            "Comentario incorporado al registro original." if success else
            "Comentario recibido. Su incorporación al registro está pendiente.",
            ephemeral=True)


class ExitCommentDMView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="Dejar comentario", style=discord.ButtonStyle.primary,
                       custom_id="heraldo:exitcomment:v1")
    async def respond(self, interaction: discord.Interaction, button: discord.ui.Button):
        mid = getattr(interaction.message, "id", None)
        with closing(db_connect()) as conn:
            row = exit_comments.find_by_dm(
                conn, dm_message_id=mid, user_id=interaction.user.id) if mid else None
        if row is None:
            await interaction.response.send_message(
                "Solicitud caducada o ya respondida.", ephemeral=True)
            return
        await interaction.response.send_modal(ExitCommentModal(mid))


async def exit_comment_request(member: discord.Member, message: discord.Message) -> None:
    guild = member.guild
    channel = guild.get_channel(message.channel.id)
    if (not exit_comments_enabled(guild.id) or not isinstance(channel, discord.TextChannel)
            or not exit_comment_private(channel) or guild.get_member(member.id) is not None):
        return
    with closing(db_connect()) as conn:
        if not exit_comments.create_pending(
                conn, guild_id=guild.id, user_id=member.id,
                channel_id=channel.id, log_message_id=message.id):
            return
    # Segunda comprobación conservadora: las expulsiones pueden aparecer tarde.
    if not await exit_comment_audit_safe(member) or guild.get_member(member.id) is not None:
        return
    if not exit_comments_enabled(guild.id) or not exit_comment_private(channel):
        return
    try:
        sent = await member.send(
            "Has abandonado **" + discord.utils.escape_mentions(guild.name) + "**. "
            "Si deseas compartir el motivo de tu salida, utiliza Dejar comentario. "
            "La respuesta es voluntaria y será visible para el personal autorizado "
            "con acceso al registro privado del servidor. Puedes ignorar este mensaje.",
            view=ExitCommentDMView(), allowed_mentions=discord.AllowedMentions.none())
    except discord.HTTPException:
        return  # DM bloqueado: no reintentar una solicitud incierta.

    linked = False
    for retry in range(3):
        try:
            with closing(db_connect()) as conn:
                linked = exit_comments.attach_dm(
                    conn, guild_id=guild.id, log_message_id=message.id,
                    dm_message_id=sent.id)
            break
        except sqlite3.OperationalError:
            if retry < 2:
                await asyncio.sleep(0.4)
    if not linked:
        # No dejar un botón visible que inevitablemente no pueda recuperar
        # la solicitud. No enviar nunca un segundo DM por esta incidencia.
        try:
            await sent.edit(view=None)
        except discord.HTTPException:
            pass


@bot.listen("on_member_remove")
async def heraldo_member_departure(member: discord.Member) -> None:
    guild = member.guild
    if not any(log_member_event_enabled(guild.id, key) for key in ("member_leave", "member_kick", "member_ban")):
        return
    kind, moderator, reason, uncertainty = await classify_member_departure(member)
    if await orientation_departure_has_detailed_log(member, kind, moderator, reason):
        return  # El informe específico de verificación ya explica esta expulsión.
    if not log_member_event_enabled(guild.id, kind):
        return
    labels = dict(LOG_EVENT_CATALOG["members"])
    kwargs = {"moderator": moderator, "reason": reason, "uncertainty": uncertainty}
    if kind == "member_ban":
        known, minutes, expires = member_departure_ban_details(
            guild.id, member.id, datetime.now(timezone.utc), reason,
        )
        kwargs.update(ban_duration_known=known, ban_duration_minutes=minutes,
                      ban_expires_at=expires)
    description = member_departure_description(member, kind, **kwargs)
    original = await log_embed(
        guild, labels[kind], description,
        discord.Color.red(),
        member=member,
    )
    # La auditoría disponible no encontró sanción; no enviar si la causa es incierta.
    if (kind == "member_leave" and original is not None
            and uncertainty is not None
            and uncertainty.startswith("Salida observada; no se encontró")):
        await exit_comment_request(member, original)


@bot.event
async def on_member_update(before: discord.Member, after: discord.Member) -> None:
    if after.bot:
        return  # los bots no pasan por el flujo de verificación
    if after.id == getattr(after.guild, 'owner_id', None):
        # Eximir únicamente de verificación; continuar procesando las
        # condenas y otros cambios de roles que correspondan.
        clear_verification_expiry(after.guild.id, after.id)
        db_clear_tentado(after.guild.id, after.id)
    if (after.guild.id, after.id) in _condemn_sync_busy:
        return

    before_role_ids = {r.id for r in before.roles}
    after_role_ids = {r.id for r in after.roles}
    active_condemnation = condemnation_get(after.guild.id, after.id)
    condemned_id = condemnation_role_id(active_condemnation, after.guild.id)
    had_condemned = bool(condemned_id and condemned_id in before_role_ids)
    has_condemned = bool(condemned_id and condemned_id in after_role_ids)

    # El rol Condenado es la fuente de verdad: si se quita por cualquier medio, se libera.
    if had_condemned and not has_condemned and active_condemnation is not None:
        _condemn_sync_busy.add((after.guild.id, after.id))
        try:
            await release_condemned_member(after, automatic=False)
        finally:
            _condemn_sync_busy.discard((after.guild.id, after.id))
        return

    # Si alguien asigna Condenado a mano, se ejecuta exactamente el mismo proceso.
    if has_condemned and not had_condemned and active_condemnation is None:
        actor = None
        try:
            async for entry in after.guild.audit_logs(limit=8, action=discord.AuditLogAction.member_role_update):
                if entry.target and entry.target.id == after.id and (datetime.now(timezone.utc) - entry.created_at).total_seconds() < 20:
                    actor = entry.user
                    break
        except (discord.Forbidden, discord.HTTPException):
            pass
        _condemn_sync_busy.add((after.guild.id, after.id))
        try:
            protection = condemnation_protection_reason(after)
            if protection:
                role = after.guild.get_role(condemned_id)
                if role is not None and role in after.roles and role.is_assignable():
                    await after.remove_roles(role, reason=f"Condena no permitida: {protection}")
                await log_embed(after.guild, "Advertencia: Condena rechazada", f"{after.mention}: {protection}.", discord.Color.orange())
            else:
                await condemn_member(
                    after,
                    reason="El rol Condenado fue otorgado manualmente.",
                    duration_minutes=None,
                    purge_spec=hp_purge_spec(after.guild.id),
                    origin="role",
                    applied_by=actor,
                    preserve_role_ids=list(before_role_ids),
                )
        finally:
            _condemn_sync_busy.discard((after.guild.id, after.id))
        return

    # Si ya estaba condenado y otro moderador/bot añade roles, se vuelven a quitar.
    if active_condemnation is not None and has_condemned:
        added_assignable = any(
            r.id not in before_role_ids and r.id != condemned_id and r.is_assignable() and not r.managed
            for r in after.roles
        )
        if added_assignable:
            new_ids = [
                r.id for r in after.roles
                if r.id not in before_role_ids and r.id != condemned_id and r.is_assignable() and not r.managed
            ]
            _condemn_sync_busy.add((after.guild.id, after.id))
            try:
                ok, _, note = await condemnation_sync_roles(
                    after, save_snapshot=False, reason="Condenado: no puede recibir otros roles",
                    role_id=condemned_id,
                )
                if ok:
                    condemnation_add_saved_roles(after.guild.id, after.id, new_ids)
                else:
                    await log_embed(after.guild, "Advertencia: No pude re-quitar roles a un condenado", f"{after.mention}: {note}", discord.Color.orange())
            except Exception:
                traceback.print_exc()
            finally:
                _condemn_sync_busy.discard((after.guild.id, after.id))
        db_clear_tentado(after.guild.id, after.id)
        db_clear_sin_verificado(after.guild.id, after.id)
        db_clear_verify_pending(after.guild.id, after.id)
        return

    # La exención no altera las rutas de condena que se procesaron arriba.
    if verification_is_exempt(after):
        clear_verification_expiry(after.guild.id, after.id)
        db_clear_tentado(after.guild.id, after.id)
        return

    # Si un moderador pierde sus permisos, iniciar un plazo NUEVO, jamás aplicar
    # la marca antigua. No retirar ni alterar roles al reactivar la obligación.
    if (verification_is_exempt(before) and verify_enabled(after.guild.id)
            and not getattr(after, "pending", False)
            and get_verify_role_id(after.guild.id) not in after_role_ids
            and not (after_role_ids & get_eval_role_ids(after.guild.id))):
        record = db_get(after.guild.id, after.id)
        if record is None or record["verify_pending_at"] is None:
            now = datetime.now(timezone.utc)
            db_set_verify_pending(after.guild.id, after.id, now)
            asyncio.create_task(schedule_verify_timeout(after.guild.id, after.id, now))

    # Flujos normales de verificación; una condena activa ya salió por arriba.
    # Join Roles que esperan Esperar aceptación de reglas se asignan al completar la pantalla.
    if (
        (join_roles_enabled(after.guild.id) or after.id in get_join_specific_roles(after.guild.id))
        and join_roles_wait_screening(after.guild.id)
        and getattr(before, "pending", False)
        and not getattr(after, "pending", False)
    ):
        queue_join_roles(after)
        verify_role_id_after_screening = get_verify_role_id(after.guild.id)
        if (
            verify_enabled(after.guild.id)
            and verify_role_id_after_screening not in after_role_ids
        ):
            now = datetime.now(timezone.utc)
            db_set_verify_pending(after.guild.id, after.id, now)
            asyncio.create_task(schedule_verify_timeout(after.guild.id, after.id, now))

    # Si el rol de verificación aparece por cualquier medio, Sin Verificar se retira.
    verify_role_id = get_verify_role_id(after.guild.id)
    if verify_role_id and verify_role_id in after_role_ids and verify_role_id not in before_role_ids:
        await clear_sin_verificar_after_verification(
            after,
            reason="Rol de verificación detectado por El Heraldo",
        )
        return

    if get_sin_verificado_role_id(after.guild.id) in after_role_ids and get_sin_verificado_role_id(after.guild.id) not in before_role_ids:
        if verify_role_id and verify_role_id in after_role_ids:
            await clear_sin_verificar_after_verification(
                after,
                reason="Sin Verificar no aplica a un miembro ya verificado",
            )
        # El rol identifica a quien aún no se verificó; no crea otro plazo.
        # Solo verify_pending_at controla la caducidad de edad cuando está activa.

    # IMPORTANTE: asignar el rol de verificación/personalidad manualmente NO inicia
    # el temporizador. La personalidad solo nace cuando El Heraldo procesa una
    # verificación nueva desde su botón. Esto protege a miembros antiguos y evita
    # aplicar expulsiones retroactivas al instalar o reconfigurar el bot.


_verification_expiry_inflight: set[tuple[int, int]] = set()


def clear_verification_expiry(guild_id: int, user_id: int) -> None:
    """Resolver ambos temporizadores que pertenecen a la misma verificación."""
    conn = db_connect()
    try:
        conn.execute("UPDATE guild_members SET verify_pending_at = NULL, sin_verificado_at = NULL WHERE guild_id = ? AND user_id = ?",
                     (guild_id, user_id))
    finally:
        conn.close()


def verification_is_exempt(member: discord.Member) -> bool:
    """Propietario y personal con permisos reales de moderación: nunca vencer verificaciones.

    No usar nombres de roles ni eximir al miembro de la moderación ordinaria.
    Los permisos efectivos de Discord reflejan también los roles configurados.
    """
    guild = getattr(member, "guild", None)
    if guild is not None and member.id == getattr(guild, "owner_id", None):
        return True
    perms = getattr(member, "guild_permissions", None)
    return bool(perms is not None and any(
        getattr(perms, permission, False)
        for permission in ("administrator", "manage_guild", "manage_messages",
                           "moderate_members", "kick_members", "ban_members")
    ))


async def run_verification_expiry(guild_id: int, user_id: int, evaluator) -> None:
    guild = bot.get_guild(guild_id)
    if guild is not None:
        member = guild.get_member(user_id)
        if (member is not None and verification_is_exempt(member)
                or user_id == getattr(guild, "owner_id", None)):
            clear_verification_expiry(guild_id, user_id)
            db_clear_tentado(guild_id, user_id)
            return
    key = (guild_id, user_id)
    if key in _verification_expiry_inflight:
        return
    _verification_expiry_inflight.add(key)
    try:
        await evaluator(guild_id, user_id)
    finally:
        _verification_expiry_inflight.discard(key)


async def schedule_check(guild_id: int, user_id: int, tentado_at: datetime) -> None:
    delay = (tentado_at + get_orientation_window(guild_id) - datetime.now(timezone.utc)).total_seconds()
    if delay > 0:
        await asyncio.sleep(delay)
    await evaluate_member(guild_id, user_id)


# Conciliación conservadora: no sancionar retroactivamente roles sin fecha de origen.
async def reconcile_untracked_verifications_for_guild(guild: discord.Guild) -> tuple[tuple[int, ...], tuple[int, ...], tuple[int, ...]]:
    """Examina roles no seguidos; solo rearma ingresos recientes con plazo completo nuevo."""
    unverified_id = get_sin_verificado_role_id(guild.id)
    if not unverified_id or guild.get_role(unverified_id) is None:
        return (), (), ()
    verified_id = get_verify_role_id(guild.id)
    orientation_ids = get_eval_role_ids(guild.id)
    can_rearm = bool(verify_enabled(guild.id) and verified_id and guild.get_role(verified_id))
    # Test no puede reactivar plazos en un servidor ajeno al laboratorio autorizado.
    if heraldo_is_test() and os.getenv("HERALDO_TEST_LAB_GUILD_ID") != str(guild.id):
        can_rearm = False
    now = datetime.now(timezone.utc)
    rearmed: list[int] = []
    review: list[int] = []
    inconsistent: list[int] = []
    # No depender de que la caché esté completa después de un largo período desconectado.
    async for member in guild.fetch_members(limit=None):
        if member.bot or verification_is_exempt(member):
            continue
        roles = {role.id for role in member.roles}
        if unverified_id not in roles:
            continue
        if verified_id in roles or roles & orientation_ids:
            inconsistent.append(member.id)
            continue
        if condemnation_get(guild.id, member.id) is not None:
            continue
        row = db_get(guild.id, member.id)
        if row is not None and any(row[key] is not None for key in
                                   ("verify_pending_at", "sin_verificado_at", "tentado_at")):
            continue
        joined = getattr(member, "joined_at", None)
        age = (now - joined).total_seconds() if joined is not None and joined.tzinfo else -1
        # joined_at no prueba cuándo se otorgó el rol: tras 15 min, solo informar.
        # Reanudar crea una ventana NUEVA; nunca un vencimiento calculado hacia atrás.
        if (can_rearm and not getattr(member, "pending", False)
                and 0 <= age <= 900 and len(rearmed) < 25):
            db_set_verify_pending(guild.id, member.id, now)
            rearmed.append(member.id)
        else:
            review.append(member.id)
    return tuple(rearmed), tuple(review), tuple(inconsistent)


@tasks.loop(minutes=30)
async def reconcile_untracked_verifications() -> None:
    """Persistir el último aviso entregado; reinicios sin cambios no generan otro."""
    for guild in bot.guilds:
        try:
            rearmed, review, inconsistent = await reconcile_untracked_verifications_for_guild(guild)
            # Nunca guardar identificadores visibles en el registro de avisos.
            fingerprint = hashlib.sha256(
                json.dumps((sorted(review), sorted(inconsistent)),
                           separators=(",", ":")).encode("utf-8")
            ).hexdigest()
            key = f"verification_orphan_notice:v1:{guild.id}"
            previous = db_meta_get(key)
            should_notify = bool(rearmed or ((review or inconsistent) and fingerprint != previous))
            if should_notify:
                delivered = await log_embed(
                    guild, "Verificación: pendientes sin seguimiento",
                    f"Plazos nuevos iniciados: **{len(rearmed)}**. "
                    f"Miembros que requieren revisión manual: **{len(review)}**. "
                    f"Roles contradictorios con la verificación: **{len(inconsistent)}**. "
                    "No se expulsaron miembros ni se modificaron roles durante esta revisión. "
                    "Los casos antiguos no se sancionan retroactivamente.",
                    discord.Color.orange(),
                )
                if delivered is not None:
                    db_meta_set(key, fingerprint)
            elif not review and not inconsistent and previous is not None and previous != fingerprint:
                # Estado vacío: una reaparición posterior sí se notificará.
                db_meta_set(key, fingerprint)
        except Exception:
            print(f"Advertencia: conciliación de verificación pendiente en servidor {guild.id}.")


@tasks.loop(minutes=2)
async def check_pending_verifications() -> None:
    """Red de seguridad: retoma verificaciones pendientes sin dejar que una fila
    dañada o un fallo puntual detenga toda la automatización."""
    conn: sqlite3.Connection | None = None
    try:
        conn = db_connect()
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT guild_id, user_id, tentado_at, verify_pending_at FROM guild_members "
            "WHERE tentado_at IS NOT NULL OR verify_pending_at IS NOT NULL"
        ).fetchall()
    except Exception:
        print("Error: Falló la lectura de verificaciones pendientes:")
        traceback.print_exc()
        return
    finally:
        if conn is not None:
            conn.close()

    now = datetime.now(timezone.utc)
    for row in rows:
        try:
            guild = bot.get_guild(row["guild_id"])
            if guild is None:
                if row["tentado_at"] is not None:
                    db_clear_tentado(row["guild_id"], row["user_id"])
                if row["verify_pending_at"] is not None:
                    db_clear_verify_pending(row["guild_id"], row["user_id"])
                continue

            if row["tentado_at"] is not None:
                tentado_at = datetime.fromisoformat(row["tentado_at"])
                if now >= tentado_at + get_orientation_window(guild.id):
                    await evaluate_member(guild.id, row["user_id"])

            if row["verify_pending_at"] is not None:
                verify_pending_at = datetime.fromisoformat(row["verify_pending_at"])
                verify_window = timedelta(seconds=get_verify_timeout(guild.id))
                if now >= verify_pending_at + verify_window:
                    await evaluate_verify_timeout(guild.id, row["user_id"])
        except Exception:
            print(
                "Error: Verificación pendiente falló "
                f"(guild={row['guild_id']}, user={row['user_id']}):"
            )
            traceback.print_exc()


async def evaluate_member(guild_id: int, user_id: int, report: bool = True) -> str:
    """Devuelve 'verificado', 'expulsado', 'castigado' o 'ausente'/'sin-guild'."""
    if condemnation_get(guild_id, user_id) is not None:
        db_clear_tentado(guild_id, user_id)
        return "castigado"
    guild = bot.get_guild(guild_id)
    if guild is None:
        return "sin-guild"
    member = guild.get_member(user_id)
    if member is None:
        db_clear_tentado(guild_id, user_id)  # ya no está, nada que hacer
        return "ausente"
    if verification_is_exempt(member):
        db_clear_tentado(guild_id, user_id)
        clear_verification_expiry(guild_id, user_id)
        return "exento"

    punish_id = hp_punish_role_id(guild_id)
    if punish_id and any(r.id == punish_id for r in member.roles):
        db_clear_tentado(guild_id, user_id)  # castigado por el honeypot: no se expulsa por falta de personalidad
        return "castigado"

    role_ids = {r.id for r in member.roles}
    if role_ids & get_eval_role_ids(guild.id):
        db_clear_tentado(guild_id, user_id)  # conservar la confirmación de elección, sea o no obligatoria
        if report:
            await log_embed(guild, "Verificación de personalidad completada", f"{member.mention} completó su verificación de personalidad.", discord.Color.green())
        return "verificado"
    if not orientation_enabled(guild.id) or not personality_required(guild.id):
        db_clear_tentado(guild_id, user_id)
        return "no-obligatorio"

    kicked = await expel(member, report=report)
    return "expulsado" if kicked else "pendiente"


# ---------------------------------------------------------------------------
# Expulsión + DM condicional
# ---------------------------------------------------------------------------

async def expel(member: discord.Member, report: bool = True) -> bool:
    if (verification_is_exempt(member) or not orientation_enabled(member.guild.id)
            or not personality_required(member.guild.id)):
        db_clear_tentado(member.guild.id, member.id)
        clear_verification_expiry(member.guild.id, member.id)
        return False
    row = db_get(member.guild.id, member.id)
    dm_sent_before = bool(row["dm_sent"]) if row else False
    is_first_fault = not dm_sent_before
    test_mode = heraldo_is_test()
    dm_ok = None
    # Test: avisar de la prueba solo tras sanción confirmada.
    # Oficial: avisar de una medida PREVISTA antes de expulsar, mientras existe DM.
    dm_channel = await prepare_removal_dm(member) if (is_first_fault or test_mode) else None
    if is_first_fault and not test_mode:
        dm_ok = await send_recovery_dm(member, report=report, dm_channel=dm_channel)
        if dm_ok:
            db_mark_dm_sent(member.guild.id, member.id)  # evitar otra invitación si falla el kick

    try:
        await heraldo_kick(member, reason="No definió su personalidad", send_notice=False)
        kicked = True
    except discord.HTTPException:
        kicked = False
    if kicked:
        # No resolver el plazo hasta que Discord haya confirmado la expulsión.
        db_clear_tentado(member.guild.id, member.id)
    if kicked and test_mode:
        await send_test_removal_notice(member, "KICK", dm_channel=dm_channel,
                                       allow_reentry_invite=True)
        if is_first_fault:
            db_mark_dm_sent(member.guild.id, member.id)

    if not report:
        return kicked
    if not kicked:
        await log_embed(member.guild, "Advertencia: Expulsión no completada",
                        f"Discord rechazó la expulsión de {member.mention}; revisa permisos y jerarquía. "
                        "El plazo pendiente se conserva para reintentar.",
                        discord.Color.dark_red())
        return False

    # El listener de salidas espera esta publicación antes de emitir un segundo log.
    log_key = orientation_kick_log_key(member)
    pending = asyncio.Event()
    if kicked:
        orientation_prune_kick_log_markers()
        _orientation_kick_log_pending[log_key] = pending

    extra = [("Oportunidad", "Primera" if is_first_fault else "Segunda")]
    if dm_ok is not None:
        extra.append(("DM de recuperación", "Enviado" if dm_ok else "No disponible"))
    extra.append(("Resultado", "Expulsado" if kicked else "No se pudo expulsar; revisar jerarquía"))
    embed = member_departure_embed(
        member, "member_kick", moderator=member.guild.me,
        reason="No definió su personalidad", extra=extra,
    )
    if not kicked:
        embed.color = discord.Color.dark_red()

    channel = member.guild.get_channel(get_log_channel_id(member.guild.id))
    try:
        if channel is not None:
            try:
                await channel.send(embed=embed)
            except discord.HTTPException:
                print("No se pudo publicar la tarjeta de expulsión por verificación")
            else:
                if kicked:
                    _orientation_kick_log_sent[log_key] = time.monotonic()
    finally:
        if kicked:
            _orientation_kick_log_pending.pop(log_key, None)
            pending.set()
    return kicked


def render_personality_recovery_dm(guild: discord.Guild, invite_url: str) -> str:
    """Sustitución segura de variables; textos y títulos reales por servidor."""
    template = guild_config_get(guild.id, "personality_recovery_dm_template") or DM_TEXT
    values = {
        "servidor": discord.utils.escape_mentions(guild.name),
        "razon": "No definió su personalidad",
        "titulo_embed": discord.utils.escape_mentions(get_orientation_embed_title(guild.id)),
        "invitacion": invite_url or "No disponible; solicita una invitación al equipo.",
        "invite_url": invite_url or "No disponible",
    }
    return re.sub(r"\{(servidor|razon|titulo_embed|invitacion|invite_url)\}",
                  lambda match: values[match.group(1)], template)[:1900]


async def send_recovery_dm(member: discord.Member, report: bool = True, *,
                           dm_channel: discord.DMChannel | None = None) -> bool:
    """Mensaje oficial previo de recuperación: nunca afirmar que ya se expulsó."""
    channel = member.guild.get_channel(get_recovery_channel_id(member.guild.id))
    invite_url = ""
    if channel is not None:
        try:
            invite = await channel.create_invite(
                max_uses=1, unique=True, reason="Recuperación de personalidad de El Heraldo"
            )
            invite_url = invite.url
        except discord.HTTPException:
            if report:
                await log_embed(member.guild, "Advertencia: Error de invitación",
                                "No pude generar la invitación de recuperación.",
                                discord.Color.dark_red())
    text = render_personality_recovery_dm(member.guild, invite_url)
    try:
        target = dm_channel if dm_channel is not None else member
        await target.send(text, allowed_mentions=discord.AllowedMentions.none())
        return True
    except discord.HTTPException:
        return False

# ---------------------------------------------------------------------------
# Comando manual de prueba (slash command — no requiere message_content intent)
# ---------------------------------------------------------------------------

async def bootstrap_guild_configuration(guild: discord.Guild, create_missing: bool | None = None) -> dict[str, list[int]]:
    """Detecta/reutiliza la estructura base y, opcionalmente, crea lo que falte.

    Por defecto NO crea canales ni roles. La creación automática solo se habilita
    cuando el administrador la activa desde /setup. Así, añadir el bot a
    un servidor existente nunca crea recursos inesperados.
    """
    desired_channels = {
        "logs": "El Heraldo",
        "condemned": "Condenados",
        "honeypot": "Honeypot",
        "verification": "Verificación",
        "questions": "Dudas",
    }
    created: dict[str, list[int]] = {"channels": [], "roles": []}
    if create_missing is None:
        create_missing = guild_config_get(guild.id, "heraldo_auto_create_resources") == "1"
    me = guild.me
    if me is None:
        return created

    # La instalación es deliberadamente idempotente: /setup también sirve
    # para reparar la estructura después de que un canal/rol haya sido eliminado.
    # Primero respetamos el ID guardado; solo si ya no existe buscamos por nombre.
    existing_channels = {c.name.casefold(): c for c in guild.text_channels}
    for key, default_name in desired_channels.items():
        channel = None
        saved_id = guild_resource_get(guild.id, "channel", key)
        if saved_id:
            candidate = guild.get_channel(saved_id)
            if isinstance(candidate, discord.TextChannel):
                channel = candidate
        if channel is None:
            channel = existing_channels.get(default_name.casefold())
        if channel is None:
            if not create_missing:
                continue
            if not me.guild_permissions.manage_channels:
                continue
            try:
                channel = await guild.create_text_channel(
                    default_name,
                    reason="El Heraldo: instalación/reparación de plantilla base",
                )
                created["channels"].append(channel.id)
                existing_channels[channel.name.casefold()] = channel
            except discord.Forbidden:
                continue
        guild_resource_set(guild.id, "channel", key, channel.id)

    if me.guild_permissions.manage_roles:
        desired_roles = {
            "sin_verificar": "Sin Verificar",
            "tentado": "Tentad@",
            "condenado": "Condenado",
        }
        existing_roles = {r.name.casefold(): r for r in guild.roles}
        for key, default_name in desired_roles.items():
            role = None
            saved_id = guild_resource_get(guild.id, "role", key)
            if saved_id:
                candidate = guild.get_role(saved_id)
                if candidate is not None:
                    role = candidate
            if role is None:
                role = existing_roles.get(default_name.casefold())
            if role is None:
                if not create_missing:
                    continue
                try:
                    role = await guild.create_role(
                        name=default_name,
                        reason="El Heraldo: instalación/reparación de plantilla base",
                    )
                    created["roles"].append(role.id)
                    existing_roles[role.name.casefold()] = role
                except discord.Forbidden:
                    continue
            guild_resource_set(guild.id, "role", key, role.id)

    # Solo se marca como inicializado después de ejecutar el proceso completo.
    # En una ejecución posterior se vuelve a comprobar todo, por lo que una
    # eliminación accidental puede repararse sin borrar ni duplicar recursos.
    guild_mark_initialized(guild.id)
    return created


def verification_duration_label(seconds: int) -> str:
    """Mostrar el valor real sin redondear las configuraciones antiguas."""
    if seconds < 60:
        return f"{seconds} s"
    minutes, rest = divmod(seconds, 60)
    if rest:
        return f"{minutes} min {rest} s"
    if minutes < 60:
        return f"{minutes} min"
    hours, mins = divmod(minutes, 60)
    if hours < 24:
        return f"{hours} h" + (f" {mins} min" if mins else "")
    days, hours = divmod(hours, 24)
    return f"{days} d" + (f" {hours} h" if hours else "") + (f" {mins} min" if mins else "")


def age_time_summary(guild_id: int) -> str:
    return (
        "**Plazo de verificación de edad:** "
        f"**{verification_duration_label(get_verify_timeout(guild_id))}**"
    )


def personality_time_summary(guild_id: int) -> str:
    return (
        "**Plazo de personalidad:** "
        f"{verification_duration_label(int(get_orientation_window(guild_id).total_seconds()))}"
    )


def verification_hub_content(guild_id: int) -> str:
    return (
        "**El Heraldo · Verificación**\n\n"
        "Selecciona el módulo que deseas configurar. Los plazos son independientes.\n\n"
        + age_time_summary(guild_id) + "\n\n" + personality_time_summary(guild_id)
    )


class AgeVerificationTimeModal(discord.ui.Modal, title="Plazo de verificación de edad"):
    verify_timeout = discord.ui.TextInput(
        label="Verificación de edad (minutos)", required=True,
        max_length=6, placeholder="Ejemplo: 5")

    def __init__(self, guild_id: int) -> None:
        super().__init__()
        self.guild_id = guild_id
        self.initial = str(max(1, (get_verify_timeout(guild_id) + 59) // 60))
        self.verify_timeout.default = self.initial

    async def on_submit(self, interaction: discord.Interaction) -> None:
        if not await configuration_access(interaction, self.guild_id):
            return
        value = str(self.verify_timeout).strip()
        try:
            minutes = int(value)
            if not 1 <= minutes <= 40320:
                raise ValueError
        except ValueError:
            await interaction.response.send_message(
                "Escribe minutos enteros de 1 a 40 320 (28 días). No se guardó nada.",
                ephemeral=True)
            return
        if value == self.initial:
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id,
                                    {"verify_timeout": str(minutes * 60)})


