def heraldo_permissions_summary(guild: discord.Guild) -> str:
    lines: list[str] = []
    channel_defs = (
        ("logs", "Logs"),
        ("condemned", "Condenados"),
        ("honeypot", "Honeypot"),
        ("verification", "Verificación"),
        ("questions", "Dudas"),
    )
    for key, label in channel_defs:
        channel_id = get_guild_channel_id(guild.id, key)
        channel = guild.get_channel(channel_id) if channel_id else None
        if not isinstance(channel, discord.TextChannel):
            lines.append(f"Error: **{label}:** no configurado")
            continue
        perms = channel.permissions_for(guild.me)
        missing: list[str] = []
        if not perms.view_channel:
            missing.append("Ver canal")
        if not perms.send_messages:
            missing.append("Enviar mensajes")
        if key in {"logs", "condemned", "honeypot", "verification"} and not perms.embed_links:
            missing.append("Insertar enlaces")
        if key == "honeypot" and not perms.manage_messages:
            missing.append("Gestionar mensajes")
        lines.append(
            f"**{label}:** {channel.mention}"
            + (f" · faltan: {', '.join(missing)}" if missing else "")
        )

    role_defs = (
        ("sin_verificar", "Sin Verificar"),
        ("tentado", "Verificación / personalidad"),
        ("condenado", "Condenado"),
    )
    for key, label in role_defs:
        role_id = get_guild_role_id(guild.id, key)
        role = guild.get_role(role_id) if role_id else None
        if role is None:
            lines.append(f"Error: **Rol {label}:** no configurado")
            continue
        problem = None
        if role.is_default():
            problem = "es @everyone"
        elif role.managed:
            problem = "está gestionado por Discord o una integración"
        elif role >= guild.me.top_role:
            problem = "está al mismo nivel o por encima del rol del Heraldo"
        lines.append(
            f"**Rol {label}:** {role.mention}"
            + (f" · {problem}" if problem else "")
        )
    return "\n".join(lines)



class HeraldoVerificationSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.pending_role_id: int | None = None
        self.pending_sin_role_id: int | None = None
        self.pending_channel_id: int | None = None
        self.pending_enabled: bool | None = None
        self._refresh_origins()

    def _refresh_origins(self) -> None:
        self.original_settings = {
            key: guild_config_get(self.guild_id, key)
            for key in ("verify_role_id", "verify_channel_id", "verify_enabled")
        }
        self.original_resources = {
            ("role", "tentado"): guild_resource_get(self.guild_id, "role", "tentado"),
            ("role", "sin_verificar"): guild_resource_get(self.guild_id, "role", "sin_verificar"),
            ("channel", "verification"): guild_resource_get(self.guild_id, "channel", "verification"),
        }

        role_select = discord.ui.RoleSelect(
            placeholder="Seleccionar rol que se otorga al verificarse",
            min_values=1,
            max_values=1,
            row=0,
        )
        role_select.callback = self.select_role
        self.add_item(role_select)

        sin_role_select = discord.ui.RoleSelect(
            placeholder="Seleccionar rol Sin Verificar",
            min_values=1,
            max_values=1,
            row=1,
        )
        sin_role_select.callback = self.select_sin_role
        self.add_item(sin_role_select)

        channel_select = discord.ui.ChannelSelect(
            placeholder="Seleccionar canal de verificación",
            channel_types=[discord.ChannelType.text],
            min_values=1,
            max_values=1,
            row=2,
        )
        channel_select.callback = self.select_channel
        self.add_item(channel_select)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de configuración no es tuyo.", ephemeral=True)
            return False
        return True

    def _content(self, guild: discord.Guild) -> str:
        items = []
        if self.pending_role_id is not None:
            role = guild.get_role(self.pending_role_id)
            items.append(f"Rol de verificación → {role.mention if role else self.pending_role_id}")
        if self.pending_sin_role_id is not None:
            role = guild.get_role(self.pending_sin_role_id)
            items.append(f"Rol Sin Verificar → {role.mention if role else self.pending_sin_role_id}")
        if self.pending_channel_id is not None:
            channel = guild.get_channel(self.pending_channel_id)
            items.append(f"Canal de verificación → {channel.mention if channel else self.pending_channel_id}")
        if self.pending_enabled is not None:
            items.append(f"Verificación automática → {'activa' if self.pending_enabled else 'desactivada'}")
        return "**El Heraldo · Verificación de edad**\n\n" + verify_config_summary(guild) + "\n\n" + age_time_summary(guild.id) + _pending_config_text(items)

    async def select_role(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        role = interaction.guild.get_role(int(values[0])) if interaction.guild and values else None
        if role is None:
            await interaction.response.send_message("No pude localizar ese rol.", ephemeral=True)
            return
        problem = verify_role_problem(role, interaction.guild)
        if problem:
            await interaction.response.send_message(f"No puedo usar {role.mention}: {problem}.", ephemeral=True)
            return
        self.pending_role_id = role.id
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    async def select_sin_role(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        role = interaction.guild.get_role(int(values[0])) if interaction.guild and values else None
        if role is None:
            await interaction.response.send_message("No pude localizar ese rol.", ephemeral=True)
            return
        if role.is_default() or role.managed or role >= interaction.guild.me.top_role:
            await interaction.response.send_message(
                "Ese rol no puede ser administrado por El Heraldo. Revisa jerarquía o integraciones.",
                ephemeral=True,
            )
            return
        self.pending_sin_role_id = role.id
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    async def select_channel(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        channel = interaction.guild.get_channel(int(values[0])) if interaction.guild and values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message("No pude localizar ese canal.", ephemeral=True)
            return
        perms = channel.permissions_for(interaction.guild.me)
        missing = []
        if not perms.view_channel:
            missing.append("Ver canal")
        if not perms.send_messages:
            missing.append("Enviar mensajes")
        if missing:
            await interaction.response.send_message(f"Faltan {', '.join(missing)} en {channel.mention}.", ephemeral=True)
            return
        self.pending_channel_id = channel.id
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Crear canal", style=discord.ButtonStyle.success, row=3)
    async def create_verify_channel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        guild = interaction.guild
        existing_id = get_guild_channel_id(self.guild_id, "verification")
        channel = guild.get_channel(existing_id) if existing_id else None
        created_now = False
        if not isinstance(channel, discord.TextChannel):
            channel = next((c for c in guild.text_channels if c.name.casefold() == "verificación".casefold()), None)
        if not isinstance(channel, discord.TextChannel):
            me = guild.me
            if me is None or not me.guild_permissions.manage_channels:
                await interaction.response.send_message(
                    "El Heraldo necesita Gestionar canales para crear el canal de verificación.",
                    ephemeral=True,
                )
                return
            await interaction.response.defer(ephemeral=True)
            try:
                channel = await guild.create_text_channel(
                    "Verificación",
                    reason="El Heraldo: crear canal de verificación desde /setup",
                )
                created_now = True
            except discord.HTTPException as exc:
                await interaction.followup.send(f"No pude crear el canal: `{exc}`.", ephemeral=True)
                return
        else:
            await interaction.response.defer(ephemeral=True)

        note = await _setup_apply_system_channel(guild, "verification", channel, publish_messages=True)
        self.pending_channel_id = None
        action = "Creé" if created_now else "Reutilicé"
        await interaction.edit_original_response(
            content=self._content(guild) + f"\n\n{action} {channel.mention}. {note}",
            view=self,
        )

    @discord.ui.button(label="Crear rol verificación", style=discord.ButtonStyle.success, row=4)
    async def create_verify_role(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.defer(ephemeral=True)
        role, created_now, error = await _setup_get_or_create_system_role(
            interaction.guild, "tentado", "Verificación", "Tentad@"
        )
        if error or role is None:
            await interaction.followup.send(error or "No pude preparar el rol.", ephemeral=True)
            return
        self.pending_role_id = None
        action = "Creé" if created_now else "Reutilicé"
        await interaction.edit_original_response(
            content=self._content(interaction.guild) + f"\n\n{action} {role.mention} como rol de verificación.",
            view=self,
        )

    @discord.ui.button(label="Crear Sin Verificar", style=discord.ButtonStyle.success, row=4)
    async def create_sin_role(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.defer(ephemeral=True)
        role, created_now, error = await _setup_get_or_create_system_role(
            interaction.guild, "sin_verificar", "Sin Verificar", "Sin Verificar"
        )
        if error or role is None:
            await interaction.followup.send(error or "No pude preparar el rol.", ephemeral=True)
            return
        self.pending_sin_role_id = None
        action = "Creé" if created_now else "Reutilicé"
        await interaction.edit_original_response(
            content=self._content(interaction.guild) + f"\n\n{action} {role.mention} como rol Sin Verificar.",
            view=self,
        )

    @discord.ui.button(label="Textos", style=discord.ButtonStyle.secondary, row=3)
    async def texts(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.send_modal(VerifyTextsModal(self.guild_id))

    @discord.ui.button(label="Publicar / actualizar", style=discord.ButtonStyle.success, row=3)
    async def publish(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.pending_role_id is not None or self.pending_sin_role_id is not None or self.pending_channel_id is not None or self.pending_enabled is not None:
            await interaction.response.send_message("Guarda o descarta los cambios pendientes antes de publicar.", ephemeral=True)
            return
        channel_id = get_guild_channel_id(self.guild_id, "verification")
        channel = interaction.guild.get_channel(channel_id) if channel_id else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message("Configura primero un canal de verificación.", ephemeral=True)
            return
        role = interaction.guild.get_role(get_verify_role_id(self.guild_id))
        if role is None:
            await interaction.response.send_message("Configura primero un rol de verificación.", ephemeral=True)
            return
        problem = verify_role_problem(role, interaction.guild)
        if problem:
            await interaction.response.send_message(f"{role.mention} {problem}.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        ref = guild_config_get(self.guild_id, "verify_panel_ref")
        if ref and ref.count(":") == 1:
            try:
                old_channel_id, old_message_id = (int(x) for x in ref.split(":"))
                old_channel = interaction.guild.get_channel(old_channel_id)
                if isinstance(old_channel, discord.TextChannel):
                    old_message = await old_channel.fetch_message(old_message_id)
                    await old_message.edit(
                        content=render_vars(get_verify_panel_text(self.guild_id), VarContext(interaction.guild, None, old_channel), 2000),
                        view=VerifyView(label=get_verify_button_label(self.guild_id)),
                    )
                    await interaction.followup.send(f"Panel de verificación actualizado en {old_channel.mention}.", ephemeral=True)
                    return
            except (ValueError, discord.NotFound, discord.Forbidden, discord.HTTPException):
                pass
        message = await channel.send(
            content=render_vars(get_verify_panel_text(self.guild_id), VarContext(interaction.guild, None, channel), 2000),
            view=VerifyView(label=get_verify_button_label(self.guild_id)),
            allowed_mentions=discord.AllowedMentions.none(),
        )
        guild_config_set(self.guild_id, "verify_panel_ref", f"{channel.id}:{message.id}")
        await interaction.followup.send(f"Panel de verificación publicado en {channel.mention}.", ephemeral=True)

    @discord.ui.button(label="Activar / desactivar", style=discord.ButtonStyle.primary, row=3)
    async def toggle(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        current = self.pending_enabled if self.pending_enabled is not None else verify_enabled(self.guild_id)
        target = not current
        prospective_role_id = self.pending_role_id or get_verify_role_id(self.guild_id)
        if target and interaction.guild.get_role(prospective_role_id) is None:
            await interaction.response.send_message("Configura primero un rol de verificación.", ephemeral=True)
            return
        self.pending_enabled = target
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Configurar tiempos", style=discord.ButtonStyle.secondary, row=3)
    async def configure_times(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if any(value is not None for value in (
                self.pending_role_id, self.pending_sin_role_id,
                self.pending_channel_id, self.pending_enabled)):
            await interaction.response.send_message(
                "Guarda o descarta los cambios pendientes antes de editar los plazos.",
                ephemeral=True)
            return
        await interaction.response.send_modal(AgeVerificationTimeModal(self.guild_id))

    @discord.ui.button(label="Guardar cambios", style=discord.ButtonStyle.success, row=4)
    async def save_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if all(value is None for value in (
                self.pending_role_id, self.pending_sin_role_id,
                self.pending_channel_id, self.pending_enabled)):
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        if not await configuration_access(interaction, self.guild_id, self.owner_id):
            return
        guild = interaction.guild
        me = guild.me
        role_id = self.pending_role_id or get_verify_role_id(self.guild_id)
        role = guild.get_role(role_id)
        if self.pending_role_id is not None or self.pending_enabled is True:
            if role is None or verify_role_problem(role, guild):
                await interaction.response.send_message(
                    "El rol de verificación ya no es seguro o administrable. No se guardó nada.",
                    ephemeral=True)
                return
        if self.pending_sin_role_id is not None:
            sin_role = guild.get_role(self.pending_sin_role_id)
            if (sin_role is None or me is None or not me.guild_permissions.manage_roles
                    or sin_role.is_default() or sin_role.managed or sin_role >= me.top_role):
                await interaction.response.send_message(
                    "El rol Sin Verificar ya no es administrable. No se guardó nada.",
                    ephemeral=True)
                return
        channel = None
        if self.pending_channel_id is not None:
            channel = guild.get_channel(self.pending_channel_id)
            perms = channel.permissions_for(me) if isinstance(channel, discord.TextChannel) and me else None
            if perms is None or not (perms.view_channel and perms.send_messages
                                     and perms.read_message_history):
                await interaction.response.send_message(
                    "El canal ya no está disponible o faltan permisos de publicación. No se guardó nada.",
                    ephemeral=True)
                return
        if self.pending_enabled is True and not guild_config_get(self.guild_id, "verify_panel_ref"):
            await interaction.response.send_message(
                "Publica primero el panel de verificación para activar el sistema. No se guardó nada.",
                ephemeral=True)
            return
        changes: dict[str, str] = {}
        resources: dict[tuple[str, str], int] = {}
        if self.pending_role_id is not None:
            changes["verify_role_id"] = str(self.pending_role_id)
            resources[("role", "tentado")] = self.pending_role_id
        if self.pending_sin_role_id is not None:
            resources[("role", "sin_verificar")] = self.pending_sin_role_id
        if self.pending_channel_id is not None:
            changes["verify_channel_id"] = str(self.pending_channel_id)
            resources[("channel", "verification")] = self.pending_channel_id
        if self.pending_enabled is not None:
            changes["verify_enabled"] = "1" if self.pending_enabled else "0"
        await interaction.response.defer(ephemeral=True)
        try:
            applied = verification_atomic_setup_save(
                self.guild_id, self.original_settings, changes,
                self.original_resources, resources)
        except (sqlite3.Error, ValueError) as exc:
            await interaction.followup.send(
                f"No pude guardar la configuración: {type(exc).__name__}. No se aplicó el borrador.",
                ephemeral=True)
            return
        if not applied:
            await interaction.followup.send(
                "La configuración cambió en otra sesión. Abre nuevamente el editor; no sobrescribí nada.",
                ephemeral=True)
            return
        self.pending_role_id = self.pending_sin_role_id = self.pending_channel_id = self.pending_enabled = None
        self._refresh_origins()
        note = "Cambios guardados."
        if channel is not None:
            try:
                await _setup_publish_verification_panel(guild, channel)
            except discord.HTTPException:
                note = ("Configuración guardada, pero Discord rechazó actualizar la tarjeta. "
                        "Reintenta Publicar / actualizar. El panel anterior no se considera actualizado.")
        await interaction.edit_original_response(content=self._content(guild) + "\n\n" + note, view=self)

    @discord.ui.button(label="Descartar cambios", style=discord.ButtonStyle.danger, row=4)
    async def discard_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.pending_role_id = self.pending_sin_role_id = self.pending_channel_id = self.pending_enabled = None
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary, row=4)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if any(value is not None for value in (
                self.pending_role_id, self.pending_sin_role_id,
                self.pending_channel_id, self.pending_enabled)):
            await interaction.response.send_message(
                "Guarda o descarta los cambios pendientes antes de volver.", ephemeral=True)
            return
        await interaction.response.edit_message(
            content=verification_hub_content(self.guild_id), embed=None,
            view=HeraldoVerificationHubView(self.guild_id, self.owner_id))


class HeraldoRaidDetectionModal(discord.ui.Modal, title="Raid Protection · Detección"):
    threshold_input = discord.ui.TextInput(
        label="Umbral de entradas",
        required=True,
        max_length=4,
        placeholder="Ej.: 10 · ingresos que disparan la detección",
    )
    window_input = discord.ui.TextInput(
        label="Ventana de detección",
        required=True,
        max_length=24,
        placeholder="Ej.: 30s · tiempo para contar entradas",
    )
    age_input = discord.ui.TextInput(
        label="Edad máxima de cuenta nueva",
        required=True,
        max_length=24,
        placeholder="Ej.: 7d · 0 = no filtrar por antigüedad",
    )
    ratio_input = discord.ui.TextInput(
        label="Proporción mínima de cuentas nuevas (%)",
        required=True,
        max_length=3,
        placeholder="Ej.: 60 · 0 = sin proporción mínima",
    )
    duration_input = discord.ui.TextInput(
        label="Duración de la respuesta",
        required=True,
        max_length=24,
        placeholder="Ej.: 15m · modo raid, no duración de sanción",
    )

    def __init__(self, guild_id: int) -> None:
        super().__init__()
        self.guild_id = guild_id
        self.threshold_input.default = str(raid_threshold(guild_id))
        self.window_input.default = format_flex_duration(raid_window_seconds(guild_id))
        age = raid_min_age_seconds(guild_id)
        self.age_input.default = format_flex_duration(age) if age else "0"
        self.ratio_input.default = str(raid_new_account_ratio(guild_id))
        self.duration_input.default = format_flex_duration(raid_duration_seconds(guild_id))

    async def on_submit(self, interaction: discord.Interaction) -> None:
        try:
            threshold = int(str(self.threshold_input).strip())
            ratio = int(str(self.ratio_input).strip())
            if not RAID_THRESHOLD_MIN <= threshold <= RAID_THRESHOLD_MAX:
                raise ValueError(
                    f"El umbral debe estar entre {RAID_THRESHOLD_MIN} y {RAID_THRESHOLD_MAX}."
                )
            if not 0 <= ratio <= 100:
                raise ValueError("La proporción debe estar entre 0 y 100.")
            window_s = parse_flex_duration(
                str(self.window_input).strip(), RAID_WINDOW_MIN, RAID_WINDOW_MAX
            )
            age_s = parse_flex_duration(
                str(self.age_input).strip(), 0, RAID_AGE_MAX
            )
            duration_s = parse_flex_duration(
                str(self.duration_input).strip(), RAID_DURATION_MIN, RAID_DURATION_MAX
            )
            if ratio > 0 and age_s <= 0:
                raise ValueError(
                    "Si usas una proporción de cuentas nuevas, la edad máxima debe ser mayor que 0."
                )
        except ValueError as e:
            await interaction.response.send_message(f"Error: No guardé nada: {e}", ephemeral=True)
            return

        await confirm_configuration(interaction, self.guild_id, {'raid_threshold': str(threshold), 'raid_window_seconds': str(window_s), 'raid_min_age_seconds': str(age_s), 'raid_new_account_ratio': str(ratio), 'raid_duration_seconds': str(duration_s)})



RAID_PRESETS = {
    "moderada": (15, 30, 3 * 86400, 70, 600),
    "equilibrada": (10, 30, 7 * 86400, 60, 900),
    "estricta": (5, 10, 14 * 86400, 50, 1800),
}
RAID_FIELDS = (
    "raid_threshold", "raid_window_seconds", "raid_min_age_seconds",
    "raid_new_account_ratio", "raid_duration_seconds",
)
RAID_OPTIONS = {
    "raid_threshold": ("Umbral de entradas", (5, 10, 15, 20, 25, 50, 100),
                       "Número de entradas para disparar la detección."),
    "raid_window_seconds": ("Ventana de detección", (5, 10, 30, 60, 120, 300, 600),
                            "Tiempo para contar los ingresos."),
    "raid_min_age_seconds": ("Edad máxima de cuenta nueva", (0, 3600, 43200, 86400,
                              3*86400, 7*86400, 14*86400, 30*86400),
                              "0 = sin filtro. Determina qué cuentas se consideran recientes."),
    "raid_new_account_ratio": ("Proporción de cuentas nuevas", (0, 25, 40, 50, 60, 70, 80, 90),
                               "0 = desactivada. Porcentaje mínimo de cuentas recientes."),
    "raid_duration_seconds": ("Duración del modo raid", (60, 300, 600, 900, 1800, 3600, 7200,
                              21600, 43200, 86400),
                              "Duración del modo de protección, no de las sanciones."),
}


def raid_detection_values(guild_id):
    return dict(zip(RAID_FIELDS, (
        raid_threshold(guild_id), raid_window_seconds(guild_id),
        raid_min_age_seconds(guild_id), raid_new_account_ratio(guild_id),
        raid_duration_seconds(guild_id),
    )))


def raid_format_choice(key, value):
    if key == "raid_threshold":
        return f"{value} ingresos"
    if key == "raid_new_account_ratio":
        return f"{value} %" if value else "Desactivada"
    if key == "raid_min_age_seconds" and not value:
        return "Sin filtro"
    return format_flex_duration(value)


def raid_parse_choice(key, raw):
    if key in ("raid_threshold", "raid_new_account_ratio"):
        try:
            result = int(raw)
        except ValueError:
            raise ValueError("Introduce un número entero válido.") from None
        minimum, maximum = ((RAID_THRESHOLD_MIN, RAID_THRESHOLD_MAX)
                            if key == "raid_threshold" else (0, 100))
        if not minimum <= result <= maximum:
            raise ValueError(f"El valor debe estar entre {minimum} y {maximum}.")
        return result
    minimum, maximum = {
        "raid_window_seconds": (RAID_WINDOW_MIN, RAID_WINDOW_MAX),
        "raid_min_age_seconds": (0, RAID_AGE_MAX),
        "raid_duration_seconds": (RAID_DURATION_MIN, RAID_DURATION_MAX),
    }[key]
    return parse_flex_duration(raw, minimum, maximum)


class HeraldoRaidCustomModal(discord.ui.Modal):
    def __init__(self, editor, key):
        super().__init__(title="Raid Protection · Personalizar")
        self.editor, self.key = editor, key
        label = RAID_OPTIONS[key][0]
        current = editor.draft[key]
        self.value_field = discord.ui.TextInput(
            label=label[:45], max_length=32, required=True,
            default=(str(current) if key in ("raid_threshold", "raid_new_account_ratio")
                     else format_flex_duration(current) if current else "0"),
            placeholder="Ej.: 15, 60 %, 30s, 5m, 2h o 7d (según el campo)",
        )
        self.add_item(self.value_field)

    async def on_submit(self, interaction):
        if not await self.editor.interaction_check(interaction):
            return
        try:
            self.editor.draft[self.key] = raid_parse_choice(self.key, str(self.value_field).strip())
        except ValueError as exc:
            await interaction.response.send_message(f"No se aplicó el borrador: {exc}", ephemeral=True)
            return
        self.editor.rebuild()
        await interaction.response.edit_message(content=self.editor.summary(), view=self.editor)


class HeraldoRaidDetectionView(discord.ui.View):
    """Dos páginas con borrador, perfiles orientativos y guardado explícito."""

    def __init__(self, parent):
        super().__init__(timeout=900)
        self.parent, self.guild_id, self.owner_id = parent, parent.guild_id, parent.owner_id
        self.original = raid_detection_values(self.guild_id)
        self.draft = dict(self.original)
        self.page = 0
        self.selectors = {}
        self.rebuild()

    async def interaction_check(self, interaction):
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    def active_profile(self):
        for name, values in RAID_PRESETS.items():
            if tuple(self.draft[k] for k in RAID_FIELDS) == values:
                return name
        return "personalizada"

    def summary(self):
        items = []
        for key in RAID_FIELDS:
            suffix = " (pendiente)" if self.draft[key] != self.original[key] else ""
            items.append(f"**{RAID_OPTIONS[key][0]}:** "
                         f"{raid_format_choice(key, self.draft[key])}{suffix}")
        help_text = (
            "Elige un perfil orientativo o modifica cada parámetro. "
            "Una ventana más corta requiere entradas más concentradas."
            if self.page == 0 else
            "La proporción exige una edad de cuenta mayor que cero. "
            "La duración aquí NO termina una condena o baneo. "
            "«Solo registrar» evita sanciones, pero puede pausar invitaciones si así se configuró."
        )
        return ("**El Heraldo · Raid Protection · Detección**\n\n"
                f"**Perfil:** {self.active_profile().capitalize()}\n"
                + "\n".join(items) + "\n\n**Ayuda:** " + help_text
                + "\n\nGuardar cambios abre una confirmación antes de modificar la configuración.")

    def add_selector(self, key, row):
        title, choices, explanation = RAID_OPTIONS[key]
        current = self.draft[key]
        options = [
            discord.SelectOption(label=raid_format_choice(key, value)[:100],
                                 value=str(value), description=explanation[:100],
                                 default=value == current)
            for value in choices
        ]
        if current not in choices:
            options.append(discord.SelectOption(
                label=("Actual: " + raid_format_choice(key, current))[:100],
                value=str(current), description="Valor personalizado conservado",
                default=True))
        options.append(discord.SelectOption(
            label="Personalizar…", value="custom",
            description="Introducir otro valor sin guardarlo todavía"))
        selector = discord.ui.Select(
            placeholder=title + " · elige una opción", min_values=1,
            max_values=1, options=options, row=row)

        async def selected(interaction):
            value = selector.values[0]
            if value == "custom":
                await interaction.response.send_modal(HeraldoRaidCustomModal(self, key))
                return
            self.draft[key] = int(value)
            self.rebuild()
            await interaction.response.edit_message(content=self.summary(), view=self)

        selector.callback = selected
        self.selectors[key] = selector
        self.add_item(selector)

    def add_button(self, label, color, handler, row):
        button = discord.ui.Button(label=label, style=color, row=row)
        button.callback = handler
        self.add_item(button)
        return button

    def rebuild(self):
        self.clear_items()
        self.selectors = {}
        if self.page == 0:
            profile_select = discord.ui.Select(
                placeholder="Sensibilidad · elige según la actividad de tu servidor",
                options=[
                    discord.SelectOption(
                        label=name.capitalize(), value=name,
                        description={
                            "moderada": "Menos falsas alarmas; menor detección de ataques lentos.",
                            "equilibrada": "Compromiso sugerido; ajustar con las alertas reales.",
                            "estricta": "Reacciona antes; puede afectar entradas legítimas.",
                        }[name], default=self.active_profile() == name)
                    for name in RAID_PRESETS
                ] + [discord.SelectOption(
                    label="Personalizada", value="personalizada",
                    description="Conservar los valores elegidos manualmente",
                    default=self.active_profile() == "personalizada")],
                min_values=1, max_values=1, row=0)
            async def profile_selected(interaction):
                key = profile_select.values[0]
                if key in RAID_PRESETS:
                    self.draft = dict(zip(RAID_FIELDS, RAID_PRESETS[key]))
                self.rebuild()
                await interaction.response.edit_message(content=self.summary(), view=self)
            profile_select.callback = profile_selected
            self.profile_select = profile_select
            self.add_item(profile_select)
            for idx, key in enumerate(RAID_FIELDS[:3], start=1):
                self.add_selector(key, idx)
            row = 4
            self.add_button("Más ajustes", discord.ButtonStyle.primary, self.next_page, row)
        else:
            for idx, key in enumerate(RAID_FIELDS[3:]):
                self.add_selector(key, idx)
            row = 2
            self.add_button("Parámetros básicos", discord.ButtonStyle.secondary, self.basic_page, row)
        save = self.add_button("Guardar cambios", discord.ButtonStyle.success, self.save, row)
        discard = self.add_button("Descartar cambios", discord.ButtonStyle.danger, self.discard, row)
        save.disabled = discard.disabled = self.draft == self.original
        self.add_button("Volver", discord.ButtonStyle.secondary, self.back, row)

    async def next_page(self, interaction):
        self.page = 1
        self.rebuild()
        await interaction.response.edit_message(content=self.summary(), view=self)

    async def basic_page(self, interaction):
        self.page = 0
        self.rebuild()
        await interaction.response.edit_message(content=self.summary(), view=self)

    async def discard(self, interaction):
        self.draft = dict(self.original)
        self.rebuild()
        await interaction.response.edit_message(content=self.summary(), view=self)

    async def back(self, interaction):
        await interaction.response.edit_message(
            content=self.parent._content(interaction.guild), view=self.parent)
        self.stop()

    async def save(self, interaction):
        changes = {k: str(value) for k, value in self.draft.items()
                   if value != self.original[k]}
        if not changes:
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        if self.draft["raid_new_account_ratio"] > 0 and self.draft["raid_min_age_seconds"] == 0:
            await interaction.response.send_message(
                "No se guardó: la proporción exige una edad de cuenta mayor que cero.",
                ephemeral=True)
            return
        if raid_detection_values(self.guild_id) != self.original:
            await interaction.response.send_message(
                "La configuración cambió en otra sesión. Abre de nuevo el editor.",
                ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id, changes)


class HeraldoRaidSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.pending_action: str | None = None
        self.pending_role_id: int | None = None
        self.pending_enabled: bool | None = None
        self.pending_invites: bool | None = None
        self.pending_purge: bool | None = None

        action_select = discord.ui.Select(
            placeholder="Acción cuando se detecte un raid; Guardar para aplicar",
            min_values=1,
            max_values=1,
            options=[
                discord.SelectOption(
                    label=label,
                    value=value,
                    description=RAID_ACTION_HELP[value],
                    default=(value == raid_action(guild_id)),
                )
                for value, label in RAID_ACTION_LABELS.items()
            ],
            row=0,
        )
        action_select.callback = self.select_action
        self.action_select = action_select
        self.add_item(action_select)

        role_select = discord.ui.RoleSelect(
            placeholder="Rol opcional para avisos; no es el rol Condenado",
            min_values=1,
            max_values=1,
            row=1,
        )
        role_select.callback = self.select_alert_role
        self.add_item(role_select)

        self.toggle_enabled.label = "Protección activada" if raid_enabled(guild_id) else "Protección desactivada"
        self.toggle_invites.label = "Pausar invitaciones: sí" if raid_lock_invites_enabled(guild_id) else "Pausar invitaciones: no"
        self.toggle_purge.label = "Purgar mensajes: sí" if raid_purge_enabled(guild_id) else "Purgar mensajes: no"

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de configuración no es tuyo.", ephemeral=True)
            return False
        return True

    def _sync_action_select(self) -> None:
        """Mantiene marcada la acción del borrador; solo Guardar la hace efectiva."""
        selected = self.pending_action if self.pending_action is not None else raid_action(self.guild_id)
        for option in self.action_select.options:
            option.default = option.value == selected

    def _content(self, guild: discord.Guild) -> str:
        items = []
        if self.pending_action is not None:
            items.append(f"Respuesta → {RAID_ACTION_LABELS.get(self.pending_action, self.pending_action)}")
        if self.pending_role_id is not None:
            role = guild.get_role(self.pending_role_id)
            items.append(f"Rol de alertas → {role.mention if role else self.pending_role_id}")
        if self.pending_enabled is not None:
            items.append(f"Protección → {'activa' if self.pending_enabled else 'desactivada'}")
        if self.pending_invites is not None:
            items.append(f"Pausar invitaciones → {'sí' if self.pending_invites else 'no'}")
        if self.pending_purge is not None:
            items.append(f"Purgar mensajes → {'sí' if self.pending_purge else 'no'}")
        return "**El Heraldo · Raid Protection**\n\n" + raid_config_summary(guild) + _pending_config_text(items)

    async def select_action(self, interaction: discord.Interaction) -> None:
        value = self.action_select.values[0]
        if value == "condemn" and interaction.guild.get_role(condemnation_role_id(guild_id=self.guild_id)) is None:
            await interaction.response.send_message("Para usar «Condenar» primero debes configurar el rol Condenado.", ephemeral=True)
            return
        self.pending_action = value
        self._sync_action_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    async def select_alert_role(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        role = interaction.guild.get_role(int(values[0])) if interaction.guild and values else None
        if role is None:
            await interaction.response.send_message("No pude localizar ese rol.", ephemeral=True)
            return
        self.pending_role_id = role.id
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Detección y duración", style=discord.ButtonStyle.primary, row=2)
    async def detection(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        editor = HeraldoRaidDetectionView(self)
        await interaction.response.edit_message(content=editor.summary(), view=editor)

    @discord.ui.button(label="Protección", style=discord.ButtonStyle.success, row=2)
    async def toggle_enabled(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        current = self.pending_enabled if self.pending_enabled is not None else raid_enabled(self.guild_id)
        self.pending_enabled = not current
        self.toggle_enabled.label = "Protección activada" if self.pending_enabled else "Protección desactivada"
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Pausar invitaciones", style=discord.ButtonStyle.secondary, row=3)
    async def toggle_invites(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        current = self.pending_invites if self.pending_invites is not None else raid_lock_invites_enabled(self.guild_id)
        self.pending_invites = not current
        self.toggle_invites.label = "Pausar invitaciones: sí" if self.pending_invites else "Pausar invitaciones: no"
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Purgar mensajes", style=discord.ButtonStyle.secondary, row=3)
    async def toggle_purge(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        current = self.pending_purge if self.pending_purge is not None else raid_purge_enabled(self.guild_id)
        self.pending_purge = not current
        self.toggle_purge.label = "Purgar mensajes: sí" if self.pending_purge else "Purgar mensajes: no"
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Guardar cambios", style=discord.ButtonStyle.success, row=4)
    async def save_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if all(v is None for v in (self.pending_action, self.pending_role_id, self.pending_enabled, self.pending_invites, self.pending_purge)):
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        if self.pending_action is not None:
            guild_config_set(self.guild_id, "raid_action", self.pending_action)
        if self.pending_role_id is not None:
            guild_config_set(self.guild_id, "raid_ping_role", str(self.pending_role_id))
        if self.pending_enabled is not None:
            guild_config_set(self.guild_id, "raid_enabled", "1" if self.pending_enabled else "0")
        if self.pending_invites is not None:
            guild_config_set(self.guild_id, "raid_lock_invites", "1" if self.pending_invites else "0")
        if self.pending_purge is not None:
            guild_config_set(self.guild_id, "raid_purge", "1" if self.pending_purge else "0")
        self.pending_action = self.pending_role_id = self.pending_enabled = self.pending_invites = self.pending_purge = None
        self._sync_action_select()
        await interaction.edit_original_response(content=self._content(interaction.guild) + "\n\nCambios guardados.", view=self)

    @discord.ui.button(label="Descartar cambios", style=discord.ButtonStyle.danger, row=4)
    async def discard_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.pending_action = self.pending_role_id = self.pending_enabled = self.pending_invites = self.pending_purge = None
        self._sync_action_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary, row=4)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await heraldo_setup_go_home(interaction, self.guild_id, self.owner_id)


class VerifyDmEditorContentModal(discord.ui.Modal):
    """Editor del contenido principal del DM que se envía al verificarse."""

    def __init__(self, guild_id: int) -> None:
        super().__init__(title="DM de verificación · Contenido")
        self.guild_id = guild_id
        self.title_input = discord.ui.TextInput(
            label="Título",
            default=get_verify_dm_title(guild_id),
            required=True,
            max_length=256,
        )
        self.field_input = discord.ui.TextInput(
            label="Nombre del campo",
            default=get_verify_dm_field_name(guild_id),
            required=True,
            max_length=256,
        )
        self.body_input = discord.ui.TextInput(
            label="Mensaje",
            style=discord.TextStyle.paragraph,
            default=get_verify_dm_body(guild_id),
            required=True,
            max_length=4000,
        )
        self.footer_input = discord.ui.TextInput(
            label="Pie del embed",
            default=get_verify_dm_footer(guild_id),
            required=True,
            max_length=2048,
        )
        self.color_input = discord.ui.TextInput(
            label="Color HEX",
            default=get_verify_dm_color(guild_id),
            required=True,
            max_length=7,
            placeholder="4F5BDC",
        )
        for item in (
            self.title_input,
            self.field_input,
            self.body_input,
            self.footer_input,
            self.color_input,
        ):
            self.add_item(item)

    async def on_submit(self, interaction: discord.Interaction) -> None:
        color = self.color_input.value.strip().lstrip("#")
        if not re.fullmatch(r"[0-9a-fA-F]{6}", color):
            await interaction.response.send_message(
                "Error: El color debe ser HEX de 6 caracteres, por ejemplo `4F5BDC`.",
                ephemeral=True,
            )
            return

        values = {
            "verify_dm_title": self.title_input.value.strip(),
            "verify_dm_field_name": self.field_input.value.strip(),
            "verify_dm_body": self.body_input.value.strip(),
            "verify_dm_footer": self.footer_input.value.strip(),
            "verify_dm_color": color.upper(),
        }
        if not all(values.values()):
            await interaction.response.send_message(
                "Error: Ningún campo puede quedar vacío.",
                ephemeral=True,
            )
            return

        await confirm_configuration(interaction, self.guild_id, values)


