class HeraldoMessageConfirmView(discord.ui.View):
    """Los modales solo preparan cambios; el administrador decide aplicarlos."""
    def __init__(self, guild_id: int, owner_id: int, operation: str, payload: dict):
        super().__init__(timeout=300)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.operation, self.payload = operation, payload
        self.original_templates = copy.deepcopy(heraldo_template_list(guild_id))
        self.original_components = copy.deepcopy(heraldo_message_role_config(guild_id))
        self.finished = False
        for child in self.children:
            if isinstance(child, discord.ui.Button) and child.label == "Guardar cambios" and operation == "delete":
                child.label = "Confirmar eliminación"
                child.style = discord.ButtonStyle.danger
            elif isinstance(child, discord.ui.Button) and child.label == "Guardar cambios" and operation == "kit":
                child.label = "Confirmar importación"

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message("Esta confirmación no te pertenece.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Guardar cambios", style=discord.ButtonStyle.success)
    async def commit(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await configuration_access(interaction, self.guild_id, self.owner_id):
            return
        if self.finished:
            await interaction.response.send_message("Esta propuesta ya fue resuelta.", ephemeral=True)
            return
        if (heraldo_template_list(self.guild_id) != self.original_templates
                or heraldo_message_role_config(self.guild_id) != self.original_components):
            await interaction.response.send_message("La configuración cambió. Abra de nuevo el editor antes de guardar.", ephemeral=True)
            return
        op, payload = self.operation, self.payload
        if op in {"template", "raw", "attach", "delete"}:
            items = heraldo_template_list(self.guild_id)
            if op == "template":
                old_name, item = payload["old_name"], payload["item"]
                if old_name and not any(t["name"] == old_name for t in items):
                    await interaction.response.send_message("La plantilla original ya no existe.", ephemeral=True)
                    return
                if any(t["name"].casefold() == item["name"].casefold() and t["name"] != old_name for t in items):
                    await interaction.response.send_message("Ya existe una plantilla con ese nombre.", ephemeral=True)
                    return
                items = [t for t in items if t["name"] != old_name] if old_name else items
                if len(items) >= 25:
                    await interaction.response.send_message("Se alcanzó el límite de plantillas.", ephemeral=True)
                    return
                items.append(item)
            else:
                target = next((t for t in items if t["name"] == payload["name"]), None)
                if not target:
                    await interaction.response.send_message("La plantilla ya no existe.", ephemeral=True)
                    return
                if op == "delete":
                    items = [t for t in items if t["name"] != payload["name"]]
                elif op == "raw":
                    for key in message_payload.VISUAL_KEYS:
                        target.pop(key, None)
                    target.update(payload["values"])
                elif op == "attach":
                    mode, component = payload["mode"], payload["component"]
                    if mode == "boton" and not any(x["label"] == component for x in heraldo_message_role_config(self.guild_id)):
                        await interaction.response.send_message("El componente fue retirado. No se guardó.", ephemeral=True)
                        return
                    target["role_component"] = component if mode == "boton" else ""
                    target["role_component_mode"] = mode
            if op in {"template", "raw"}:
                candidate = item if op == "template" else target
                try:
                    message_payload.validate({k: v for k, v in candidate.items() if k in message_payload.VISUAL_KEYS})
                except ValueError as exc:
                    await interaction.response.send_message(f"No se guardó la plantilla: {exc}", ephemeral=True)
                    return
            heraldo_template_save(self.guild_id, items)
        elif op == "component":
            components = heraldo_message_role_config(self.guild_id)
            item = payload["item"]
            role, me = interaction.guild.get_role(item["role_id"]), interaction.guild.me
            if not role or not me or role.is_default() or role.managed or role >= me.top_role or not me.guild_permissions.manage_roles or not self_service_role_safe(role):
                await interaction.response.send_message("Ya no es posible gestionar ese rol.", ephemeral=True)
                return
            if len(components) >= 20 or any(x["label"].casefold() == item["label"].casefold() for x in components):
                await interaction.response.send_message("Límite alcanzado o nombre duplicado.", ephemeral=True)
                return
            components.append(item)
            guild_config_set(self.guild_id, "message_role_components", json.dumps(components, ensure_ascii=False))
        elif op == "kit":
            items = heraldo_template_list(self.guild_id)
            new = payload["items"]
            names = {x["name"].casefold() for x in items}
            if payload.get("replace"):
                incoming_names = {x["name"].casefold() for x in new}
                items = [x for x in items if x['name'].casefold() not in incoming_names]
                names = {x['name'].casefold() for x in items}
            if len(items) + len(new) > 25 or any(t["name"].casefold() in names for t in new):
                await interaction.response.send_message("Las plantillas han cambiado. Revisa el kit antes de reintentarlo.", ephemeral=True)
                return
            heraldo_template_save(self.guild_id, items + new)
        else:
            await interaction.response.send_message("Operación no admitida.", ephemeral=True)
            return
        self.finished = True
        self.stop()
        await interaction.response.edit_message(content="Cambios guardados por confirmación del administrador. Los mensajes publicados no se modifican automáticamente.", view=None)

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.finished = True
        self.stop()
        await interaction.response.edit_message(content="Operación cancelada. No se guardó ningún cambio.", view=None)


async def heraldo_message_request_confirmation(interaction: discord.Interaction, guild_id: int,
                                               owner_id: int, operation: str, payload: dict, summary: str):
    await interaction.response.send_message(
        "**El Heraldo · Cambios pendientes**\n\n" + summary +
        "\n\nRevisa la operación y utiliza el botón de confirmación para ejecutarla, o **Cancelar** para descartarla.",
        view=HeraldoMessageConfirmView(guild_id, owner_id, operation, payload),
        ephemeral=True, allowed_mentions=discord.AllowedMentions.none(),
    )


# Mensajes reutilizables por servidor. No modifica mensajes operativos del bot.
def heraldo_template_list(guild_id: int) -> list[dict]:
    try:
        value = json.loads(guild_config_get(guild_id, "message_custom_templates") or "[]")
        return [x for x in value if isinstance(x, dict) and isinstance(x.get("name"), str)][:25] if isinstance(value, list) else []
    except (ValueError, TypeError):
        return []


def heraldo_template_save(guild_id: int, templates: list[dict]) -> None:
    guild_config_set(guild_id, "message_custom_templates", json.dumps(templates, ensure_ascii=False))


def heraldo_template_embed(template: dict) -> discord.Embed | None:
    title = template.get("title", "")
    description = template.get("description", "")
    image = template.get("image", "")
    if not title and not description and not image:
        return None
    embed = discord.Embed(title=title or None, description=description or None, color=0x2B2D31)
    if image:
        embed.set_image(url=image)
    return embed


def heraldo_template_payload(template, guild, member=None, channel=None):
    context = {"servidor": guild.name, "servidor_id": str(guild.id),
               "usuario": getattr(member, "display_name", "Miembro"),
               "usuario_id": str(getattr(member, "id", "")),
               "canal": getattr(channel, "name", "canal"),
               "fecha": datetime.now(timezone.utc).isoformat(timespec="minutes")}
    content, embeds = message_payload.render(template, context)
    return {"content": content, "embeds": message_payload.TemplateEmbeds(discord.Embed.from_dict(e) for e in embeds),
            "view": heraldo_template_view(dict(template, _guild_id=guild.id)),
            "allowed_mentions": discord.AllowedMentions.none()}


def heraldo_template_view(template: dict) -> discord.ui.View | None:
    if template.get('componentes'):
        return message_components.build_view(template, int(template['_guild_id']))
    label, url = template.get("button_label", ""), template.get("button_url", "")
    view = discord.ui.View(timeout=None)
    if label and url:
        view.add_item(discord.ui.Button(label=label, url=url))
    component_name = template.get("role_component", "")
    component = next((x for x in heraldo_message_role_config(int(template.get("_guild_id", 0))) if x["label"] == component_name), None)
    if template.get("role_component_mode") == "menu":
        configs = heraldo_message_role_config(int(template.get("_guild_id", 0)))
        if configs:
            view.add_item(HeraldoMessageRoleSelect(configs, int(template["_guild_id"])))
    elif component:
        view.add_item(HeraldoMessageRoleButton(component, int(template["_guild_id"])))
    return view if view.children else None


class HeraldoTemplateModal(discord.ui.Modal, title="Editor de plantilla"):
    name = discord.ui.TextInput(label="Nombre único", max_length=70)
    title_text = discord.ui.TextInput(label="Título del embed (opcional)", required=False, max_length=256)
    description = discord.ui.TextInput(label="Contenido", style=discord.TextStyle.paragraph, required=False, max_length=2000)
    image = discord.ui.TextInput(label="URL de imagen (opcional)", required=False, max_length=400)
    button = discord.ui.TextInput(label="Botón enlace: Etiqueta | https://...", required=False, max_length=400)

    def __init__(self, guild_id: int, owner_id: int, old_name: str | None = None):
        super().__init__()
        self.guild_id, self.owner_id, self.old_name = guild_id, owner_id, old_name
        old = next((x for x in heraldo_template_list(guild_id) if x["name"] == old_name), None)
        if old:
            self.name.default = old["name"]
            self.title_text.default = old.get("title", "")
            self.description.default = old.get("description", "")
            self.image.default = old.get("image", "")
            if old.get("button_url"):
                self.button.default = old.get("button_label", "") + " | " + old["button_url"]

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner_id or interaction.guild_id != self.guild_id:
            await interaction.response.send_message("No tienes acceso a este editor.", ephemeral=True)
            return
        name, title, description = str(self.name).strip(), str(self.title_text).strip(), str(self.description).strip()
        image, button = str(self.image).strip(), str(self.button).strip()
        if not name or not (title or description or image):
            await interaction.response.send_message("Indica un nombre y un contenido o imagen.", ephemeral=True)
            return
        if image and not re.match(r"^https://[^\s]+$", image, re.I):
            await interaction.response.send_message("La imagen requiere una URL HTTPS válida.", ephemeral=True)
            return
        label, url = "", ""
        if button:
            label, sep, url = button.partition("|")
            label, url = label.strip(), url.strip()
            if not sep or not label or len(label) > 80 or not re.match(r"^https://[^\s]+$", url, re.I):
                await interaction.response.send_message("Usa Etiqueta | https://direccion para el botón.", ephemeral=True)
                return
        items = heraldo_template_list(self.guild_id)
        if any(x["name"].casefold() == name.casefold() and x["name"] != self.old_name for x in items):
            await interaction.response.send_message("Ya existe una plantilla con ese nombre.", ephemeral=True)
            return
        if self.old_name:
            items = [x for x in items if x["name"] != self.old_name]
        if len(items) >= 25:
            await interaction.response.send_message("Se alcanzó el máximo de 25 plantillas.", ephemeral=True)
            return
        old = next((x for x in heraldo_template_list(self.guild_id) if x["name"] == self.old_name), None)
        old_component = old.get("role_component", "") if old else ""
        old_mode = old.get("role_component_mode", "boton") if old else "boton"
        item = dict(old or {}, name=name, title=title, description=description, image=image,
                    button_label=label, button_url=url, role_component=old_component, role_component_mode=old_mode)
        if item.get("embeds"):
            item["embeds"][0].update(title=title, description=description)
            if image:
                item["embeds"][0]["image"] = {"url": image}
            else:
                item["embeds"][0].pop("image", None)
        await heraldo_message_request_confirmation(interaction, self.guild_id, self.owner_id,
            "template", {"old_name": self.old_name, "item": item},
            "Plantilla: **" + discord.utils.escape_markdown(name) + "**. La configuración todavía no se ha guardado.")



class HeraldoTemplateRawModal(discord.ui.Modal, title="Edición JSON de plantilla"):
    raw = discord.ui.TextInput(label="JSON de la plantilla", style=discord.TextStyle.paragraph, max_length=4000)

    def __init__(self, guild_id: int, owner_id: int, selected: str, template: dict):
        super().__init__()
        self.guild_id, self.owner_id, self.selected = guild_id, owner_id, selected
        raw = json.dumps({k: v for k, v in template.items() if k in message_payload.VISUAL_KEYS}, ensure_ascii=False, indent=2)
        self.raw.default = raw if len(raw) <= 4000 else '{"content": ""}'

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message("Acceso denegado.", ephemeral=True)
            return
        try:
            values = json.loads(str(self.raw))
            values = message_payload.validate(values)
        except (ValueError, TypeError):
            await interaction.response.send_message("JSON inválido. Usa exclusivamente las propiedades admitidas, dentro de sus límites.", ephemeral=True)
            return
        templates = heraldo_template_list(self.guild_id)
        target = next((x for x in templates if x["name"] == self.selected), None)
        if target is None:
            await interaction.response.send_message("La plantilla ya no existe.", ephemeral=True)
            return
        await heraldo_message_request_confirmation(interaction, self.guild_id, self.owner_id,
            "raw", {"name": self.selected, "values": values},
            "Edición JSON de **" + discord.utils.escape_markdown(self.selected) + "** pendiente de confirmación.")


class HeraldoTemplateSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int, selected: str | None = None):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        templates = heraldo_template_list(guild_id)
        self.selected = selected if any(x["name"] == selected for x in templates) else (templates[0]["name"] if templates else None)
        self.channel_id = None
        if templates:
            choose = discord.ui.Select(
                placeholder="Seleccionar plantilla",
                options=[discord.SelectOption(label=t["name"][:100], value=str(i),
                    default=t["name"] == self.selected) for i, t in enumerate(templates)],
                row=0,
            )
            choose.callback = self.choose
            self.add_item(choose)
        channel = discord.ui.ChannelSelect(placeholder="Canal para publicar la plantilla",
                                           channel_types=[discord.ChannelType.text], row=1)
        channel.callback = self.channel_selected
        self.add_item(channel)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id or interaction.guild_id != self.guild_id:
            await interaction.response.send_message("Este panel de configuración no es tuyo.", ephemeral=True)
            return False
        return True

    def _current(self) -> dict | None:
        return next((t for t in heraldo_template_list(self.guild_id) if t["name"] == self.selected), None)

    async def choose(self, interaction: discord.Interaction):
        values = (interaction.data or {}).get("values", [])
        templates = heraldo_template_list(self.guild_id)
        index = int(values[0]) if values and values[0].isdigit() else -1
        if index < 0 or index >= len(templates):
            await interaction.response.send_message("Plantilla no disponible.", ephemeral=True)
            return
        chosen = templates[index]
        await interaction.response.edit_message(
            content="**El Heraldo · Plantillas**\n\nSeleccionada: **" + discord.utils.escape_markdown(chosen["name"]) + "**",
            embed=heraldo_template_embed(chosen),
            view=HeraldoTemplateSetupView(self.guild_id, self.owner_id, chosen["name"]),
        )

    async def channel_selected(self, interaction: discord.Interaction):
        values = (interaction.data or {}).get("values", [])
        self.channel_id = int(values[0]) if values else None
        await interaction.response.defer()

    @discord.ui.button(label="Crear", style=discord.ButtonStyle.primary, row=2)
    async def create(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(HeraldoTemplateModal(self.guild_id, self.owner_id))

    @discord.ui.button(label="Editar", style=discord.ButtonStyle.primary, row=2)
    async def edit(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not self._current():
            await interaction.response.send_message("Primero crea una plantilla.", ephemeral=True)
            return
        await interaction.response.send_modal(HeraldoTemplateModal(self.guild_id, self.owner_id, self.selected))

    @discord.ui.button(label="Vincular botón", style=discord.ButtonStyle.primary, row=2)
    async def attach(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not self._current():
            await interaction.response.send_message("Primero crea una plantilla.", ephemeral=True)
            return
        await interaction.response.send_modal(HeraldoAttachRoleModal(self.guild_id, self.owner_id, self.selected))

    @discord.ui.button(label="Publicar", style=discord.ButtonStyle.success, row=2)
    async def publish(self, interaction: discord.Interaction, button: discord.ui.Button):
        template = self._current()
        channel = interaction.guild.get_channel(self.channel_id) if self.channel_id else None
        if not template or not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message("Selecciona una plantilla y un canal válido.", ephemeral=True)
            return
        me = interaction.guild.me
        user_perms = channel.permissions_for(interaction.user)
        if not user_perms.view_channel or not user_perms.send_messages:
            await interaction.response.send_message("No dispone de acceso para publicar en ese canal.", ephemeral=True)
            return
        if not me or not channel.permissions_for(me).send_messages or not channel.permissions_for(me).embed_links:
            await interaction.response.send_message("El Heraldo necesita Enviar mensajes e Insertar enlaces en ese canal.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        try:
            await channel.send(**heraldo_template_payload(template, interaction.guild, interaction.user, channel))
        except (discord.HTTPException, ValueError):
            await interaction.followup.send("No fue posible publicar la plantilla. Comprueba permisos y formato.", ephemeral=True)
            return
        await interaction.followup.send(f"Plantilla publicada en {channel.mention}.", ephemeral=True)

    @discord.ui.button(label="JSON", style=discord.ButtonStyle.secondary, row=3)
    async def edit_raw(self, interaction: discord.Interaction, button: discord.ui.Button):
        current = self._current()
        if not current:
            await interaction.response.send_message("Primero crea una plantilla.", ephemeral=True)
            return
        raw = json.dumps({k: v for k, v in current.items() if k in message_payload.VISUAL_KEYS}, ensure_ascii=False, indent=2)
        if len(raw) > 4000:
            await interaction.response.send_message("Esta plantilla supera el tamaño del formulario. Exporte el kit y use /importkit con reemplazo para revisarla sin truncar contenido.", ephemeral=True)
            return
        await interaction.response.send_modal(HeraldoTemplateRawModal(self.guild_id, self.owner_id, self.selected, current))

    @discord.ui.button(label="Variables", style=discord.ButtonStyle.secondary, row=3)
    async def variables(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_message("Variables: {usuario}, {usuario_id}, {servidor}, {servidor_id}, {canal} y {fecha} (UTC). Se resuelven al publicar; las menciones automáticas están desactivadas. JSON admite content y hasta diez embeds con campos, autor, pie, imagen y miniatura.", ephemeral=True)

    @discord.ui.button(label="Vista previa", style=discord.ButtonStyle.secondary, row=4)
    async def preview(self, interaction, button):
        current = self._current()
        if not current:
            await interaction.response.send_message("Seleccione una plantilla.", ephemeral=True)
            return
        try:
            payload = heraldo_template_payload(current, interaction.guild, interaction.user, interaction.channel)
            if payload['view']:
                for child in payload['view'].children:
                    child.disabled = True
            await interaction.response.send_message(**payload, ephemeral=True)
        except ValueError as exc:
            await interaction.response.send_message(str(exc), ephemeral=True)

    @discord.ui.button(label="Eliminar", style=discord.ButtonStyle.danger, row=3)
    async def delete(self, interaction: discord.Interaction, button: discord.ui.Button):
        template = self._current()
        if not template:
            await interaction.response.send_message("No hay una plantilla seleccionada.", ephemeral=True)
            return
        await heraldo_message_request_confirmation(interaction, self.guild_id, self.owner_id,
            "delete", {"name": self.selected},
            "Solicitas eliminar **" + discord.utils.escape_markdown(self.selected) + "**. Esta acción requiere confirmación.")

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary, row=3)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.edit_message(
            content=heraldo_messages_setup_content(), embed=None,
            view=HeraldoMessagesSetupView(self.guild_id, self.owner_id),
        )



# Componentes de mensajes: gestión persistente de roles con comprobación de jerarquías.
def heraldo_message_role_config(guild_id: int) -> list[dict]:
    try:
        data = json.loads(guild_config_get(guild_id, "message_role_components") or "[]")
    except (TypeError, ValueError):
        return []
    return [x for x in data if isinstance(x, dict) and x.get("role_id") and x.get("label")][:20] if isinstance(data, list) else []


class HeraldoMessageRoleModal(discord.ui.Modal, title="Nuevo componente de roles"):
    label_text = discord.ui.TextInput(label="Etiqueta", max_length=70)
    role_text = discord.ui.TextInput(label="ID del rol del servidor", max_length=22)
    action_text = discord.ui.TextInput(label="Acción: añadir, quitar o alternar", default="alternar", max_length=12)

    def __init__(self, guild_id: int, owner_id: int):
        super().__init__()
        self.guild_id, self.owner_id = guild_id, owner_id

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message("Acceso denegado.", ephemeral=True)
            return
        label = str(self.label_text).strip()
        raw_id = str(self.role_text).strip()
        action = str(self.action_text).strip().casefold()
        if not raw_id.isdecimal() or action not in {"añadir", "quitar", "alternar"}:
            await interaction.response.send_message("Indica un ID válido y una acción admitida.", ephemeral=True)
            return
        role = interaction.guild.get_role(int(raw_id))
        me = interaction.guild.me
        if not role or role.is_default() or role.managed or not me or role >= me.top_role:
            await interaction.response.send_message("El rol no existe o no puede ser administrado por El Heraldo.", ephemeral=True)
            return
        components = heraldo_message_role_config(self.guild_id)
        if len(components) >= 20:
            await interaction.response.send_message("Se alcanzó el límite de componentes de roles.", ephemeral=True)
            return
        if any(x["label"].casefold() == label.casefold() for x in components):
            await interaction.response.send_message("Ya existe un componente con ese nombre.", ephemeral=True)
            return
        await heraldo_message_request_confirmation(interaction, self.guild_id, self.owner_id,
            "component", {"item": {"label": label, "role_id": role.id, "action": action}},
            "Componente **" + discord.utils.escape_markdown(label) + "** y acción **" + action + "** pendientes.")


