def self_service_role_safe(role: discord.Role) -> bool:
    """Los componentes públicos no conceden permisos de administración."""
    forbidden = ("administrator", "manage_guild", "manage_roles", "manage_channels",
                 "manage_webhooks", "ban_members", "kick_members", "moderate_members")
    return not any(getattr(role.permissions, permission, False) for permission in forbidden)



def heraldo_message_role_access(
    guild: discord.Guild, member: discord.Member, role_id: int, action: str,
) -> tuple[discord.Role | None, str | None]:
    """Revalidación antes Y después de llamadas de red en componentes públicos."""
    permitted = any(
        int(item["role_id"]) == role_id and item.get("action", "alternar") == action
        for item in heraldo_message_role_config(guild.id)
    )
    if not permitted:
        return None, "Este componente ya no está configurado para esa acción."
    role, me = guild.get_role(role_id), guild.me
    if role is None:
        return None, "El rol configurado ya no existe."
    if me is None or not me.guild_permissions.manage_roles:
        return None, "El Heraldo necesita el permiso Gestionar roles."
    if role.is_default() or role.managed:
        return None, "Este rol no puede asignarse mediante un componente público."
    if role >= me.top_role:
        return None, "El rol está al mismo nivel o por encima del rol más alto de El Heraldo."
    if not self_service_role_safe(role):
        return None, "El rol contiene permisos administrativos y no puede asignarse mediante un componente público."
    if condemnation_get(guild.id, member.id):
        return None, "No puede modificar sus roles mientras exista una condena activa."
    return role, None


_message_role_busy: set[tuple[int, int]] = set()
_message_role_cooldown: dict[tuple[int, int], float] = {}


async def heraldo_message_role_action(interaction: discord.Interaction, guild_id: int, role_id: int, action: str):
    guild = interaction.guild
    if not guild or guild.id != guild_id or not isinstance(interaction.user, discord.Member):
        await interaction.response.send_message("Acción no disponible fuera del servidor.", ephemeral=True)
        return
    role, denial = heraldo_message_role_access(guild, interaction.user, role_id, action)
    if denial:
        await interaction.response.send_message(denial, ephemeral=True)
        return
    member = interaction.user
    key = (guild.id, member.id)
    now = time.monotonic()
    for expired_key, until in list(_message_role_cooldown.items()):
        if until <= now:
            _message_role_cooldown.pop(expired_key, None)
    if key in _message_role_busy or key in _message_role_cooldown:
        await interaction.response.send_message("Espere unos segundos antes de volver a modificar sus roles.", ephemeral=True)
        return
    _message_role_busy.add(key)
    try:
        await interaction.response.defer(ephemeral=True)
        member = await guild.fetch_member(member.id)
        # Los permisos, rol o estado de condena pueden cambiar durante el fetch.
        role, denial = heraldo_message_role_access(guild, member, role_id, action)
        if denial:
            answer = denial + " No se modificaron los roles."
        elif action == "añadir" or (action == "alternar" and role not in member.roles):
            await member.add_roles(role, reason="Componente de mensajes de El Heraldo")
            answer = "Rol asignado."
        elif action == "quitar" or (action == "alternar" and role in member.roles):
            await member.remove_roles(role, reason="Componente de mensajes de El Heraldo")
            answer = "Rol retirado."
        else:
            answer = "No fue necesario realizar cambios."
    except discord.HTTPException:
        answer = "No fue posible modificar el rol. Verifica los permisos."
    finally:
        _message_role_busy.discard(key)
        _message_role_cooldown[key] = time.monotonic() + 3
    await interaction.followup.send(answer, ephemeral=True)


@bot.listen("on_interaction")
async def heraldo_message_components_dispatch(interaction: discord.Interaction):
    # Captura los componentes publicados antes de un reinicio sin registrar una vista por mensaje.
    if interaction.type != discord.InteractionType.component or not interaction.data:
        return
    custom_id = str(interaction.data.get("custom_id", ""))
    if custom_id.startswith("ehmsg:select:"):
        parts = custom_id.split(":")
        values = interaction.data.get("values", [])
        selected = str(values[0]).split(":") if values else []
        if len(parts) == 3 and parts[2].isdigit() and len(selected) == 2 and selected[0].isdigit() and selected[1] in {"añadir", "quitar", "alternar"} and not interaction.response.is_done():
            await heraldo_message_role_action(interaction, int(parts[2]), int(selected[0]), selected[1])
        return
    if not custom_id.startswith("ehmsg:role:"):
        return
    parts = custom_id.split(":")
    if len(parts) != 5 or not parts[2].isdigit() or not parts[3].isdigit() or parts[4] not in {"añadir", "quitar", "alternar"}:
        return
    if not interaction.response.is_done():
        await heraldo_message_role_action(interaction, int(parts[2]), int(parts[3]), parts[4])



class HeraldoMessageKitImportModal(discord.ui.Modal, title="Importar kit de mensajes"):
    payload = discord.ui.TextInput(label="JSON del kit", style=discord.TextStyle.paragraph, max_length=4000)

    def __init__(self, guild_id: int, owner_id: int):
        super().__init__()
        self.guild_id, self.owner_id = guild_id, owner_id

    async def on_submit(self, interaction: discord.Interaction):
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message("Acceso denegado.", ephemeral=True)
            return
        try:
            data = json.loads(str(self.payload))
            cleaned = message_payload.import_kit(data)
        except (ValueError, TypeError, KeyError):
            await interaction.response.send_message("El kit no cumple el formato y los límites exigidos.", ephemeral=True)
            return
        current = heraldo_template_list(self.guild_id)
        existing = {x["name"].casefold() for x in current}
        duplicates = [x["name"] for x in cleaned if x["name"].casefold() in existing]
        if duplicates:
            await interaction.response.send_message(
                "Importación cancelada: el kit contiene nombres que ya existen. Renómbralos antes de importar.",
                ephemeral=True,
            )
            return
        if len(current) + len(cleaned) > 25:
            await interaction.response.send_message("Importación cancelada: se superaría el máximo de 25 plantillas.", ephemeral=True)
            return
        await heraldo_message_request_confirmation(interaction, self.guild_id, self.owner_id,
            "kit", {"items": cleaned},
            f"Importación de **{len(cleaned)}** plantillas pendiente. No se importarán acciones de roles ni se sobrescribirán mensajes.")


class HeraldoMessageKitsView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel no te pertenece.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Exportar kit", style=discord.ButtonStyle.primary)
    async def export(self, interaction: discord.Interaction, button: discord.ui.Button):
        templates = heraldo_template_list(self.guild_id)
        safe = [{k: v for k, v in t.items() if k in message_payload.VISUAL_KEYS | {"name"}} for t in templates]
        content = json.dumps({"version": 2, "templates": safe}, ensure_ascii=False, indent=2).encode("utf-8")
        await interaction.response.send_message(
            "Kit exportado. No incluye las acciones de roles ni configuraciones de otros servidores.",
            file=discord.File(io.BytesIO(content), filename="heraldo-message-kit.json"), ephemeral=True)

    @discord.ui.button(label="Importar kit", style=discord.ButtonStyle.primary)
    async def import_kit(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.send_modal(HeraldoMessageKitImportModal(self.guild_id, self.owner_id))

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.edit_message(content=heraldo_messages_setup_content(), embed=None,
                                                view=HeraldoMessagesSetupView(self.guild_id, self.owner_id))


class HeraldoMessagesSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id

        panel_select = discord.ui.Select(
            placeholder="Selecciona una sección de Mensajes",
            min_values=1,
            max_values=1,
            options=[
                discord.SelectOption(label="Verificación", value="verification", description="Panel, botón y respuesta al verificar."),
                discord.SelectOption(label="DM de verificación", value="verify_dm", description="Mensaje privado de verificación."),
                discord.SelectOption(label="Condenas", value="condemnation", description="Tarjeta fija de condenados y perdonados."),
                discord.SelectOption(label="Sugerencias", value="suggestions", description="Mensaje y panel de sugerencias."),
                discord.SelectOption(label="Honeypot", value="honeypot", description="Aviso de los canales trampa."),
                discord.SelectOption(label="Logs", value="logs", description="Registros de moderación y del servidor."),
                discord.SelectOption(label="Mensajes personalizados", value="templates", description="Mensajes adicionales creados por el administrador."),
                discord.SelectOption(label="Componentes", value="components", description="Botones y menús de roles."),
                discord.SelectOption(label="Programación", value="schedules", description="Envíos automáticos con fecha u horario."),
                discord.SelectOption(label="Autorespuestas", value="autoresponses", description="Respuestas a palabras o frases."),
                discord.SelectOption(label="Sticky", value="sticky", description="Mensaje mantenido al final de un canal."),
                discord.SelectOption(label="Webhooks", value="webhooks", description="Publicación mediante un webhook del bot."),
                discord.SelectOption(label="Kits de mensajes", value="kits", description="Importar o exportar mensajes personalizados."),
            ],
            row=0,
        )
        panel_select.callback = self.open_editor
        self.panel_select = panel_select
        self.add_item(panel_select)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(
                "Este panel de configuración no es tuyo.",
                ephemeral=True,
            )
            return False
        return True

    async def open_editor(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        selected = values[0] if values else ""

        if selected == "webhooks":
            await interaction.response.send_message(
                "**Publicación por webhook**\n\nUse `/webhook_mensaje` para elegir plantilla y canal y confirmar su publicación. "
                "El administrador y el bot deben tener permiso para gestionar webhooks en el destino. "
                "El Heraldo crea o reutiliza únicamente su propio webhook; no solicita ni almacena tokens. "
                "Admite plantillas visuales y enlaces. Los botones y selectores de roles se publican mediante el bot.",
                ephemeral=True)
            return

        if selected == "sticky":
            await interaction.response.send_message(
                "**Mensajes sticky**\n\nUse `/sticky crear` para elegir canal y plantilla; confirmar habilita su publicación. "
                "El bot reemplaza su publicación anterior después de actividad humana, respetando una espera configurable. "
                "Use `/sticky listar` para consultar errores y `/sticky retirar` para detenerlo; la última publicación se conserva. "
                "Un envío incierto queda detenido para revisión.", ephemeral=True)
