def validate_setup_view_layouts(guild_id: int) -> list[str]:
    """Construye las vistas de /setup para detectar errores de layout al arrancar."""
    factories = [
        ("HeraldoSetupView", lambda: HeraldoSetupView(guild_id, 0)),
        ("HeraldoChannelSetupView", lambda: HeraldoChannelSetupView(guild_id, 0)),
        ("HeraldoRoleSetupView", lambda: HeraldoRoleSetupView(guild_id, 0)),
        ("HeraldoOrientationSetupView", lambda: HeraldoOrientationSetupView(guild_id, 0)),
        ("HeraldoMotwSetupView", lambda: HeraldoMotwSetupView(guild_id, 0)),
        ("HeraldoHoneypotSetupView", lambda: HeraldoHoneypotSetupView(guild_id, 0)),
        ("HeraldoVerificationSetupView", lambda: HeraldoVerificationSetupView(guild_id, 0)),
        ("HeraldoRaidSetupView", lambda: HeraldoRaidSetupView(guild_id, 0)),
        ("HeraldoMessagesSetupView", lambda: HeraldoMessagesSetupView(guild_id, 0)),
        ("HeraldoTemplateSetupView", lambda: HeraldoTemplateSetupView(guild_id, 0)),
        ("HeraldoMessageComponentsSetupView", lambda: HeraldoMessageComponentsSetupView(guild_id, 0)),
        ("HeraldoMessageKitsView", lambda: HeraldoMessageKitsView(guild_id, 0)),
        ("HeraldoJoinRolesSetupView", lambda: HeraldoJoinRolesSetupView(guild_id, 0)),
        ("HeraldoJoinRolesBasicView", lambda: HeraldoJoinRolesBasicView(guild_id, 0)),
        ("HeraldoJoinRolesUsersView", lambda: HeraldoJoinRolesUsersView(guild_id, 0)),
        ("HeraldoJoinRolesBotsView", lambda: HeraldoJoinRolesBotsView(guild_id, 0)),
        ("HeraldoJoinRolesSyncView", lambda: HeraldoJoinRolesSyncView(guild_id, 0)),
        ("HeraldoModerationSetupView", lambda: HeraldoModerationSetupView(guild_id, 0)),
        ("HeraldoUserReportsSetupView", lambda: HeraldoUserReportsSetupView(guild_id, 0)),
        ("ReportReminderSetupView", lambda: ReportReminderSetupView(guild_id, 0)),
        ("HeraldoDateFormatSetupView", lambda: HeraldoDateFormatSetupView(guild_id, 0)),
        ("HeraldoCasesSetupView", lambda: HeraldoCasesSetupView(guild_id, 0)),
        ("HeraldoCondemnationSetupView", lambda: HeraldoCondemnationSetupView(guild_id, 0)),
        ("HeraldoAutomodSetupView", lambda: HeraldoAutomodSetupView(guild_id, 0)),
        ("HeraldoVerificationHubView", lambda: HeraldoVerificationHubView(guild_id, 0)),
        ("HeraldoLoggingSetupView", lambda: HeraldoLoggingSetupView(guild_id, 0)),
        ("HeraldoReactionRolesSetupView", lambda: HeraldoReactionRolesSetupView(guild_id, 0)),
        ("HeraldoReactionRolesEditorView", lambda: HeraldoReactionRolesEditorView(
            guild_id, 0, {"channel_id": 0, "roles": []})),
        ("DefaultMessageStudioView:verification:preview", lambda: DefaultMessageStudioView(guild_id, 0, "verification", "preview", "messages_setup")),
        ("DefaultMessageStudioView:verification:edit", lambda: DefaultMessageStudioView(guild_id, 0, "verification", "edit", "messages_setup")),
        ("DefaultMessageStudioView:verify_dm:edit", lambda: DefaultMessageStudioView(guild_id, 0, "verify_dm", "edit", "messages_setup")),
        ("DefaultMessageStudioView:suggestions:edit", lambda: DefaultMessageStudioView(guild_id, 0, "suggestions", "edit", "messages_setup")),
        ("DefaultMessageStudioView:honeypot:edit", lambda: DefaultMessageStudioView(guild_id, 0, "honeypot", "edit", "messages_setup")),
        ("DefaultMessageStudioView:condemnation:edit", lambda: DefaultMessageStudioView(guild_id, 0, "condemnation", "edit", "messages_setup")),
        ("LogTemplateEditorView:preview", lambda: LogTemplateEditorView(guild_id, 0, "general", None, "messages_setup", "preview")),
        ("LogTemplateEditorView:edit", lambda: LogTemplateEditorView(guild_id, 0, "general", None, "messages_setup", "edit")),
        ("LogTemplateEditorView:variables", lambda: LogTemplateEditorView(guild_id, 0, "general", None, "messages_setup", "variables")),
    ]
    errors: list[str] = []
    for name, factory in factories:
        try:
            view = factory()
            if len(view.children) > 25:
                errors.append(f"{name}: {len(view.children)} componentes; Discord permite 25.")
            view.stop()
        except Exception as exc:
            errors.append(f"{name}: {type(exc).__name__}: {exc}")
    return errors



class ModerationReactionEditModal(discord.ui.Modal, title="Moderation · Editar reporte"):
    emoji = discord.ui.TextInput(label="Emoji", required=True, max_length=100, placeholder="📢")
    label = discord.ui.TextInput(label="Nombre del reporte", required=True, max_length=100, placeholder="Spam")

    def __init__(self, parent_view: "HeraldoUserReportsSetupView", index: int | None = None) -> None:
        super().__init__()
        self.parent_view = parent_view
        self.index = index
        self.original_item = (copy.deepcopy(parent_view._working_reactions()[index])
                              if index is not None else None)
        if index is not None:
            item = parent_view._working_reactions()[index]
            self.emoji.default = str(item["emoji"])
            self.label.default = str(item["label"])
        elif not any(_moderation_emoji_key(str(item["emoji"])) == _moderation_emoji_key("❗")
                     for item in parent_view._working_reactions()):
            # Ofrecer la nueva advertencia por defecto sin alterar reglas guardadas.
            self.emoji.default = "❗"
            self.label.default = "Incumplimiento de reglas"

    async def on_submit(self, interaction: discord.Interaction) -> None:
        if not await self.parent_view.interaction_check(interaction):
            return
        current = self.parent_view._working_reactions()
        if self.index is not None and (
            self.index >= len(current) or current[self.index] != self.original_item
        ):
            await interaction.response.send_message(
                "La reacción cambió mientras editaba. Abra el formulario nuevamente.",
                ephemeral=True,
            )
            return
        emoji = str(self.emoji).strip()
        label = str(self.label).strip()
        key = _moderation_emoji_key(emoji)
        condemn_key = _moderation_emoji_key(self.parent_view.pending_condemn_emoji or get_condemnation_emoji(self.parent_view.guild_id))
        if key == condemn_key:
            await interaction.response.send_message("Ese emoji está reservado para la condena directa.", ephemeral=True)
            return
        reactions = [dict(item) for item in self.parent_view._working_reactions()]
        for idx, item in enumerate(reactions):
            if idx != self.index and _moderation_emoji_key(str(item["emoji"])) == key:
                await interaction.response.send_message("Ese emoji ya está usado por otro reporte.", ephemeral=True)
                return
        if self.index is None:
            if len(reactions) >= MODERATION_REPORT_MAX_REACTIONS:
                await interaction.response.send_message(f"Ya alcanzaste el máximo de {MODERATION_REPORT_MAX_REACTIONS} reacciones.", ephemeral=True)
                return
            is_default_warning = (key == _moderation_emoji_key("❗")
                                  and label == "Incumplimiento de reglas")
            reactions.append({
                "emoji": emoji, "label": label,
                "action": "warn" if is_default_warning else "report",
                "duration_minutes": None, "threshold": 1, "purge_minutes": None,
            })
            self.parent_view.selected_reaction_index = len(reactions) - 1
        else:
            reactions[self.index]["emoji"] = emoji
            reactions[self.index]["label"] = label
            self.parent_view.selected_reaction_index = self.index
        self.parent_view.pending_reactions = reactions
        self.parent_view._rebuild_reaction_select()
        await interaction.response.edit_message(content=self.parent_view._content(interaction.guild), view=self.parent_view)


class ModerationReactionRuleModal(discord.ui.Modal, title="Condiciones de reacción"):
    duration = discord.ui.TextInput(label="Duración de la sanción (si aplica)", required=False, max_length=30, placeholder="Por ejemplo: 30m, 2h, 1d")
    threshold = discord.ui.TextInput(label="Personas distintas necesarias", required=True, max_length=2, placeholder="Por ejemplo: 2")
    purge = discord.ui.TextInput(label="Purga del miembro reportado (opcional)", required=False, max_length=30, placeholder="Ej. 30m: últimos 30 minutos; vacío = no borrar")

    def __init__(self, parent_view: "HeraldoUserReportsSetupView", index: int) -> None:
        super().__init__()
        self.parent_view = parent_view
        self.index = index
        item = parent_view._working_reactions()[index]
        self.original_item = copy.deepcopy(item)
        duration = item.get("duration_minutes")
        self.duration.default = format_duration(int(duration)) if duration else "-"
        self.threshold.default = str(item.get("threshold", 1))
        purge = item.get("purge_minutes")
        self.purge.default = format_duration(int(purge)) if purge else "-"
        action = str(item.get("action", "report"))
        if action in {"report", "warn", "kick"}:
            self.remove_item(self.duration)
        if action in {"report", "warn"}:
            self.remove_item(self.purge)

    async def on_submit(self, interaction: discord.Interaction) -> None:
        # La acción pertenece al selector desplegable del editor.
        if not await self.parent_view.interaction_check(interaction):
            return
        current = self.parent_view._working_reactions()
        if self.index >= len(current) or current[self.index] != self.original_item:
            await interaction.response.send_message(
                "La regla cambió mientras editaba. Abra el formulario nuevamente.",
                ephemeral=True,
            )
            return
        action = str(current[self.index].get("action", "report"))
        if action not in MODERATION_REPORT_ACTIONS:
            await interaction.response.send_message("La acción seleccionada no es válida.", ephemeral=True)
            return
        try:
            threshold = int(str(self.threshold).strip())
            if not 1 <= threshold <= 25:
                raise ValueError
        except ValueError:
            await interaction.response.send_message("Los reportes necesarios deben estar entre 1 y 25.", ephemeral=True)
            return
        duration_raw = str(self.duration).strip().lower()
        duration_minutes = None
        if duration_raw not in {"", "-", "0", "none", "indefinida"}:
            try:
                duration_minutes = parse_duration(duration_raw, 1, (365 if action == "ban" else 28) * 24 * 60)
            except ValueError as exc:
                await interaction.response.send_message(f"Duración inválida: {exc}", ephemeral=True)
                return
        if action == "timeout" and duration_minutes is None:
            await interaction.response.send_message("Timeout necesita una duración.", ephemeral=True)
            return
        purge_raw = str(self.purge).strip().lower()
        purge_minutes = None
        if purge_raw not in {"", "-", "0", "none", "no"}:
            try:
                kind, value = parse_purge_spec(purge_raw)
                if kind != "time":
                    raise ValueError("Usa una ventana de tiempo, por ejemplo 30m o 2h.")
                purge_minutes = value
            except ValueError as exc:
                await interaction.response.send_message(f"Purga inválida: {exc}", ephemeral=True)
                return
        if action == "warn":
            duration_minutes, purge_minutes, threshold = None, None, 1
        elif action in {"report", "kick"}:
            duration_minutes = None
        if action == "report":
            purge_minutes = None
        if action == "report" and purge_minutes:
            await interaction.response.send_message(
                "Solo reportar no permite borrar mensajes. Elimina la ventana de purga para continuar.", ephemeral=True
            )
            return
        reactions = [dict(item) for item in self.parent_view._working_reactions()]
        reactions[self.index].update(
            action=action, duration_minutes=duration_minutes, threshold=threshold, purge_minutes=purge_minutes
        )
        self.parent_view.pending_reactions = reactions
        self.parent_view.selected_reaction_index = self.index
        self.parent_view._rebuild_reaction_select()
        await interaction.response.edit_message(content=self.parent_view._content(interaction.guild), view=self.parent_view)

class ModerationCondemnEmojiModal(discord.ui.Modal, title="Emoji para condena directa"):
    emoji = discord.ui.TextInput(label="Emoji de condena", required=True, max_length=100, placeholder="☠️")

    def __init__(self, parent_view: "HeraldoUserReportsSetupView") -> None:
        super().__init__()
        self.parent_view = parent_view
        self.emoji.default = parent_view.pending_condemn_emoji or get_condemnation_emoji(parent_view.guild_id)

    async def on_submit(self, interaction: discord.Interaction) -> None:
        if not await self.parent_view.interaction_check(interaction):
            return
        emoji = str(self.emoji).strip()
        if not emoji:
            await interaction.response.send_message("El emoji no puede estar vacío.", ephemeral=True)
            return
        report_mappings = self.parent_view.pending_reactions
        if report_mappings is None:
            report_mappings = moderation_report_reactions(self.parent_view.guild_id)
        conflict = next((item for item in report_mappings if _moderation_emoji_key(item["emoji"]) == _moderation_emoji_key(emoji)), None)
        if conflict:
            await interaction.response.send_message(
                f"Ese emoji pertenece al reporte **{conflict['label']}**: "
                f"{moderation_action_label(str(conflict.get('action', 'report')))}, "
                f"con un umbral de {conflict.get('threshold', 1)} personas distintas. "
                "Revísalo en **/setup → Moderation → Reportes → Condiciones**. "
                "Elige otro emoji para condenar mediante reacción.", ephemeral=True)
            return
        self.parent_view.pending_condemn_emoji = emoji
        await interaction.response.edit_message(content=self.parent_view._content(interaction.guild), view=self.parent_view)


class HeraldoWarningLimitSelectView(discord.ui.View):
    """Borrador de política de advertencias y sanciones por reacción."""

    POLICY_ACTIONS = (
        ("warn", "Advertir", "Crear expediente WARN sin borrar mensajes"),
        ("timeout", "Aislar", "Timeout por reportes o límite de WARN"),
        ("kick", "Expulsar", "Expulsión sin borrar mensajes"),
        ("ban", "Banear", "Baneo sin borrar mensajes"),
        ("condemn", "Condenar", "Motor de condenas y conservación de evidencias"),
    )

    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=300)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.original_raw = {
            "moderation_warn_limit": guild_config_get(guild_id, "moderation_warn_limit"),
            "moderation_warn_limit_action": guild_config_get(guild_id, "moderation_warn_limit_action"),
            "moderation_warn_limit_mute_minutes": guild_config_get(guild_id, "moderation_warn_limit_mute_minutes"),
        }
        for key, _, _ in self.POLICY_ACTIONS:
            name = f"moderation_reaction_{key}_enabled"
            self.original_raw[name] = guild_config_get(guild_id, name)
        self.max_warns = moderation_warning_limit(guild_id)
        self.escalation = moderation_warn_escalation_action(guild_id)
        self.mute_minutes = moderation_warn_escalation_duration(guild_id)
        self.enabled_actions = {
            action for action, _, _ in self.POLICY_ACTIONS
            if moderation_report_punishment_enabled(guild_id, action)
        }
        self.max_select = discord.ui.Select(
            placeholder="1. Máximo de advertencias vigentes",
            options=[
                discord.SelectOption(
                    label=f"{value} advertencia{'s' if value > 1 else ''}", value=str(value),
                    default=value == self.max_warns,
                ) for value in range(1, MODERATION_WARN_MAX_ALLOWED + 1)
            ], row=0,
        )
        self.max_select.callback = self.select_max
        self.add_item(self.max_select)
        self.escalation_select = discord.ui.Select(
            placeholder="2. Acción cuando se alcanza el máximo",
            options=[
                discord.SelectOption(label=label, value=action, description=hint,
                                     default=action == self.escalation)
                for action, label, hint in (
                    ("none", "Solo avisar a moderación", "Predeterminado; no aplica sanciones"),
                    ("timeout", "Aislar temporalmente", "Requiere duración de aislamiento"),
                    ("kick", "Expulsar", "No elimina mensajes"),
                    ("ban", "Banear", "No elimina mensajes"),
                    ("condemn", "Condenar", "Utiliza el motor de condenas"),
                )
            ], row=1,
        )
        self.escalation_select.callback = self.select_escalation
        self.add_item(self.escalation_select)
        self.duration_select = discord.ui.Select(
            placeholder="3. Duración si la acción es Aislar",
            options=[
                discord.SelectOption(label=format_duration(minutes), value=str(minutes),
                                     default=minutes == self.mute_minutes)
                for minutes in MODERATION_WARN_ESCALATION_DURATION_CHOICES
            ],
            disabled=self.escalation != "timeout", row=2,
        )
        self.duration_select.callback = self.select_duration
        self.add_item(self.duration_select)
        self.punishment_select = discord.ui.Select(
            placeholder="4. Acciones permitidas por reportes (selección múltiple)",
            options=[
                discord.SelectOption(label=label, value=action, description=hint,
                                     default=action in self.enabled_actions)
                for action, label, hint in self.POLICY_ACTIONS
            ],
            min_values=0, max_values=len(self.POLICY_ACTIONS), row=3,
        )
        self.punishment_select.callback = self.select_punishments
        self.add_item(self.punishment_select)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    def _content(self) -> str:
        names = {"none": "Solo avisar", "timeout": "Aislar", "kick": "Expulsar",
                 "ban": "Banear", "condemn": "Condenar"}
        toggles = ", ".join(label for action, label, _ in self.POLICY_ACTIONS
                            if action in self.enabled_actions) or "Ninguna"
        return (
            "**El Heraldo · Moderation · Política de reportes y advertencias**\n\n"
            f"**Máximo de advertencias:** {self.max_warns}/{self.max_warns} (1 a 5).\n"
            f"**Al alcanzar el máximo:** {names[self.escalation]}"
            + (f" durante {format_duration(self.mute_minutes)}" if self.escalation == "timeout" else "")
            + f".\n**Acciones habilitadas para reportes:** {toggles}.\n\n"
            "El número de reportes por reacción se configura por separado mediante "
            "**Configurar condiciones**. Las sanciones desactivadas no se ejecutan, "
            "aunque una regla existente las tenga seleccionadas.\n"
            "Solo reportar conserva siempre el mensaje. Advertir crea un expediente WARN "
            "sin purga. Condenar utiliza el motor de condenas.\n"
            "Cuando un miembro alcance el máximo de advertencias, se ejecutará la acción "
            "seleccionada **solo si está habilitada**. "
            "La opción predeterminada es Solo avisar. No se repite una sanción incierta.\n\n"
            "Ninguna selección se guarda hasta confirmar la propuesta."
        )

    async def select_max(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        if len(values) != 1 or values[0] not in {"1", "2", "3", "4", "5"}:
            await interaction.response.send_message("El máximo debe estar entre 1 y 5.", ephemeral=True)
            return
        self.max_warns = int(values[0])
        for option in self.max_select.options:
            option.default = option.value == values[0]
        await interaction.response.edit_message(content=self._content(), view=self)

    async def select_escalation(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        if len(values) != 1 or values[0] not in MODERATION_WARN_ESCALATION_ACTIONS:
            await interaction.response.send_message("Seleccione una acción válida.", ephemeral=True)
            return
        self.escalation = values[0]
        self.duration_select.disabled = self.escalation != "timeout"
        for option in self.escalation_select.options:
            option.default = option.value == self.escalation
        await interaction.response.edit_message(content=self._content(), view=self)

    async def select_duration(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        if (len(values) != 1 or not values[0].isdigit()
                or int(values[0]) not in MODERATION_WARN_ESCALATION_DURATION_CHOICES):
            await interaction.response.send_message("Duración no admitida.", ephemeral=True)
            return
        self.mute_minutes = int(values[0])
        for option in self.duration_select.options:
            option.default = option.value == values[0]
        await interaction.response.edit_message(content=self._content(), view=self)

    async def select_punishments(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        valid = {item[0] for item in self.POLICY_ACTIONS}
        if len(values) != len(set(values)) or not set(values).issubset(valid):
            await interaction.response.send_message("La selección de acciones no es válida.", ephemeral=True)
            return
        self.enabled_actions = set(values)
        for option in self.punishment_select.options:
            option.default = option.value in self.enabled_actions
        await interaction.response.edit_message(content=self._content(), view=self)

    @discord.ui.button(label="Revisar y confirmar", style=discord.ButtonStyle.primary, row=4)
    async def review(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if any(guild_config_get(self.guild_id, key) != raw
               for key, raw in self.original_raw.items()):
            await interaction.response.send_message(
                "La política cambió mientras editaba. Abra un panel nuevo.", ephemeral=True
            )
            return
        action = self.escalation
        if action != "none" and action in self.enabled_actions:
            required = {"timeout": "moderate_members", "kick": "kick_members",
                        "ban": "ban_members", "condemn": "manage_roles"}[action]
            bot_member = interaction.guild.me
            if bot_member is None or not getattr(bot_member.guild_permissions, required, False):
                await interaction.response.send_message(
                    "El Heraldo no tiene el permiso requerido para la acción de límite seleccionada.",
                    ephemeral=True,
                )
                return
        changes = {
            "moderation_warn_limit": str(self.max_warns),
            "moderation_warn_limit_action": self.escalation,
            "moderation_warn_limit_mute_minutes": str(self.mute_minutes),
        }
        for name, _, _ in self.POLICY_ACTIONS:
            changes[f"moderation_reaction_{name}_enabled"] = (
                "1" if name in self.enabled_actions else "0"
            )
        # Omitir valores semánticamente iguales, incluidos los valores predeterminados.
        changes = {
            key: value for key, value in changes.items()
            if (self.original_raw[key] if self.original_raw[key] is not None else
                "3" if key == "moderation_warn_limit" else
                "none" if key == "moderation_warn_limit_action" else
                "60" if key == "moderation_warn_limit_mute_minutes" else "1") != value
        }
        if not changes:
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id, changes)

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger, row=4)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.stop()
        await interaction.response.edit_message(
            content="Edición cancelada. No se guardaron cambios.", view=None,
        )


REPORT_REMINDER_HELP = (
    "Los recordatorios informan a los miembros de cómo colaborar con la moderación "
    "utilizando las reacciones de reporte disponibles. Explican qué significa cada "
    "reacción, sin presentar la condena exclusiva como opción de uso general. "
    "Úselos con moderación para evitar mensajes excesivos y reportes innecesarios."
)


def reminder_settings(guild_id):
    return {key: guild_config_get(guild_id, key) or fallback for key, fallback in {
        "report_reminder_enabled": "0",
        "report_reminder_channel": "0",
        "report_reminder_frequency": "weekly",
        "report_reminder_day": "0",
        "report_reminder_hour": "12",
        "report_reminder_interval": "7d",
        "report_reminder_start": "",
    }.items()}


def reminder_preview(guild_id):
    lines = []
    for item in moderation_report_reactions(guild_id):
        if item.get("action") == "warn":
            continue
        lines.append(f"• {item['emoji']} {discord.utils.escape_markdown(str(item['label']))}: "
                     f"{item.get('threshold', 1)} reportes de personas diferentes")
    return ("**Cómo colaborar con la moderación**\n\n"
            "Para comunicar posibles incumplimientos, reaccione con el emoji que "
            "mejor describa el mensaje. Evite reportes innecesarios.\n\n"
            + ("\n".join(lines) or "No hay reacciones disponibles.")
            + "\n\nEl equipo de moderación revisará los reportes. Las acciones "
              "reservadas a moderadores no forman parte de este sistema público.")[:1900]


class ReportReminderOptionsModal(discord.ui.Modal, title="Recordatorios: intervalo personalizado"):
    days = discord.ui.TextInput(label="Intervalo (ej.: 30s, 2m, 1h, 14d)", placeholder="Ejemplo: 2m", max_length=10)
    date = discord.ui.TextInput(label="Inicio (AAAA-MM-DD, opcional)", placeholder="Ejemplo: 2026-11-01", required=False, max_length=10)
    def __init__(self, parent):
        super().__init__()
        self.parent = parent
        current = parent.pending["report_reminder_interval"]
        self.days.default = current if re.fullmatch(r"(\d+)(s|m|h|d)", current) else f"{current}d"
        self.date.default = parent.pending["report_reminder_start"]
    async def on_submit(self, interaction):
        if not await self.parent.interaction_check(interaction):
            return
        try:
            interval = str(self.days).strip().lower()
            match = re.fullmatch(r"(\d+)(s|m|h|d)", interval)
            if not match:
                raise ValueError()
            number, unit = int(match.group(1)), match.group(2)
            seconds = number * {"s": 1, "m": 60, "h": 3600, "d": 86400}[unit]
            is_test = os.getenv("RAILWAY_PROJECT_ID") == "747a1ee0-cdab-4ad5-8e45-a6ddfccc9b61"
            if seconds < (10 if is_test else 86400) or seconds > 365 * 86400 or (unit == "s" and not is_test):
                raise ValueError()
            start = str(self.date).strip()
            if start:
                datetime.strptime(start, "%Y-%m-%d")
        except ValueError:
            await interaction.response.send_message("Use 1d–365d, 24h o equivalente. Solo en Test: desde 10s (ej.: 30s, 2m). Fecha AAAA-MM-DD.", ephemeral=True)
            return
        self.parent.pending.update(report_reminder_interval=interval, report_reminder_start=start, report_reminder_frequency="custom")
        await interaction.response.edit_message(content=self.parent.summary(), view=self.parent)


class ReportReminderSetupView(discord.ui.View):
    FREQUENCIES = {"daily": "Diario", "weekly": "Semanal", "fortnightly": "Cada 14 días",
                   "monthly": "Mensual", "custom": "Personalizado"}
    def __init__(self, guild_id, owner_id):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.original = reminder_settings(guild_id)
        self.pending = dict(self.original)
        menus = [
            ("report_reminder_frequency", 0, [(key, value) for key, value in self.FREQUENCIES.items()]),
            ("report_reminder_day", 1, [(str(i), name) for i, name in enumerate(("Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"))]),
            ("report_reminder_hour", 2, [(str(i), f"{i:02d}:00") for i in range(24)]),
        ]
        for field, row, options in menus:
            select = discord.ui.Select(placeholder={"report_reminder_frequency": "Frecuencia",
                "report_reminder_day": "Día (semanal)", "report_reminder_hour": "Hora (Santo Domingo)"}[field],
                row=row, options=[discord.SelectOption(label=label, value=value, default=value == self.pending[field]) for value, label in options])
            async def change(interaction, name=field):
                value = (interaction.data or {}).get("values", [None])[0]
                valid = set(dict(next(o for k, _r, o in menus if k == name)))
                if value not in valid:
                    await interaction.response.send_message("Selección inválida.", ephemeral=True)
                    return
                self.pending[name] = value
                for item in self.children:
                    if isinstance(item, discord.ui.Select) and item.placeholder == {
                        "report_reminder_frequency": "Frecuencia",
                        "report_reminder_day": "Día (semanal)",
                        "report_reminder_hour": "Hora (Santo Domingo)",
                    }[name]:
                        for option in item.options:
                            option.default = option.value == value
                await interaction.response.edit_message(content=self.summary(), view=self)
            select.callback = change
            self.add_item(select)
        channel = discord.ui.ChannelSelect(placeholder="Canal para el recordatorio", channel_types=[discord.ChannelType.text], row=3)
        channel.callback = self.channel_changed
        self.add_item(channel)

    async def interaction_check(self, interaction):
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    def summary(self):
        p = self.pending
        state = "Activado" if p["report_reminder_enabled"] == "1" else "Desactivado"
        return (f"**Recordatorios de reportes**\n\n{REPORT_REMINDER_HELP}\n\n"
            f"**Estado propuesto:** {state}\n"
            f"**Frecuencia:** {self.FREQUENCIES[p['report_reminder_frequency']]}\n"
            f"**Hora:** {int(p['report_reminder_hour']):02d}:00 (Santo Domingo)\n"
            f"**Canal:** <#{p['report_reminder_channel']}>\n"
            "Personalizar: 1d–365d o equivalente; en Test también 30s, 2m o 1h. "
            "Solo una confirmación administrativa guarda estos cambios.\n"
            f"**Próxima publicación estimada:** "
            f"{format_configured_datetime(self.guild_id, reminder_next_due(p, datetime.now(timezone.utc)))}")

    async def channel_changed(self, interaction):
        values = (interaction.data or {}).get("values", [])
        channel = interaction.guild.get_channel(int(values[0])) if values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message("Seleccione un canal de texto.", ephemeral=True)
            return
        perms = channel.permissions_for(interaction.guild.me)
        if not (perms.view_channel and perms.send_messages and perms.embed_links):
            await interaction.response.send_message("Faltan permisos del bot para publicar.", ephemeral=True)
            return
        self.pending["report_reminder_channel"] = str(channel.id)
        await interaction.response.edit_message(content=self.summary(), view=self)

    @discord.ui.button(label="Personalizar", style=discord.ButtonStyle.primary, row=4)
    async def custom(self, interaction, button):
        await interaction.response.send_modal(ReportReminderOptionsModal(self))

    @discord.ui.button(label="Vista previa", style=discord.ButtonStyle.secondary, row=4)
    async def preview(self, interaction, button):
        await interaction.response.send_message(content=reminder_preview(self.guild_id), ephemeral=True)

    @discord.ui.button(label="Activar / Desactivar", style=discord.ButtonStyle.primary, row=4)
    async def toggle(self, interaction, button):
        self.pending["report_reminder_enabled"] = "0" if self.pending["report_reminder_enabled"] == "1" else "1"
        await interaction.response.edit_message(content=self.summary(), view=self)

    @discord.ui.button(label="Confirmar cambios", style=discord.ButtonStyle.success, row=4)
    async def confirm(self, interaction, button):
        if reminder_settings(self.guild_id) != self.original:
            await interaction.response.send_message("Configuración obsoleta. Vuelva a abrirla.", ephemeral=True)
            return
        if self.pending["report_reminder_enabled"] == "1":
            channel = interaction.guild.get_channel(int(self.pending["report_reminder_channel"]))
            if not isinstance(channel, discord.TextChannel):
                await interaction.response.send_message("Seleccione un canal antes de activar.", ephemeral=True)
                return
        changes = {k: v for k, v in self.pending.items() if v != self.original[k]}
        if not changes:
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id, changes)

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger, row=4)
    async def cancel(self, interaction, button):
        self.stop()
        await interaction.response.edit_message(content="Cancelado. No se guardaron cambios.", view=None)


def reminder_next_due(settings, now):
    """Calcula una fecha futura en horario de Santo Domingo (UTC-4)."""
    local = now.astimezone(timezone(timedelta(hours=-4)))
    hour = max(0, min(23, int(settings["report_reminder_hour"])))
    candidate = local.replace(hour=hour, minute=0, second=0, microsecond=0)
    frequency = settings["report_reminder_frequency"]
    if frequency == "daily":
        days = 1
    elif frequency == "weekly":
        days = 7
        candidate += timedelta(days=(int(settings["report_reminder_day"]) - candidate.weekday()) % 7)
    elif frequency == "fortnightly":
        days = 14
    elif frequency == "monthly":
        days = None  # Los meses no tienen siempre 30 días.
    else:
        interval = str(settings["report_reminder_interval"]).lower()
        match = re.fullmatch(r"(\d+)(s|m|h|d)", interval)
        if match:
            seconds = int(match.group(1)) * {"s": 1, "m": 60, "h": 3600, "d": 86400}[match.group(2)]
        else:
            seconds = max(1, min(365, int(interval))) * 86400  # configuración heredada
        is_test = os.getenv("RAILWAY_PROJECT_ID") == "747a1ee0-cdab-4ad5-8e45-a6ddfccc9b61"
        seconds = max(10 if is_test else 86400, min(seconds, 365 * 86400))
        days = None
    start = settings["report_reminder_start"]
    if frequency in {"custom", "fortnightly", "monthly"} and start:
        try:
            candidate = datetime.strptime(start, "%Y-%m-%d").replace(
                tzinfo=timezone(timedelta(hours=-4)), hour=hour)
        except ValueError:
            pass
    # Evitar millones de iteraciones si un intervalo corto parte de una fecha antigua.
    # Se salta directamente al próximo vencimiento, sin recuperar avisos omitidos.
    if frequency == "custom" and candidate <= local:
        elapsed = (local - candidate).total_seconds()
        steps = int(elapsed // seconds) + 1
        candidate += timedelta(seconds=steps * seconds)
    while candidate <= local:
        if frequency == "monthly":
            import calendar
            next_year = candidate.year + (candidate.month == 12)
            next_month = candidate.month % 12 + 1
            day = min(candidate.day, calendar.monthrange(next_year, next_month)[1])
            candidate = candidate.replace(year=next_year, month=next_month, day=day)
        elif frequency == "custom":
            candidate += timedelta(seconds=seconds)
        else:
            candidate += timedelta(days=days)
    return candidate.astimezone(timezone.utc)


@tasks.loop(seconds=10)
async def report_reminders_loop():
    """No ejecuta publicaciones atrasadas ni repite envíos de resultado incierto."""
    now = datetime.now(timezone.utc)
    for guild in bot.guilds:
        settings = reminder_settings(guild.id)
        if settings["report_reminder_enabled"] != "1":
            continue
        channel = guild.get_channel(int(settings["report_reminder_channel"]))
        if not isinstance(channel, discord.TextChannel):
            continue
        me = guild.me
        perms = channel.permissions_for(me) if me is not None else None
        if perms is None or not (perms.view_channel and perms.send_messages and perms.embed_links):
            continue
        signature = json.dumps(settings, sort_keys=True)
        next_due_key = "report_reminder_next_due"
        signature_key = "report_reminder_signature"
        try:
            conn = db_connect()
            try:
                conn.execute("BEGIN IMMEDIATE")
                rows = conn.execute(
                    "SELECT key, value FROM guild_settings WHERE guild_id = ? AND key IN (?, ?)",
                    (guild.id, next_due_key, signature_key)).fetchall()
                stored = {row[0]: row[1] for row in rows}
                if stored.get(signature_key) != signature or not stored.get(next_due_key):
                    next_due = reminder_next_due(settings, now)
                    claim = False
                else:
                    try:
                        next_due = datetime.fromisoformat(stored[next_due_key])
                        if next_due.tzinfo is None:
                            raise ValueError("naive datetime")
                    except ValueError:
                        next_due = reminder_next_due(settings, now)
                    claim = next_due <= now
                    if claim:
                        next_due = reminder_next_due(settings, now)
                for key, value in (
                    (next_due_key, next_due.isoformat()), (signature_key, signature)
                ):
                    conn.execute(
                        "INSERT INTO guild_settings(guild_id, key, value) VALUES (?, ?, ?) "
                        "ON CONFLICT(guild_id, key) DO UPDATE SET value=excluded.value",
                        (guild.id, key, value))
                conn.commit()
            finally:
                conn.close()
            if claim:
                # La fecha siguiente se persiste antes de enviar, para no duplicar
                # notificaciones tras fallos ambiguos o reinicios.
                await channel.send(content=reminder_preview(guild.id),
                                   allowed_mentions=discord.AllowedMentions.none())
        except (discord.HTTPException, sqlite3.Error, ValueError, TypeError):
            print(f"Advertencia: recordatorio pendiente en servidor {guild.id}")
        except Exception:
            traceback.print_exc()


@report_reminders_loop.before_loop
async def before_report_reminders_loop():
    await bot.wait_until_ready()


class HeraldoUserReportsSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.original_channel_id = moderation_report_channel_id(guild_id)
        self.original_reactions = copy.deepcopy(moderation_report_reactions(guild_id))
        self.original_condemn_emoji = get_condemnation_emoji(guild_id)
        self.pending_channel_id: int | None = None
        self.pending_reactions: list[dict[str, object]] | None = None
        self.pending_condemn_emoji: str | None = None
        self.selected_reaction_index: int | None = None

        channel_select = discord.ui.ChannelSelect(
            placeholder="Seleccionar canal de reportes",
            channel_types=[discord.ChannelType.text], min_values=1, max_values=1, row=0,
        )
        channel_select.callback = self.select_channel
        self.channel_select = channel_select
        self.add_item(channel_select)
        self.reaction_select: discord.ui.Select | None = None
        self.action_select: discord.ui.Select | None = None
        self._rebuild_reaction_select()

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de configuración no es tuyo.", ephemeral=True)
            return False
        return True

    def _working_reactions(self) -> list[dict[str, object]]:
        return self.pending_reactions if self.pending_reactions is not None else moderation_report_reactions(self.guild_id)

    def _has_pending_changes(self) -> bool:
        return (
            (self.pending_channel_id is not None and self.pending_channel_id != self.original_channel_id)
            or (self.pending_reactions is not None and self.pending_reactions != self.original_reactions)
            or (self.pending_condemn_emoji is not None and self.pending_condemn_emoji != self.original_condemn_emoji)
        )

    def _update_change_buttons(self) -> None:
        pending = self._has_pending_changes()
        self.save_changes.disabled = not pending
        self.discard_changes.disabled = not pending

    def _rebuild_reaction_select(self) -> None:
        channel_id = self.pending_channel_id if self.pending_channel_id is not None else moderation_report_channel_id(self.guild_id)
        self.channel_select.default_values = [discord.SelectDefaultValue(id=channel_id, type=discord.SelectDefaultValueType.channel)] if channel_id else []
        if self.reaction_select is not None:
            self.remove_item(self.reaction_select)
        reactions = self._working_reactions()
        if reactions:
            options = []
            for index, item in enumerate(reactions):
                action = moderation_action_label(str(item.get("action", "report")))
                options.append(discord.SelectOption(
                    label=str(item["label"])[:100],
                    value=str(index),
                    emoji=str(item["emoji"]),
                    description=f"{action} · {item.get('threshold', 1)} reporte(s)"[:100],
                    default=index == self.selected_reaction_index,
                ))
            select = discord.ui.Select(placeholder=f"Reacciones configuradas · {len(reactions)}/{MODERATION_REPORT_MAX_REACTIONS}", options=options, row=1)
            select.callback = self.select_reaction
        else:
            select = discord.ui.Select(
                placeholder=f"Sin reacciones · 0/{MODERATION_REPORT_MAX_REACTIONS}",
                options=[discord.SelectOption(label="Sin reacciones configuradas", value="-1")],
                disabled=True, row=1,
            )
        self.reaction_select = select
        self.add_item(select)
        self._rebuild_action_select()

    def _rebuild_action_select(self) -> None:
        if self.action_select is not None:
            self.remove_item(self.action_select)
        reactions = self._working_reactions()
        index = self.selected_reaction_index
        selected = reactions[index] if index is not None and 0 <= index < len(reactions) else None
        current_action = str(selected.get("action", "report")) if selected else "report"
        selector = discord.ui.Select(
            placeholder="2. Acción al alcanzar los reportes necesarios",
            options=[
                discord.SelectOption(
                    label=moderation_action_label(action),
                    value=action,
                    default=action == current_action,
                )
                for action in ("report", "warn", "timeout", "condemn", "kick", "ban")
            ],
            disabled=selected is None,
            row=2,
        )
        selector.callback = self.select_action
        self.action_select = selector
        self.add_item(selector)

    async def select_action(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        index = self.selected_reaction_index
        if (index is None or not 0 <= index < len(self._working_reactions())
                or len(values) != 1 or values[0] not in MODERATION_REPORT_ACTIONS):
            await interaction.response.send_message(
                "Seleccione una reacción y una acción válida.", ephemeral=True
            )
            return
        reactions = [dict(item) for item in self._working_reactions()]
        reactions[index]["action"] = values[0]
        if values[0] in {"report", "warn"}:
            # Los reportes y las advertencias no eliminan mensajes.
            reactions[index]["purge_minutes"] = None
        if values[0] == "warn":
            reactions[index]["threshold"] = 1
        if values[0] in {"report", "warn", "kick"}:
            # Estas acciones no admiten duración; evita presentar valores inertes.
            reactions[index]["duration_minutes"] = None
        self.pending_reactions = reactions
        self._rebuild_reaction_select()
        notice = ""
        if values[0] == "report":
            notice = "\n\nSolo reportar no elimina mensajes; se descartó cualquier purga pendiente."
        elif values[0] == "warn":
            notice = "\n\nAdvertir: solo moderadores, una advertencia por mensaje, sin purga. El Heraldo asumirá la reacción si tiene permisos."
        elif values[0] == "timeout" and not reactions[index].get("duration_minutes"):
            notice = "\n\nPara aislar, pulse Condiciones y establezca la duración antes de guardar."
        await interaction.response.edit_message(
            content=self._content(interaction.guild) + notice, view=self
        )

    def _content(self, guild: discord.Guild) -> str:
        lines: list[str] = []
        if self.pending_channel_id is not None:
            channel = guild.get_channel(self.pending_channel_id)
            lines.append(f"Canal de reportes → {channel.mention if channel else self.pending_channel_id}")
        if self.pending_reactions is not None:
            lines.append(f"Reacciones → {len(self.pending_reactions)}/{MODERATION_REPORT_MAX_REACTIONS}")
        if self.pending_condemn_emoji is not None:
            lines.append(f"Emoji de condena → {self.pending_condemn_emoji}")
        selected = ""
        if self.selected_reaction_index is not None:
            reactions = self._working_reactions()
            if 0 <= self.selected_reaction_index < len(reactions):
                item = reactions[self.selected_reaction_index]
                duration = item.get("duration_minutes")
                purge = item.get("purge_minutes")
                action = str(item.get("action", "report"))
                count = int(item.get("threshold", 1))
                selected = (
                    f"\n\n**Seleccionado:** {item['emoji']} **{item['label']}**"
                    f"\nAcción: {moderation_action_label(str(item.get('action', 'report')))}"
                    f" · Umbral: {item.get('threshold', 1)}"
                    f" · Duración: {format_duration(int(duration)) if duration else '—'}"
                    f" · Ventana de purga: {format_duration(int(purge)) if purge else '—'}"
                )
                if action in {"kick", "ban", "condemn", "timeout"} and count == 1:
                    selected += ("\n**Advertencia:** esta sanción se activará con el "
                                 "reporte de una sola persona.")
                if action == "report":
                    selected += "\nSolo reportar no aplica sanciones ni elimina mensajes."
                if action == "warn":
                    selected += "\nSolo moderadores: crea expediente WARN y conserva el mensaje sin purgar."
                if action != "report" and not moderation_report_punishment_enabled(self.guild_id, action):
                    selected += "\n**Acción desactivada:** no se ejecutará al alcanzar el umbral."
        intro = (
            "**Reportes por reacción**\n"
            "Elija una reacción, seleccione la acción y ajuste sus condiciones.\n"
            "**Condena directa** y **Advertencias y sanciones** tienen ajustes propios.\n\n"
        )
        mappings = self._working_reactions()
        missing_warn = not any(
            _moderation_emoji_key(str(item["emoji"])) == _moderation_emoji_key("❗")
            for item in mappings
        )
        summary = (
            f"**Canal de reportes:** "
            f"{guild.get_channel(self.pending_channel_id or moderation_report_channel_id(self.guild_id)).mention if guild.get_channel(self.pending_channel_id or moderation_report_channel_id(self.guild_id)) else 'Sin canal específico'}\n"
            f"**Reacciones configuradas:** {len(mappings)}/{MODERATION_REPORT_MAX_REACTIONS}\n"
            f"**Condena directa:** {self.pending_condemn_emoji or get_condemnation_emoji(self.guild_id)}"
        )
        summary += "\n**Reacciones disponibles:**"
        for rule in mappings:
            rule_action = str(rule.get("action", "report"))
            rule_threshold = int(rule.get("threshold", 1))
            detail = (" · solo moderadores" if rule_action == "warn" else
                      f" · {rule_threshold} persona(s)")
            summary += (
                f"\n• {rule['emoji']} {discord.utils.escape_markdown(str(rule['label'])[:65])}"
                f" — {moderation_action_label(rule_action)}{detail}"
            )
        if missing_warn:
            summary += (
                "\n**Advertencia ❗ no configurada.** Pulse Añadir para prepararla "
                "y confirme con Guardar cambios."
            )
        action = moderation_warn_escalation_action(self.guild_id)
        current_action = moderation_action_label(action) if action != "none" else "Solo avisar"
        self._update_change_buttons()
        status = ("**Cambios pendientes:** revise y pulse Guardar cambios para aplicarlos."
                  if self._has_pending_changes() else
                  "**Estado:** sin cambios pendientes. Guardar y Descartar están desactivados.")
        result = (
            intro + status + "\n\n" + summary +
            f"\n\n**Advertencias vigentes:** máximo {moderation_warning_limit(self.guild_id)}; "
            f"al alcanzarlo: {current_action}." + selected +
            _pending_config_text(lines)
        )
        return result if len(result) <= 1900 else result[:1870] + "…"

    async def select_channel(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        channel = interaction.guild.get_channel(int(values[0])) if interaction.guild and values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message("No pude localizar ese canal.", ephemeral=True)
            return
        perms = channel.permissions_for(interaction.guild.me)
        if not perms.view_channel or not perms.send_messages or not perms.embed_links:
            await interaction.response.send_message("El Heraldo necesita Ver canal, Enviar mensajes e Insertar enlaces en ese canal.", ephemeral=True)
            return
        self.pending_channel_id = channel.id if channel.id != moderation_report_channel_id(self.guild_id) else None
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    async def select_reaction(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        if not values:
            return
        index = int(values[0])
        if index < 0 or index >= len(self._working_reactions()):
            await interaction.response.send_message("Esa reacción ya no está disponible.", ephemeral=True)
            return
        self.selected_reaction_index = index
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Añadir", style=discord.ButtonStyle.primary, row=3)
    async def add_reaction(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if len(self._working_reactions()) >= MODERATION_REPORT_MAX_REACTIONS:
            await interaction.response.send_message("Ya alcanzaste el máximo de reacciones.", ephemeral=True)
            return
        await interaction.response.send_modal(ModerationReactionEditModal(self))

    @discord.ui.button(label="Editar", style=discord.ButtonStyle.primary, row=3)
    async def edit_reaction(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.selected_reaction_index is None:
            await interaction.response.send_message("Selecciona primero una reacción.", ephemeral=True)
            return
        await interaction.response.send_modal(ModerationReactionEditModal(self, self.selected_reaction_index))

    @discord.ui.button(label="Condiciones", style=discord.ButtonStyle.primary, row=3)
    async def edit_rule(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.selected_reaction_index is None:
            await interaction.response.send_message("Selecciona primero una reacción.", ephemeral=True)
            return
        if self._working_reactions()[self.selected_reaction_index].get("action") == "warn":
            await interaction.response.send_message(
                "Advertir siempre se ejecuta con una sola reacción de un moderador, "
                "no tiene duración y nunca elimina mensajes.", ephemeral=True,
            )
            return
        await interaction.response.send_modal(ModerationReactionRuleModal(self, self.selected_reaction_index))

    @discord.ui.button(label="Eliminar", style=discord.ButtonStyle.danger, row=3)
    async def delete_reaction(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.selected_reaction_index is None:
            await interaction.response.send_message("Selecciona primero una reacción.", ephemeral=True)
            return
        reactions = [dict(item) for item in self._working_reactions()]
        reactions.pop(self.selected_reaction_index)
        self.pending_reactions = reactions
        self.selected_reaction_index = None
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Emoji de condena directa", style=discord.ButtonStyle.primary, row=3)
    async def edit_condemn_emoji(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.send_modal(ModerationCondemnEmojiModal(self))

    @discord.ui.button(label="Advertencias y sanciones", style=discord.ButtonStyle.primary, row=4)
    async def configure_warn_limit(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        warn_view = HeraldoWarningLimitSelectView(self.guild_id, self.owner_id)
        await interaction.response.send_message(
            content=warn_view._content(), view=warn_view, ephemeral=True,
        )

    @discord.ui.button(label="Recordatorios", style=discord.ButtonStyle.primary, row=4)
    async def reminders(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        view = ReportReminderSetupView(self.guild_id, self.owner_id)
        await interaction.response.send_message(content=view.summary(), view=view, ephemeral=True)

    @discord.ui.button(label="Guardar cambios", style=discord.ButtonStyle.success, row=4)
    async def save_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not self._has_pending_changes():
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        if ((self.pending_channel_id is not None
             and moderation_report_channel_id(self.guild_id) != self.original_channel_id)
            or (self.pending_reactions is not None
                and moderation_report_reactions(self.guild_id) != self.original_reactions)
            or (self.pending_condemn_emoji is not None
                and get_condemnation_emoji(self.guild_id) != self.original_condemn_emoji)):
            await interaction.response.send_message(
                "La configuración de reportes cambió mientras editaba. Recargue el editor.",
                ephemeral=True,
            )
            return
        if self.pending_reactions is not None:
            condemn_key = _moderation_emoji_key(self.pending_condemn_emoji or get_condemnation_emoji(self.guild_id))
            if any(_moderation_emoji_key(str(item["emoji"])) == condemn_key for item in self.pending_reactions):
                await interaction.response.send_message("El emoji de condena no puede coincidir con una reacción de reporte.", ephemeral=True)
                return
        if self.pending_reactions is not None:
            for item in self.pending_reactions:
                action = str(item.get("action", "report"))
                if action not in MODERATION_REPORT_ACTIONS:
                    await interaction.response.send_message(
                        "La regla incluye una acción no válida.", ephemeral=True
                    )
                    return
                if action == "timeout" and not item.get("duration_minutes"):
                    await interaction.response.send_message(
                        "Una regla de aislamiento requiere duración; edítela antes de guardar.",
                        ephemeral=True,
                    )
                    return
                if action in {"report", "warn"} and item.get("purge_minutes"):
                    await interaction.response.send_message(
                        "Solo reportar y Advertir no permiten purgar mensajes.", ephemeral=True
                    )
                    return
                if action == "warn" and (item.get("duration_minutes") or int(item.get("threshold", 1)) != 1):
                    await interaction.response.send_message(
                        "Advertir requiere umbral 1 y no admite duración.", ephemeral=True
                    )
                    return
                required = {"timeout": "moderate_members", "kick": "kick_members",
                            "ban": "ban_members", "condemn": "manage_roles"}.get(action)
                bot_member = interaction.guild.me
                if required and (
                    bot_member is None or
                    not getattr(bot_member.guild_permissions, required, False)
                ):
                    await interaction.response.send_message(
                        f"El Heraldo no tiene permisos para la acción {moderation_action_label(action)}. "
                        "Revise sus permisos antes de guardar la regla.", ephemeral=True,
                    )
                    return
        if self.pending_channel_id is not None:
            channel = interaction.guild.get_channel(self.pending_channel_id)
            me = interaction.guild.me
            perms = channel.permissions_for(me) if channel and me else None
            if not isinstance(channel, discord.TextChannel) or perms is None or not (
                perms.view_channel and perms.send_messages and perms.embed_links
            ):
                await interaction.response.send_message(
                    "El canal de reportes dejó de estar disponible o faltan permisos.",
                    ephemeral=True,
                )
                return
            set_moderation_report_channel_id(self.guild_id, self.pending_channel_id)
        if self.pending_reactions is not None:
            set_moderation_report_reactions(self.guild_id, self.pending_reactions)
        if self.pending_condemn_emoji is not None:
            guild_config_set(self.guild_id, "condemnation_emoji", self.pending_condemn_emoji)
        self.original_channel_id = moderation_report_channel_id(self.guild_id)
        self.original_reactions = copy.deepcopy(moderation_report_reactions(self.guild_id))
        self.original_condemn_emoji = get_condemnation_emoji(self.guild_id)
        self.pending_channel_id = None
        self.pending_reactions = None
        self.pending_condemn_emoji = None
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild) + "\n\nCambios guardados.", view=self)

    @discord.ui.button(label="Descartar cambios", style=discord.ButtonStyle.danger, row=4)
    async def discard_changes(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not self._has_pending_changes():
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        self.original_channel_id = moderation_report_channel_id(self.guild_id)
        self.original_reactions = copy.deepcopy(moderation_report_reactions(self.guild_id))
        self.original_condemn_emoji = get_condemnation_emoji(self.guild_id)
        self.pending_channel_id = None
        self.pending_reactions = None
        self.pending_condemn_emoji = None
        self.selected_reaction_index = None
        self._rebuild_reaction_select()
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary, row=4)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(
            content="**El Heraldo · Moderation**\n\nConfigura las funciones de moderación disponibles.",
            view=HeraldoModerationSetupView(self.guild_id, self.owner_id),
        )

class HeraldoCasesSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de configuración no es tuyo.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Actualizar", style=discord.ButtonStyle.secondary, row=0)
    async def refresh(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(content=moderation_cases_summary(interaction.guild), view=self)

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary, row=0)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(
            content="**El Heraldo · Moderation**\n\nConfigura las funciones de moderación disponibles.",
            view=HeraldoModerationSetupView(self.guild_id, self.owner_id),
        )

class HeraldoCondemnationDurationModal(discord.ui.Modal, title="Condenas · Duración predeterminada"):
    duration = discord.ui.TextInput(
        label="Duración (0 = indefinida)",
        placeholder="Ej.: 30m, 12h, 2d, 1d 12h o 0",
        required=True,
        max_length=80,
    )

    def __init__(self, guild_id: int) -> None:
        super().__init__()
        self.guild_id = guild_id
        current = condemnation_default_duration_minutes(guild_id)
        self.duration.default = format_duration(current) if current is not None else "0"

    async def on_submit(self, interaction: discord.Interaction) -> None:
        raw = str(self.duration).strip()
        if raw.casefold() in {"0", "indefinida", "indefinido", "permanente", "hasta retirar"}:
            minutes = None
            setting = "indefinida"
        else:
            try:
                minutes = parse_duration(raw, 1, get_condemnation_max_minutes(self.guild_id))
            except ValueError as exc:
                await interaction.response.send_message(f"Error: Duración inválida: {exc}", ephemeral=True)
                return
            setting = f"{minutes}m"

        await confirm_configuration(interaction, self.guild_id, {"condemnation_default_duration": setting or "indefinida"})


class CondemnationChannelAccessConfirmView(discord.ui.View):
    """Acceso al canal preparado únicamente tras confirmación expresa."""
    def __init__(self, guild_id: int, owner_id: int, channel_id: int, role_id: int) -> None:
        super().__init__(timeout=180)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.channel_id = channel_id
        self.role_id = role_id

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @discord.ui.button(label="Confirmar acceso", style=discord.ButtonStyle.success)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        guild = interaction.guild
        channel = guild.get_channel(self.channel_id)
        role = guild.get_role(self.role_id)
        me = guild.me
        if (not isinstance(channel, discord.TextChannel) or role is None or me is None
                or role.id != get_condenado_role_id(guild.id)
                or channel.id != condemnation_channel_id(guild.id)):
            await interaction.response.edit_message(
                content="La configuración cambió. Vuelve a abrir Condenas antes de confirmar.", view=None)
            return
        if not (interaction.user.guild_permissions.manage_channels
                and me.guild_permissions.manage_channels
                and channel.permissions_for(me).manage_channels):
            await interaction.response.send_message(
                "Se requiere Gestionar canales para el administrador y El Heraldo.", ephemeral=True)
            return
        try:
            await channel.set_permissions(
                role,
                view_channel=True, read_message_history=True,
                send_messages=False, send_messages_in_threads=True,
                create_public_threads=False, create_private_threads=False,
                manage_threads=False,
                reason="El Heraldo: acceso de condenados a sus hilos privados",
            )
        except discord.HTTPException:
            await interaction.response.send_message(
                "Discord rechazó los permisos. No se aplicaron cambios adicionales.", ephemeral=True)
            return
        await interaction.response.edit_message(
            content="Acceso del rol Condenado configurado. Los hilos privados solo se abren "
                    "al miembro invitado y a moderadores con Gestionar hilos. "
                    "Las tarjetas del canal principal siguen siendo visibles a quienes puedan ver el canal.",
            view=None,
        )

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(
            content="Operación cancelada. No se modificaron los permisos.", view=None)


class HeraldoCondemnationSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.pending_channel_id: int | None = None
        self.pending_role_id: int | None = None

        channel_select = discord.ui.ChannelSelect(
            placeholder="Seleccionar canal de condenados",
            channel_types=[discord.ChannelType.text],
            min_values=1,
            max_values=1,
            row=0,
        )
        channel_select.callback = self.select_channel
        self.add_item(channel_select)

        role_select = discord.ui.RoleSelect(
            placeholder="Seleccionar rol Condenado",
            min_values=1,
            max_values=1,
            row=1,
        )
        role_select.callback = self.select_role
        self.add_item(role_select)

        # Las opciones conocidas no requieren memorizar ni escribir su sintaxis.
        max_minutes = get_condemnation_max_minutes(guild_id)
        choices = [
            ("Indefinida", "0"), ("30 minutos", "30m"), ("1 hora", "1h"),
            ("6 horas", "6h"), ("12 horas", "12h"), ("1 día", "1d"),
            ("3 días", "3d"), ("7 días", "7d"), ("30 días", "30d"),
        ]
        allowed = [discord.SelectOption(label="Indefinida", value="0")]
        for label, value in choices[1:]:
            try:
                parse_duration(value, 1, max_minutes)
            except ValueError:
                continue
            allowed.append(discord.SelectOption(label=label, value=value))
        allowed.append(discord.SelectOption(
            label="Duración personalizada",
            value="custom",
            description="Introducir una duración distinta de las sugeridas",
        ))
        duration_select = discord.ui.Select(
            placeholder="Elegir duración predeterminada",
            min_values=1, max_values=1, options=allowed, row=4,
        )
        duration_select.callback = self.select_duration
        self.add_item(duration_select)

    async def select_duration(self, interaction: discord.Interaction) -> None:
        values = (interaction.data or {}).get("values", [])
        if not values:
            await interaction.response.send_message("Selecciona una duración.", ephemeral=True)
            return
        value = str(values[0])
        if value == "custom":
            await interaction.response.send_modal(HeraldoCondemnationDurationModal(self.guild_id))
            return
        if value not in {"0", "30m", "1h", "6h", "12h", "1d", "3d", "7d", "30d"}:
            await interaction.response.send_message("Duración no permitida.", ephemeral=True)
            return
        if value != "0":
            try:
                minutes = parse_duration(value, 1, get_condemnation_max_minutes(self.guild_id))
            except ValueError:
                await interaction.response.send_message("La duración supera el máximo configurado.", ephemeral=True)
                return
            selected = f"{minutes}m"
        else:
            selected = "indefinida"
        # Seleccionar no guarda: siempre presenta confirmación o Cancelar.
        await confirm_configuration(
            interaction, self.guild_id, {"condemnation_default_duration": selected},
        )

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de configuración no es tuyo.", ephemeral=True)
            return False
        return True

    def _content(self, guild: discord.Guild) -> str:
        channel = guild.get_channel(condemnation_channel_id(guild.id))
        role = guild.get_role(get_condenado_role_id(guild.id))
        items: list[str] = []
        if self.pending_channel_id is not None:
            pending_channel = guild.get_channel(self.pending_channel_id)
            items.append(f"Canal → {pending_channel.mention if pending_channel else self.pending_channel_id}")
        if self.pending_role_id is not None:
            pending_role = guild.get_role(self.pending_role_id)
            items.append(f"Rol → {pending_role.mention if pending_role else self.pending_role_id}")
        return (
            "**El Heraldo · Moderation · Condenas**\n\n"
            f"Canal de condenados: {channel.mention if isinstance(channel, discord.TextChannel) else 'no configurado'}\n"
            f"Rol Condenado: {role.mention if role else 'no configurado'}\n"
            f"Duración predeterminada: **{format_duration(condemnation_default_duration_minutes(guild.id)) if condemnation_default_duration_minutes(guild.id) is not None else 'Indefinida'}**"
            + _pending_config_text(items)
        )

    async def select_channel(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        channel = interaction.guild.get_channel(int(values[0])) if interaction.guild and values else None
        if not isinstance(channel, discord.TextChannel):
            await interaction.response.send_message("No pude localizar ese canal.", ephemeral=True)
            return
        perms = channel.permissions_for(interaction.guild.me)
        if not perms.view_channel or not perms.send_messages or not perms.embed_links:
            await interaction.response.send_message(
                "El Heraldo necesita Ver canal, Enviar mensajes e Insertar enlaces en ese canal.",
                ephemeral=True,
            )
            return
        self.pending_channel_id = channel.id
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    async def select_role(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values") if interaction.data else []
        role = interaction.guild.get_role(int(values[0])) if interaction.guild and values else None
        if role is None:
            await interaction.response.send_message("No pude localizar ese rol.", ephemeral=True)
            return
        if role.is_default() or role.managed or role >= interaction.guild.me.top_role:
            await interaction.response.send_message(
                "Ese rol no puede ser administrado por El Heraldo. Revisa jerarquía o integraciones.",
                ephemeral=True,
            )
            return
        self.pending_role_id = role.id
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Duración", style=discord.ButtonStyle.primary, row=2)
    async def duration(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.send_modal(HeraldoCondemnationDurationModal(self.guild_id))

    @discord.ui.button(label="Preparar acceso", style=discord.ButtonStyle.primary, row=2)
    async def prepare_access(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        guild = interaction.guild
        channel = guild.get_channel(condemnation_channel_id(guild.id))
        role = guild.get_role(get_condenado_role_id(guild.id))
        if not isinstance(channel, discord.TextChannel) or role is None:
            await interaction.response.send_message(
                "Configura y guarda primero el canal y el rol Condenado.", ephemeral=True)
            return
        await interaction.response.send_message(
            "El Heraldo dará al rol Condenado acceso al canal y su historial, "
            "permiso para responder en hilos, pero no para publicar directamente en el canal, "
            "crear hilos o gestionar hilos. Esta acción modificará los permisos del canal. "
            "Las tarjetas principales serán visibles a todos los miembros con acceso al canal. "
            "¿Confirmas el cambio?",
            view=CondemnationChannelAccessConfirmView(guild.id, interaction.user.id, channel.id, role.id),
            ephemeral=True,
        )

    @discord.ui.button(label="Crear canal", style=discord.ButtonStyle.success, row=2)
    async def create_channel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        guild = interaction.guild
        existing_id = get_guild_channel_id(self.guild_id, "condemned")
        channel = guild.get_channel(existing_id) if existing_id else None
        created_now = False
        if not isinstance(channel, discord.TextChannel):
            channel = next((c for c in guild.text_channels if c.name.casefold() == "condenados"), None)
        if not isinstance(channel, discord.TextChannel):
            me = guild.me
            if me is None or not me.guild_permissions.manage_channels:
                await interaction.response.send_message(
                    "El Heraldo necesita Gestionar canales para crear el canal de condenados.",
                    ephemeral=True,
                )
                return
            await interaction.response.defer(ephemeral=True)
            try:
                channel = await guild.create_text_channel(
                    "Condenados",
                    reason="El Heraldo: crear canal de condenados desde /setup",
                )
                created_now = True
            except discord.HTTPException as exc:
                await interaction.followup.send(f"No pude crear el canal: `{exc}`.", ephemeral=True)
                return
        else:
            await interaction.response.defer(ephemeral=True)

        note = await _setup_apply_system_channel(guild, "condemned", channel, publish_messages=True)
        self.pending_channel_id = None
        action = "Creé" if created_now else "Reutilicé"
        await interaction.edit_original_response(
            content=self._content(guild) + f"\n\n{action} {channel.mention}. {note}",
            view=self,
        )

    @discord.ui.button(label="Crear rol Condenado", style=discord.ButtonStyle.success, row=2)
    async def create_role(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.defer(ephemeral=True)
        role, created_now, error = await _setup_get_or_create_system_role(
            interaction.guild, "condenado", "Condenado", "Condenado"
        )
        if error or role is None:
            await interaction.followup.send(error or "No pude preparar el rol.", ephemeral=True)
            return
        self.pending_role_id = None
        action = "Creé" if created_now else "Reutilicé"
        await interaction.edit_original_response(
            content=self._content(interaction.guild) + f"\n\n{action} {role.mention} como rol Condenado.",
            view=self,
        )

    @discord.ui.button(label="Guardar cambios", style=discord.ButtonStyle.success, row=3)
    async def save(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self.pending_channel_id is None and self.pending_role_id is None:
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        if self.pending_channel_id is not None:
            channel = interaction.guild.get_channel(self.pending_channel_id)
            if isinstance(channel, discord.TextChannel):
                await _setup_apply_system_channel(interaction.guild, "condemned", channel, publish_messages=True)
        if self.pending_role_id is not None:
            guild_resource_set(self.guild_id, "role", "condenado", self.pending_role_id)
        self.pending_channel_id = self.pending_role_id = None
        await interaction.edit_original_response(content=self._content(interaction.guild) + "\n\nCambios guardados.", view=self)

    @discord.ui.button(label="Descartar", style=discord.ButtonStyle.danger, row=3)
    async def discard(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.pending_channel_id = self.pending_role_id = None
        await interaction.response.edit_message(content=self._content(interaction.guild), view=self)

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary, row=3)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(
            content="**El Heraldo · Moderation**\n\nConfigura las funciones de moderación disponibles.",
            view=HeraldoModerationSetupView(self.guild_id, self.owner_id),
        )



class HeraldoBanDurationModal(discord.ui.Modal, title="Duración personalizada de baneo"):
    duration = discord.ui.TextInput(label="Duración del baneo", placeholder="Ejemplo: 10m, 2h o 7d",
                                    required=True, max_length=30)

    def __init__(self, guild_id: int, owner_id: int):
        super().__init__()
        self.guild_id, self.owner_id = guild_id, owner_id

    async def on_submit(self, interaction: discord.Interaction) -> None:
        if not await configuration_access(interaction, self.guild_id, self.owner_id):
            return
        try:
            minutes = parse_duration(str(self.duration).strip(), 1, 365 * 24 * 60)
        except ValueError as exc:
            await interaction.response.send_message(f"Duración inválida: {exc}", ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id,
                                    {"moderation_default_ban_minutes": str(minutes)})


class HeraldoBanDurationSetupView(discord.ui.View):
    """Elegir una duración solo abre una revisión. Cancelar no guarda."""
    CHOICES = (
        ("0", "Permanente"), ("1", "1 minuto"), ("2", "2 minutos"),
        ("5", "5 minutos"), ("10", "10 minutos"), ("30", "30 minutos"),
        ("60", "1 hora"), ("1440", "1 día"), ("10080", "7 días"),
    )

    def __init__(self, guild_id: int, owner_id: int):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        current = moderation_default_ban_minutes(guild_id)
        selector = discord.ui.Select(
            placeholder="Duración predeterminada de BAN",
            options=[discord.SelectOption(label=label, value=value, default=int(value) == (current or 0))
                     for value, label in self.CHOICES], row=0,
        )
        selector.callback = self.choose
        self.add_item(selector)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    def content(self) -> str:
        minutes = moderation_default_ban_minutes(self.guild_id)
        return (
            "**El Heraldo · Moderation · Baneo temporal**\n\n"
            f"Duración predeterminada: **{format_duration(minutes) if minutes else 'Permanente'}**.\n"
            "La duración explícita de /ban o de una reacción tiene prioridad.\n"
            "Sin configurar: 5 minutos en El Heraldo Test; permanente en producción.\n\n"
            "Seleccione o personalice una duración y confirme Guardar cambios. Cancelar nunca guarda."
        )

    async def choose(self, interaction: discord.Interaction) -> None:
        values = interaction.data.get("values", []) if interaction.data else []
        if len(values) != 1 or values[0] not in {v for v, _ in self.CHOICES}:
            await interaction.response.send_message("Duración no válida.", ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id,
                                    {"moderation_default_ban_minutes": values[0]})

    @discord.ui.button(label="Personalizar", style=discord.ButtonStyle.primary, row=1)
    async def custom(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.send_modal(HeraldoBanDurationModal(self.guild_id, self.owner_id))

    @discord.ui.button(label="Volver", style=discord.ButtonStyle.secondary, row=1)
    async def back(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.edit_message(
            content="**El Heraldo · Moderation**\n\nConfigura las funciones de moderación disponibles.",
            view=HeraldoModerationSetupView(self.guild_id, self.owner_id))


