DATE_FORMAT_CHOICES = {
    "discord": "Fecha y hora local de cada usuario (Discord)",
    "dmy24": "Día/mes/año, reloj de 24 horas",
    "mdy12": "Mes/día/año, reloj de 12 horas",
    "iso": "Año-mes-día, reloj de 24 horas",
}


def date_format_setup_summary(guild_id: int) -> str:
    choice = guild_config_get(guild_id, "display_date_format") or "discord"
    if choice not in DATE_FORMAT_CHOICES:
        choice = "discord"
    examples = {
        "discord": "<t:1792080000:F> (adaptado a cada miembro)",
        "dmy24": "15/10/2026 16:00",
        "mdy12": "10/15/2026 4:00 PM",
        "iso": "2026-10-15 16:00",
    }
    return (
        "**El Heraldo · Formato de fecha**\n\n"
        f"**Actual:** {DATE_FORMAT_CHOICES[choice]}\n"
        f"**Ejemplo:** {examples[choice]}\n\n"
        "Los formatos personalizados se usan en mensajes nuevos y paneles dinámicos "
        "compatibles. Los expedientes históricos no se alteran. "
        "Discord utiliza la hora local de cada usuario cuando se selecciona su formato nativo."
    )


def format_configured_datetime(guild_id: int, dt: datetime) -> str:
    """Representar una fecha sin alterar el instante original."""
    mode = guild_config_get(guild_id, "display_date_format") or "discord"
    moment = dt if dt.tzinfo else dt.replace(tzinfo=timezone.utc)
    if mode == "discord" or mode not in DATE_FORMAT_CHOICES:
        return discord.utils.format_dt(moment, "f")
    from zoneinfo import ZoneInfo
    local = moment.astimezone(ZoneInfo("America/Santo_Domingo"))
    if mode == "dmy24":
        return local.strftime("%d/%m/%Y %H:%M")
    if mode == "mdy12":
        return local.strftime("%m/%d/%Y %I:%M %p").replace(" 0", " ")
    return local.strftime("%Y-%m-%d %H:%M")


class HeraldoDateFormatSetupView(discord.ui.View):
    def __init__(self, guild_id: int, owner_id: int):
        super().__init__(timeout=900)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.original = guild_config_get(guild_id, "display_date_format") or "discord"
        self.pending = self.original
        selection = discord.ui.Select(
            placeholder="Seleccionar formato de fecha",
            options=[discord.SelectOption(label=label, value=value,
                                          default=value == self.pending)
                     for value, label in DATE_FORMAT_CHOICES.items()],
            row=0,
        )
        selection.callback = self.select_format
        self.add_item(selection)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    async def select_format(self, interaction: discord.Interaction) -> None:
        value = (interaction.data or {}).get("values", [None])[0]
        if value not in DATE_FORMAT_CHOICES:
            await interaction.response.send_message("Formato de fecha no válido.", ephemeral=True)
            return
        self.pending = value
        for item in self.children:
            if isinstance(item, discord.ui.Select):
                for option in item.options:
                    option.default = option.value == value
        await interaction.response.edit_message(
            content=date_format_setup_summary(self.guild_id)
                    + f"\n\n**Borrador SIN GUARDAR:** {DATE_FORMAT_CHOICES[self.pending]}\n"
                      "Pulse Revisar y confirmar para proponer el cambio, y Guardar cambios en la confirmación final.",
            view=self,
        )

    @discord.ui.button(label="Revisar y confirmar", style=discord.ButtonStyle.primary, row=1)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if (guild_config_get(self.guild_id, "display_date_format") or "discord") != self.original:
            await interaction.response.send_message(
                "La configuración cambió mientras editaba. Vuelva a abrir el panel.", ephemeral=True)
            return
        if self.pending == self.original:
            await interaction.response.send_message("No hay cambios pendientes.", ephemeral=True)
            return
        await confirm_configuration(interaction, self.guild_id, {"display_date_format": self.pending})

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger, row=1)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.stop()
        await interaction.response.edit_message(content="Edición cancelada. No se guardaron cambios.", view=None)


class HeraldoSetupView(discord.ui.View):
    """Navegación directa: abrir un módulo al elegirlo, sin pasos redundantes."""

    MODULES = (
        ("automod", "AutoMod", "Protecciones automáticas del servidor"),
        ("moderation", "Moderation", "Condenas, reportes y casos"),
        ("join_roles", "Join Roles", "Roles al entrar al servidor"),
        ("reaction_roles", "Reaction Roles", "Configuración de roles por reacción"),
        ("role_connections", "Role Connections", "Conexiones de roles (pendiente)"),
        ("logging", "Logs", "Eventos y canales de registros"),
        ("messages", "Mensajes", "Plantillas y mensajes predeterminados"),
        ("verification", "Verification", "Verificación y personalidad"),
        ("language", "Idioma", "Configuración del idioma (pendiente)"),
        ("date_format", "Formato de fecha", "Fechas y horas en los mensajes del bot"),
    )

    def __init__(self, guild_id: int, owner_id: int) -> None:
        super().__init__(timeout=900)
        self.guild_id = guild_id
        self.owner_id = owner_id
        self.selected_module: str | None = None

        select = discord.ui.Select(
            placeholder="Elige una sección para abrirla",
            min_values=1,
            max_values=1,
            row=0,
            options=[
                discord.SelectOption(
                    label=label,
                    value=key,
                    description=description,
                )
                for key, label, description in self.MODULES
                if key not in {"role_connections", "language"}
            ],
        )
        select.callback = self.select_module
        self.module_select = select
        self.add_item(select)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if not await configuration_access(interaction, getattr(self, "guild_id", None), getattr(self, "owner_id", None)):
            return False
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel de configuración no es tuyo.", ephemeral=True)
            return False
        return True

    async def select_module(self, interaction: discord.Interaction) -> None:
        # Confirmar inmediatamente la interacción. No necesitamos editar el embed
        # cada vez que se cambia el desplegable.
        # Leer el valor enviado por Discord en esta interacción, sin depender
        # de estado cacheado de la instancia de la vista.
        values = (interaction.data or {}).get("values", [])
        if not values:
            await interaction.response.send_message("Selecciona un módulo.", ephemeral=True)
            return
        selected = str(values[0])
        if selected not in {item[0] for item in self.MODULES}:
            await interaction.response.send_message("Módulo no válido.", ephemeral=True)
            return
        self.selected_module = selected
        await self.configure(interaction, None)

    async def configure(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        selected = self.selected_module
        if selected is None:
            await interaction.response.send_message(
                "Selecciona primero un módulo en el menú desplegable.",
                ephemeral=True,
            )
            return

        if selected == "date_format":
            content = date_format_setup_summary(self.guild_id)
            view = HeraldoDateFormatSetupView(self.guild_id, self.owner_id)
        elif selected == "automod":
            content = "**El Heraldo · AutoMod**\n\nConfigura las protecciones automáticas del servidor."
            view = HeraldoAutomodSetupView(self.guild_id, self.owner_id)
        elif selected == "moderation":
            content = "**El Heraldo · Moderation**\n\nConfigura las funciones de moderación disponibles."
            view = HeraldoModerationSetupView(self.guild_id, self.owner_id)
        elif selected == "join_roles":
            content = "**El Heraldo · Join Roles**\n\n" + join_roles_summary(interaction.guild)
            view = HeraldoJoinRolesSetupView(self.guild_id, self.owner_id)
        elif selected == "reaction_roles":
            view = HeraldoReactionRolesSetupView(self.guild_id, self.owner_id)
            content = view.summary(interaction.guild)
        elif selected == "role_connections":
            content = (
                "**El Heraldo · Role Connections**\n\n"
                "Módulo reservado. La configuración se implementará cuando definamos su alcance."
            )
            view = HeraldoPendingSetupModuleView(self.guild_id, self.owner_id, "Role Connections")
        elif selected == "logging":
            view = HeraldoLoggingSetupView(self.guild_id, self.owner_id)
            content = view._content(interaction.guild)
        elif selected == "messages":
            content = heraldo_messages_setup_content()
            view = HeraldoMessagesSetupView(self.guild_id, self.owner_id)
        elif selected == "verification":
            content = verification_hub_content(self.guild_id)
            view = HeraldoVerificationHubView(self.guild_id, self.owner_id)
        elif selected == "language":
            content = (
                "**El Heraldo · Idioma**\n\n"
                "Módulo reservado para la internacionalización del bot."
            )
            view = HeraldoPendingSetupModuleView(self.guild_id, self.owner_id, "Idioma")
        else:
            await interaction.response.send_message("Módulo no válido.", ephemeral=True)
            return

        # Una sola respuesta de actualización, sin defer + segunda llamada HTTP.
        await interaction.response.edit_message(content=content, embed=None, view=view)

    async def on_error(
        self, interaction: discord.Interaction, error: Exception, item: discord.ui.Item,
    ) -> None:
        # No dejar interacciones silenciosas si falla la navegación.
        print(
            f"Error: /setup: error en {type(item).__name__} "
            f"(guild={self.guild_id}, module={self.selected_module}): {error!r}"
        )
        traceback.print_exception(type(error), error, error.__traceback__)
        try:
            if interaction.response.is_done():
                await interaction.followup.send(
                    "Error: Error al abrir la configuración. Revisa los logs de El Heraldo.",
                    ephemeral=True,
                )
            else:
                await interaction.response.send_message(
                    "Error: Error al abrir la configuración. Revisa los logs de El Heraldo.",
                    ephemeral=True,
                )
        except discord.HTTPException:
            pass

    @discord.ui.button(label="Cerrar", style=discord.ButtonStyle.danger, row=1)
    async def close(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.stop()
        await interaction.response.edit_message(content="Panel de configuración cerrado.", view=None)




@bot.tree.command(name="importkit", description="Importa un archivo JSON de plantillas con revisión y confirmación.")
@app_commands.default_permissions(manage_guild=True)
@app_commands.guild_only()
async def heraldo_importkit(interaction: discord.Interaction, archivo: discord.Attachment, reemplazar: bool = False):
    if not await configuration_access(interaction):
        return
    if archivo.size > 131072 or not archivo.filename.lower().endswith('.json'):
        await interaction.response.send_message("Se admite un archivo JSON de hasta 128 KiB.", ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True)
    try:
        raw = await archivo.read()
        if len(raw) > 131072:
            raise ValueError('Archivo demasiado grande.')
        items = message_payload.import_kit(json.loads(raw.decode('utf-8-sig')))
    except (ValueError, UnicodeError, discord.HTTPException):
        await interaction.followup.send("El archivo no contiene un kit válido.", ephemeral=True)
        return
    current = heraldo_template_list(interaction.guild.id)
    names = {x['name'].casefold() for x in current}
    duplicates = [x['name'] for x in items if x['name'].casefold() in names]
    if duplicates and not reemplazar:
        await interaction.followup.send("Hay nombres repetidos. Renombre las plantillas o solicite reemplazo explícito.", ephemeral=True)
        return
    if len(current) + len(items) - (len(duplicates) if reemplazar else 0) > 25:
        await interaction.followup.send("Se superaría el máximo de 25 plantillas.", ephemeral=True)
        return
    summary = f"Propuesta: {len(items) - len(duplicates)} nuevas, {len(duplicates)} reemplazos.\n"
    summary += '\n'.join(('Reemplazar: ' if x['name'] in duplicates else 'Añadir: ') + discord.utils.escape_markdown(x['name']) for x in items)
    await interaction.followup.send(summary + "\nLas acciones privilegiadas se excluyen. Confirme para aplicar.",
        view=HeraldoMessageConfirmView(interaction.guild.id, interaction.user.id, 'kit', {'items': items, 'replace': reemplazar}),
        ephemeral=True, allowed_mentions=discord.AllowedMentions.none())


@bot.tree.command(name="sendtemplate", description="Publica una plantilla de mensajes del servidor.")
@app_commands.default_permissions(manage_messages=True)
@app_commands.guild_only()
async def heraldo_sendtemplate(interaction: discord.Interaction, canal: discord.TextChannel, plantilla: str):
    if not isinstance(interaction.user, discord.Member) or not interaction.user.guild_permissions.manage_messages:
        await interaction.response.send_message("Se requiere el permiso Administrar mensajes.", ephemeral=True)
        return
    user_perms = canal.permissions_for(interaction.user)
    if canal.guild.id != interaction.guild.id or not user_perms.view_channel or not user_perms.send_messages or not user_perms.manage_messages:
        await interaction.response.send_message("Se requiere acceso y Administrar mensajes en el canal de destino.", ephemeral=True)
        return
    item = next((t for t in heraldo_template_list(interaction.guild.id)
                 if t["name"].casefold() == plantilla.strip().casefold()), None)
    if not item:
        await interaction.response.send_message("La plantilla indicada no existe. Consulta /setup → Mensajes.", ephemeral=True)
        return
    me = interaction.guild.me
    perms = canal.permissions_for(me) if me else None
    if not perms or not perms.send_messages or not perms.embed_links:
        await interaction.response.send_message("El Heraldo necesita Enviar mensajes e Insertar enlaces en ese canal.", ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True)
    try:
        sent = await canal.send(**heraldo_template_payload(item, interaction.guild, interaction.user, canal))
    except (discord.HTTPException, ValueError):
        await interaction.followup.send("No se pudo publicar la plantilla. Revisa el contenido y los permisos.", ephemeral=True)
        return
    await interaction.followup.send(f"Mensaje publicado correctamente en {canal.mention}: {sent.jump_url}", ephemeral=True)


@heraldo_sendtemplate.autocomplete("plantilla")
async def heraldo_sendtemplate_autocomplete(interaction: discord.Interaction, current: str):
    if not interaction.guild_id:
        return []
    return [app_commands.Choice(name=t["name"][:100], value=t["name"][:100])
            for t in heraldo_template_list(interaction.guild_id)
            if current.casefold() in t["name"].casefold()][:25]



class HeraldoEditTemplateConfirmView(discord.ui.View):
    """Edición manual de un mensaje del bot; no se ejecuta al seleccionar la plantilla."""
    def __init__(self, guild_id: int, owner_id: int, channel_id: int, message_id: int, template_name: str):
        super().__init__(timeout=300)
        self.guild_id, self.owner_id, self.channel_id = guild_id, owner_id, channel_id
        self.message_id, self.template_name = message_id, template_name

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.guild_id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message("Esta confirmación no te pertenece.", ephemeral=True)
            return False
        if not isinstance(interaction.user, discord.Member) or not interaction.user.guild_permissions.manage_messages:
            await interaction.response.send_message("Se requiere Administrar mensajes.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Confirmar edición", style=discord.ButtonStyle.success)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not await self.interaction_check(interaction):
            return
        guild = interaction.guild
        channel = guild.get_channel(self.channel_id) if guild else None
        item = next((x for x in heraldo_template_list(self.guild_id) if x["name"] == self.template_name), None)
        if not isinstance(channel, discord.TextChannel) or not item:
            await interaction.response.send_message("El canal o la plantilla ya no está disponible.", ephemeral=True)
            return
        me = guild.me
        user_perms = channel.permissions_for(interaction.user)
        if not user_perms.view_channel or not user_perms.manage_messages or not user_perms.send_messages:
            await interaction.response.send_message("Ya no dispone de permisos para editar mensajes en ese canal.", ephemeral=True)
            return
        perms = channel.permissions_for(me) if me else None
        if not perms or not perms.view_channel or not perms.read_message_history or not perms.send_messages or not perms.embed_links:
            await interaction.response.send_message("Permisos insuficientes para editar el mensaje.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True)
        try:
            message = await channel.fetch_message(self.message_id)
            if not me or message.author.id != me.id:
                await interaction.followup.send("Solo se pueden editar mensajes publicados por este bot.", ephemeral=True)
                return
            await message.edit(**heraldo_template_payload(item, guild, interaction.user, channel))
        except (discord.HTTPException, discord.NotFound, ValueError):
            await interaction.followup.send("No fue posible actualizar el mensaje.", ephemeral=True)
            return
        self.stop()
        await interaction.edit_original_response(content="Mensaje actualizado por confirmación del administrador.", view=None)
        await interaction.followup.send("Edición completada.", ephemeral=True)

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.stop()
        await interaction.response.edit_message(content="Edición cancelada. El mensaje original permanece intacto.", view=None)


@bot.tree.command(name="edittemplate", description="Edita un mensaje del Heraldo con una plantilla, previa confirmación.")
@app_commands.default_permissions(manage_messages=True)
@app_commands.guild_only()
async def heraldo_edittemplate(interaction: discord.Interaction, enlace: str, plantilla: str):
    if not isinstance(interaction.user, discord.Member) or not interaction.user.guild_permissions.manage_messages:
        await interaction.response.send_message("Se requiere Administrar mensajes.", ephemeral=True)
        return
    match = re.fullmatch(r"https://(?:discord(?:app)?\.com)/channels/(\d+)/(\d+)/(\d+)", enlace.strip())
    if not match or int(match.group(1)) != interaction.guild.id:
        await interaction.response.send_message("Introduce el enlace a un mensaje de este servidor.", ephemeral=True)
        return
    channel_id, message_id = int(match.group(2)), int(match.group(3))
    channel = interaction.guild.get_channel(channel_id)
    item = next((x for x in heraldo_template_list(interaction.guild.id)
                 if x["name"].casefold() == plantilla.strip().casefold()), None)
    if not isinstance(channel, discord.TextChannel) or item is None:
        await interaction.response.send_message("El canal o la plantilla no existe.", ephemeral=True)
        return
    user_perms = channel.permissions_for(interaction.user)
    if not user_perms.view_channel or not user_perms.manage_messages or not user_perms.read_message_history:
        await interaction.response.send_message("Se requiere acceso y Administrar mensajes en el canal de destino.", ephemeral=True)
        return
    me = interaction.guild.me
    perms = channel.permissions_for(me) if me else None
    if not perms or not perms.view_channel or not perms.read_message_history:
        await interaction.response.send_message("El Heraldo no puede consultar ese mensaje.", ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True)
    try:
        message = await channel.fetch_message(message_id)
    except discord.HTTPException:
        await interaction.followup.send("No se encontró el mensaje.", ephemeral=True)
        return
    if not me or message.author.id != me.id:
        await interaction.followup.send("La edición solo está permitida para mensajes del Heraldo.", ephemeral=True)
        return
    await interaction.followup.send(
        "**El Heraldo · Edición pendiente**\n\n"
        + f"Plantilla: **{discord.utils.escape_markdown(item['name'])}**\n"
        + f"Mensaje de destino: {message.jump_url}\n\n"
        + "La publicación actual no cambiará hasta pulsar **Confirmar edición**.",
        view=HeraldoEditTemplateConfirmView(interaction.guild.id, interaction.user.id,
                                             channel_id, message_id, item["name"]),
        ephemeral=True, allowed_mentions=discord.AllowedMentions.none(),
    )


