def condemnation_default_duration_minutes(guild_id: int | None = None) -> int | None:
    """Duración predeterminada para nuevas condenas. None = indefinida."""
    value = guild_config_get(guild_id, "condemnation_default_duration") if guild_id is not None else None
    if value is None:
        if legacy_fallback_allowed(guild_id):
            value = db_meta_get("condemnation_default_duration")
    if not value or value.strip().lower() in {"indefinida", "indefinido", "none", "null", "0"}:
        return None
    try:
        return parse_duration(value, 1, get_condemnation_max_minutes(guild_id))
    except ValueError:
        return None


def set_condemnation_default_duration(value: str | None, guild_id: int | None = None) -> None:
    if guild_id is not None:
        guild_config_set(guild_id, "condemnation_default_duration", value or "indefinida")
    else:
        db_meta_set("condemnation_default_duration", value or "indefinida")


def condemnation_channel_id(guild_id: int | None = None) -> int:
    if guild_id is None:
        value = db_meta_get("condemned_channel_id")
        return int(value) if value else CONDEMNED_CHANNEL_ID
    configured = get_guild_channel_id(guild_id, "condemned")
    if configured:
        return configured
    value = guild_config_get(guild_id, "condemned_channel_id")
    if value:
        return int(value)
    if legacy_fallback_allowed(guild_id):
        value = db_meta_get("condemned_channel_id")
        return int(value) if value else CONDEMNED_CHANNEL_ID
    return 0


def get_condemnation_emoji(guild_id: int | None = None) -> str:
    if guild_id is not None:
        value = guild_config_get(guild_id, "condemnation_emoji")
        if value:
            return value
    if legacy_fallback_allowed(guild_id):
        return db_meta_get("condemnation_emoji") or CONDEMNED_EMOJI
    return CONDEMNED_EMOJI



MODERATION_CASE_TYPES = {"WARN", "MUTE", "KICK", "BAN", "CONDEMN"}


# El número entero permanece como clave interna. El código público es reversible,
# alfanumérico y tiene exactamente siete caracteres, sin migrar claves externas.
CASE_CODE_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
CASE_CODE_MODULUS = 36 ** 6
CASE_CODE_MULTIPLIER = 1009
CASE_CODE_OFFSET = 20000000


def _legacy_case_code(number: int) -> str:
    value = (number * CASE_CODE_MULTIPLIER + CASE_CODE_OFFSET) % CASE_CODE_MODULUS
    chars = []
    for _ in range(6):
        value, digit = divmod(value, 36)
        chars.append(CASE_CODE_ALPHABET[digit])
    return "C" + "".join(reversed(chars))


def _case_code_table(conn: sqlite3.Connection) -> None:
    conn.execute(
        "CREATE TABLE IF NOT EXISTS moderation_case_codes ("
        "guild_id INTEGER NOT NULL, case_number INTEGER NOT NULL, "
        "code TEXT NOT NULL UNIQUE, PRIMARY KEY(guild_id, case_number))"
    )


def moderation_case_code(number: int, guild_id: int) -> str:
    """Obtener o asignar de forma persistente un código público aleatorio único."""
    import secrets
    conn = db_connect()
    try:
        _case_code_table(conn)
        row = conn.execute(
            "SELECT code FROM moderation_case_codes WHERE guild_id=? AND case_number=?",
            (guild_id, number),
        ).fetchone()
        if row:
            return str(row[0])
        for _ in range(30):
            code = "".join(secrets.choice(CASE_CODE_ALPHABET) for _ in range(7))
            if not any(ch.isalpha() for ch in code) or not any(ch.isdigit() for ch in code):
                continue
            try:
                conn.execute(
                    "INSERT INTO moderation_case_codes(guild_id, case_number, code) VALUES (?,?,?)",
                    (guild_id, number, code),
                )
                return code
            except sqlite3.IntegrityError:
                row = conn.execute(
                    "SELECT code FROM moderation_case_codes WHERE guild_id=? AND case_number=?",
                    (guild_id, number),
                ).fetchone()
                if row:
                    return str(row[0])
        raise RuntimeError("No fue posible generar un identificador único.")
    finally:
        conn.close()


def moderation_case_number(code: str, guild_id: int) -> int:
    value = str(code).strip().upper()
    if value.isdecimal():
        return int(value)
    if value.startswith("C-") and value[2:].isdecimal():
        return int(value[2:])
    if len(value) != 7 or any(ch not in CASE_CODE_ALPHABET for ch in value):
        raise ValueError("Código inválido. Introduzca siete caracteres alfanuméricos.")
    conn = db_connect()
    try:
        _case_code_table(conn)
        row = conn.execute(
            "SELECT case_number FROM moderation_case_codes WHERE guild_id=? AND code=?",
            (guild_id, value),
        ).fetchone()
        if row:
            return int(row[0])
        # Compatibilidad con códigos de la versión anterior.
        if value.startswith("C"):
            encoded = 0
            for ch in value[1:]:
                encoded = encoded * 36 + CASE_CODE_ALPHABET.index(ch)
            number = ((encoded - CASE_CODE_OFFSET) * pow(CASE_CODE_MULTIPLIER, -1, CASE_CODE_MODULUS)) % CASE_CODE_MODULUS
            if number >= 1 and _legacy_case_code(number) == value:
                existing = conn.execute(
                    "SELECT 1 FROM moderation_cases WHERE guild_id=? AND case_number=?",
                    (guild_id, number),
                ).fetchone()
                if existing:
                    return number
    finally:
        conn.close()
    raise ValueError("No existe un expediente con ese identificador.")


def moderation_case_next_number(guild_id: int) -> int:
    conn = db_connect()
    row = conn.execute(
        "SELECT COALESCE(MAX(case_number), 0) + 1 FROM moderation_cases WHERE guild_id = ?",
        (guild_id,),
    ).fetchone()
    conn.close()
    return int(row[0])


def moderation_case_get(guild_id: int, case_number: int) -> sqlite3.Row | None:
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    row = conn.execute(
        "SELECT * FROM moderation_cases WHERE guild_id = ? AND case_number = ?",
        (guild_id, case_number),
    ).fetchone()
    conn.close()
    return row


def moderation_case_list(guild_id: int, user_id: int | None = None, case_type: str | None = None, open_only: bool | None = None, limit: int = 20) -> list[sqlite3.Row]:
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    where = ["guild_id = ?"]
    params: list[object] = [guild_id]
    if user_id is not None:
        where.append("user_id = ?")
        params.append(user_id)
    if case_type:
        where.append("type = ?")
        params.append(case_type.upper())
    if open_only is not None:
        where.append("open = ?")
        params.append(1 if open_only else 0)
    params.append(max(1, min(limit, 50)))
    rows = conn.execute(
        "SELECT * FROM moderation_cases WHERE " + " AND ".join(where) + " ORDER BY case_number DESC LIMIT ?",
        params,
    ).fetchall()
    conn.close()
    return rows


def moderation_case_message_history(guild_id: int, user_id: int) -> str:
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    rows = conn.execute(
        "SELECT channel_id, message_id, content, attachments, created_at FROM moderation_message_cache "
        "WHERE guild_id = ? AND user_id = ? ORDER BY channel_id, created_at DESC",
        (guild_id, user_id),
    ).fetchall()
    conn.close()
    grouped: dict[int, list[dict[str, object]]] = {}
    for row in rows:
        bucket = grouped.setdefault(int(row["channel_id"]), [])
        if len(bucket) >= 5:
            continue
        try:
            attachment_list = json.loads(row["attachments"] or "[]")
        except json.JSONDecodeError:
            attachment_list = []
        bucket.append({
            "message_id": int(row["message_id"]),
            "content": (row["content"] or "")[:1000],
            "attachments": attachment_list,
            "created_at": row["created_at"],
        })
    return json.dumps(grouped, ensure_ascii=False)


MODERATION_WARN_MAX_DEFAULT = 3
MODERATION_WARN_MAX_ALLOWED = 5
MODERATION_REPORT_TOGGLABLE_ACTIONS = ("warn", "timeout", "kick", "ban", "condemn")
MODERATION_WARN_ESCALATION_ACTIONS = {"none", "timeout", "kick", "ban", "condemn"}
MODERATION_WARN_ESCALATION_DURATION_CHOICES = (30, 60, 1440, 10080)


def moderation_report_punishment_enabled(guild_id: int, action: str) -> bool:
    """Controles específicos de reportes. No alteran los comandos manuales."""
    return action not in MODERATION_REPORT_TOGGLABLE_ACTIONS or (
        guild_config_get(guild_id, f"moderation_reaction_{action}_enabled") != "0"
    )


def moderation_warn_escalation_action(guild_id: int) -> str:
    value = guild_config_get(guild_id, "moderation_warn_limit_action") or "none"
    return value if value in MODERATION_WARN_ESCALATION_ACTIONS else "none"


def moderation_warn_escalation_duration(guild_id: int) -> int:
    minutes = guild_setting_int(guild_id, "moderation_warn_limit_mute_minutes", 60)
    return minutes if minutes in MODERATION_WARN_ESCALATION_DURATION_CHOICES else 60


async def moderation_warning_escalation(
    guild: discord.Guild, member: discord.Member, case_number: int,
    current: int, maximum: int,
) -> str:
    """Actúa una sola vez al cruzar el límite; no reintenta sanciones inciertas."""
    if current != maximum:
        return ""
    action = moderation_warn_escalation_action(guild.id)
    if action == "none":
        return "Máximo alcanzado: pendiente de revisión administrativa."
    if not moderation_report_punishment_enabled(guild.id, action):
        return "Máximo alcanzado: la acción configurada está desactivada."
    bot_member = guild.me
    required = {"timeout": "moderate_members", "kick": "kick_members",
                "ban": "ban_members", "condemn": "manage_roles"}[action]
    if (bot_member is None
            or not getattr(bot_member.guild_permissions, required, False)
            or member.top_role >= bot_member.top_role):
        return "Máximo alcanzado: faltan permisos o jerarquía para aplicar la acción."
    protection = condemnation_protection_reason(member)
    if member.bot or protection:
        return "Máximo alcanzado: el miembro está protegido frente a acciones automáticas."

    # La reclamación se persiste ANTES de comunicarse con Discord; si el bot
    # se detiene después, no se ejecuta a ciegas una segunda sanción.
    try:
        conn = db_connect()
        try:
            changed = conn.execute(
                "INSERT OR IGNORE INTO moderation_warn_escalations "
                "(guild_id,user_id,warn_case_number,action,status,created_at) "
                "VALUES (?,?,?,?,'pending',?)",
                (guild.id, member.id, case_number, action, datetime.now(timezone.utc).isoformat()),
            ).rowcount
        finally:
            conn.close()
    except sqlite3.Error:
        return "No se pudo reservar la acción automática; revisión administrativa necesaria."
    if not changed:
        return "La acción por límite ya estaba registrada; no se repetirá."

    reason = f"Máximo de advertencias alcanzado ({current}/{maximum}). Expediente {moderation_case_code(case_number, guild.id)}"
    ban_minutes = moderation_effective_ban_minutes(guild.id, None) if action == "ban" else None
    outcome = "failed"
    message = "Acción no completada; revisión administrativa necesaria."
    try:
        if action == "timeout":
            minutes = moderation_warn_escalation_duration(guild.id)
            await member.timeout(datetime.now(timezone.utc) + timedelta(minutes=minutes), reason=reason)
        elif action == "kick":
            await heraldo_kick(member, reason=reason)
        elif action == "ban":
            await heraldo_ban(member, reason=reason, delete_message_seconds=0,
                              duration_minutes=ban_minutes, record_case=False)
        elif action == "condemn":
            successful, detail = await condemn_member(
                member, reason=reason, duration_minutes=condemnation_default_duration_minutes(guild.id),
                purge_spec=None, origin="warning_limit", applied_by=None,
            )
            if not successful:
                raise RuntimeError("Condena no confirmada")
        if action in {"timeout", "kick", "ban"}:
            case_type = {"timeout": "MUTE", "kick": "KICK", "ban": "BAN"}[action]
            try:
                moderation_case_create(
                    guild.id, case_type, member.id, reason,
                    duration_minutes=moderation_warn_escalation_duration(guild.id)
                    if action == "timeout" else ban_minutes if action == "ban" else None, author_id=None,
                )
            except Exception:
                outcome = "review"
                message = "Acción ejecutada, pero no fue posible registrar su expediente; revisión necesaria."
        if outcome != "review":
            outcome = "complete"
            message = f"Acción al alcanzar el máximo: {moderation_action_label(action)}."
    except Exception:
        # No repetir automáticamente una sanción que pudo haber tenido efecto.
        message = "Acción por límite no confirmada; requiere revisión, sin reintento automático."
    finally:
        try:
            conn = db_connect()
            try:
                conn.execute(
                    "UPDATE moderation_warn_escalations SET status=? "
                    "WHERE guild_id=? AND user_id=? AND warn_case_number=?",
                    (outcome, guild.id, member.id, case_number),
                )
            finally:
                conn.close()
        except sqlite3.Error:
            message += " Registro de estado pendiente; revisar sin repetir la sanción."
    if action != "condemn":
        try:
            await log_embed(
                guild, "Límite de advertencias",
                f"Miembro: {member.mention}\nAdvertencias: {current}/{maximum}\n"
                f"Expediente: {moderation_case_code(case_number, guild.id)}\n{message}",
                discord.Color.orange(),
            )
        except Exception:
            pass
    return message



class ModerationWarningLimitReached(ValueError):
    """El usuario ya alcanzó el límite de advertencias vigentes."""


def moderation_warning_limit(guild_id: int) -> int:
    value = guild_setting_int(guild_id, "moderation_warn_limit", MODERATION_WARN_MAX_DEFAULT)
    return max(1, min(MODERATION_WARN_MAX_ALLOWED, value))


def moderation_warning_counts(guild_id: int, user_id: int) -> tuple[int, int]:
    """Cuenta vigentes y todas las WARN, conservando el historial cerrado."""
    conn = db_connect()
    try:
        row = conn.execute(
            "SELECT COUNT(*), COALESCE(SUM(CASE WHEN open = 1 AND "
            "(expires_at IS NULL OR expires_at > ?) THEN 1 ELSE 0 END), 0) "
            "FROM moderation_cases WHERE guild_id = ? AND user_id = ? AND type = 'WARN'",
            (datetime.now(timezone.utc).isoformat(), guild_id, user_id),
        ).fetchone()
        return int(row[1]), int(row[0])
    finally:
        conn.close()


def moderation_warning_create(
    guild_id: int, user_id: int, reason: str, *,
    duration_minutes: int | None = None, author_id: int | None = None,
    proof: str | None = None, verified_proof: str | None = None,
) -> tuple[int, int, int]:
    """Inserta WARN respetando límite bajo BEGIN IMMEDIATE, sin borrar historial."""
    history = moderation_case_message_history(guild_id, user_id)
    limit = moderation_warning_limit(guild_id)
    conn = db_connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        current = int(conn.execute(
            "SELECT COUNT(*) FROM moderation_cases WHERE guild_id=? AND user_id=? "
            "AND type='WARN' AND open=1 AND (expires_at IS NULL OR expires_at > ?)",
            (guild_id, user_id, datetime.now(timezone.utc).isoformat()),
        ).fetchone()[0])
        if current >= limit:
            raise ModerationWarningLimitReached(f"Máximo de advertencias alcanzado: {current}/{limit}.")
        number = int(conn.execute(
            "SELECT COALESCE(MAX(case_number), 0)+1 FROM moderation_cases WHERE guild_id=?",
            (guild_id,),
        ).fetchone()[0])
        now = datetime.now(timezone.utc)
        expires = now + timedelta(minutes=duration_minutes) if duration_minutes else None
        conn.execute(
            "INSERT INTO moderation_cases "
            "(guild_id,case_number,type,user_id,reason,duration_minutes,created_at,"
            "expires_at,author_id,proof,verified_proof,moderator_notes,message_history,open) "
            "VALUES (?,?,'WARN',?,?,?,?,?,?,?,?,?,?,1)",
            (guild_id, number, user_id, reason[:1000], duration_minutes,
             now.isoformat(), expires.isoformat() if expires else None,
             author_id, (proof or "")[:2000], (verified_proof or "")[:2000],
             "Advertencia administrativa.", history),
        )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    moderation_case_code(number, guild_id)
    return number, current + 1, limit


def moderation_case_create(guild_id: int, case_type: str, user_id: int, reason: str, *, duration_minutes: int | None = None, author_id: int | None = None, proof: str | None = None, verified_proof: str | None = None, moderator_notes: str | None = None) -> int:
    case_type = case_type.upper()
    if case_type not in MODERATION_CASE_TYPES:
        raise ValueError("Tipo de caso inválido.")
    case_number = moderation_case_next_number(guild_id)
    now = datetime.now(timezone.utc)
    expires_at = now + timedelta(minutes=duration_minutes) if duration_minutes else None
    conn = db_connect()
    conn.execute(
        "INSERT INTO moderation_cases "
        "(guild_id, case_number, type, user_id, reason, duration_minutes, created_at, expires_at, author_id, proof, verified_proof, moderator_notes, message_history, open) "
        "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1)",
        (guild_id, case_number, case_type, user_id, reason[:1000], duration_minutes, now.isoformat(),
         expires_at.isoformat() if expires_at else None, author_id, (proof or "")[:2000],
         (verified_proof or "")[:2000], (moderator_notes or "")[:2000],
         moderation_case_message_history(guild_id, user_id)),
    )
    conn.close()
    moderation_case_code(case_number, guild_id)
    return case_number


def moderation_case_update(guild_id: int, case_number: int, *, reason: str | None = None, duration_minutes: int | None | object = ..., proof: str | None = None, verified_proof: str | None = None, notes: str | None = None) -> bool:
    row = moderation_case_get(guild_id, case_number)
    if row is None:
        return False
    updates: list[str] = []
    params: list[object] = []
    if reason is not None:
        updates.append("reason = ?")
        params.append(reason[:1000])
    if duration_minutes is not ...:
        updates.extend(["duration_minutes = ?", "expires_at = ?"])
        params.append(duration_minutes)
        params.append((datetime.fromisoformat(row["created_at"]) + timedelta(minutes=int(duration_minutes))).isoformat() if duration_minutes else None)
    if proof is not None:
        updates.append("proof = ?")
        params.append(proof[:2000])
    if verified_proof is not None:
        updates.append("verified_proof = ?")
        params.append(verified_proof[:2000])
    if notes is not None:
        updates.append("moderator_notes = ?")
        params.append(notes[:2000])
    if not updates:
        return True
    params.extend([guild_id, case_number])
    conn = db_connect()
    conn.execute("UPDATE moderation_cases SET " + ", ".join(updates) + " WHERE guild_id = ? AND case_number = ?", params)
    conn.close()
    return True


def moderation_case_close(guild_id: int, case_number: int, *, closed_by: int | None, resolution: str = "closed") -> bool:
    conn = db_connect()
    cur = conn.execute(
        "UPDATE moderation_cases SET open = 0, closed_at = ?, closed_by = ?, resolution = ? "
        "WHERE guild_id = ? AND case_number = ? AND open = 1",
        (datetime.now(timezone.utc).isoformat(), closed_by, resolution[:500], guild_id, case_number),
    )
    conn.close()
    return cur.rowcount > 0


def moderation_case_delete(guild_id: int, case_number: int) -> bool:
    conn = db_connect()
    cur = conn.execute("DELETE FROM moderation_cases WHERE guild_id = ? AND case_number = ?", (guild_id, case_number))
    conn.close()
    return cur.rowcount > 0


async def moderation_verified_proof(guild: discord.Guild, proof: str | None) -> str | None:
    if not proof:
        return None
    match = re.search(r"discord(?:app)?\.com/channels/(\d+)/(\d+)/(\d+)", proof)
    if not match or int(match.group(1)) != guild.id:
        return None
    channel = guild.get_channel_or_thread(int(match.group(2)))
    if channel is None or not hasattr(channel, "fetch_message"):
        return None
    try:
        message = await channel.fetch_message(int(match.group(3)))
    except discord.HTTPException:
        return None
    text = message.content or "(sin texto)"
    if message.attachments:
        text += "\n" + "\n".join(attachment.url for attachment in message.attachments[:5])
    return text[:2000]


def moderation_case_embed(guild: discord.Guild, row: sqlite3.Row) -> discord.Embed:
    embed = discord.Embed(
        title=f"Expediente {moderation_case_code(row['case_number'], int(row['guild_id']))} · {row['type']}",
        color=discord.Color.orange() if row["open"] else discord.Color.dark_grey(),
        timestamp=datetime.fromisoformat(row["created_at"]),
    )
    embed.add_field(name="Estado", value="Abierto" if row["open"] else "Cerrado", inline=True)
    if row["type"] == "WARN":
        active, _ = moderation_warning_counts(guild.id, int(row["user_id"]))
        embed.add_field(
            name="Advertencias vigentes",
            value=f"{active}/{moderation_warning_limit(guild.id)}",
            inline=True,
        )
    embed.add_field(name="Usuario", value=f"<@{row['user_id']}>\nID: {row['user_id']}", inline=True)
    embed.add_field(name="Autor", value=f"<@{row['author_id']}>" if row["author_id"] else "El Heraldo", inline=True)
    embed.add_field(name="Motivo", value=str(row["reason"])[:1024], inline=False)
    duration_text = format_duration(int(row["duration_minutes"])) if row["duration_minutes"] else "Indefinida / no aplica"
    embed.add_field(name="Duración", value=duration_text, inline=True)
    if row["expires_at"]:
        embed.add_field(name="Caduca", value=discord.utils.format_dt(datetime.fromisoformat(row["expires_at"]), "R"), inline=True)
    if row["proof"]:
        embed.add_field(name="Prueba", value=str(row["proof"])[:1024], inline=False)
    if row["verified_proof"]:
        embed.add_field(name="Prueba verificada", value=str(row["verified_proof"])[:1024], inline=False)
    if row["moderator_notes"]:
        embed.add_field(name="Notas del moderador", value=str(row["moderator_notes"])[:1024], inline=False)
    if not row["open"] and row["resolution"]:
        embed.add_field(name="Resolución", value=str(row["resolution"])[:1024], inline=False)
    embed.set_footer(text=f"{guild.name} · El Heraldo")
    return embed


def moderation_cases_summary(guild: discord.Guild) -> str:
    rows = moderation_case_list(guild.id, limit=8)
    if not rows:
        return "**El Heraldo · Moderation · Cases**\n\nTodavía no hay casos registrados."
    lines = []
    for row in rows:
        state = "abierto" if row["open"] else "cerrado"
        lines.append(f"**{moderation_case_code(row['case_number'], int(row['guild_id']))}** · {row['type']} · <@{row['user_id']}> · {state}\n{str(row['reason'])[:120]}")
    return "**El Heraldo · Moderation · Cases**\n\n" + "\n\n".join(lines)



# Modo exclusivamente experimental de Railway. No sustituye las pruebas de Discord.
HERALDO_TEST_PROJECT = "747a1ee0-cdab-4ad5-8e45-a6ddfccc9b61"
HERALDO_TEST_REASON = "Prueba funcional autorizada de El Heraldo Test."


def heraldo_is_test() -> bool:
    return os.getenv("RAILWAY_PROJECT_ID") == HERALDO_TEST_PROJECT


def moderation_default_ban_minutes(guild_id: int) -> int | None:
    """BAN por defecto: 5 minutos en Test, permanente en otros entornos."""
    raw = guild_config_get(guild_id, "moderation_default_ban_minutes")
    if raw is None:
        return 5 if heraldo_is_test() else None
    try:
        value = int(raw)
    except (ValueError, TypeError):
        return 5 if heraldo_is_test() else None
    return value if 1 <= value <= 365 * 24 * 60 else None


def moderation_effective_ban_minutes(guild_id: int, minutes: int | None) -> int | None:
    """Una duración de cero expresamente solicitada significa permanente."""
    if minutes is not None:
        return minutes if minutes > 0 else None
    return moderation_default_ban_minutes(guild_id)


async def prepare_removal_dm(member: discord.Member) -> discord.DMChannel | None:
    """Abre el canal privado sin enviar contenido antes de una sanción."""
    try:
        return await member.create_dm()
    except (AttributeError, discord.HTTPException):
        return None


async def send_test_removal_notice(member: discord.Member, action: str,
                                   minutes: int | None = None, *,
                                   dm_channel: discord.DMChannel | None = None,
                                   allow_reentry_invite: bool = False) -> bool:
    """Aviso experimental solo tras sanción confirmada, sin link en ban/manual."""
    if not heraldo_is_test():
        return False
    guild = member.guild
    invite_url = None
    if allow_reentry_invite and action == "KICK":
        preferred = guild.get_channel(get_recovery_channel_id(guild.id))
        channels = ([preferred] if isinstance(preferred, discord.TextChannel) else []) + list(guild.text_channels)
        seen = set()
        for channel in channels:
            if channel.id in seen:
                continue
            seen.add(channel.id)
            if guild.me is None:
                break
            permissions = channel.permissions_for(guild.me)
            public = channel.permissions_for(guild.default_role)
            if not (permissions.view_channel and permissions.create_instant_invite and public.view_channel):
                continue
            try:
                invite = await channel.create_invite(
                    max_uses=1, max_age=0, unique=True,
                    reason="Recuperación por prueba de personalidad de El Heraldo",
                )
                invite_url = invite.url
                break
            except discord.HTTPException:
                continue
    if action == "BAN" and minutes:
        availability = f"Baneo experimental confirmado. Duración prevista: {format_duration(minutes)}."
    elif action == "BAN":
        availability = "Baneo experimental confirmado. Debe levantarse antes de reingresar."
    elif allow_reentry_invite:
        availability = "Expulsión experimental de personalidad confirmada."
    else:
        availability = "Expulsión experimental confirmada. Consulta al equipo para solicitar el regreso."
    invite_text = f"Invitación de un solo uso: {invite_url}\\n" if invite_url else ""
    message = (
        "Estamos realizando pruebas de moderación en El Heraldo Test. "
        "La medida forma parte de nuestras comprobaciones. Te pedimos disculpas por las molestias.\\n\\n"
        f"{availability}\\n{invite_text}\\n"
        "Si tienes alguna dificultad, comunícate con los administradores del servidor."
    )
    try:
        target = dm_channel if dm_channel is not None else member
        await target.send(message, allowed_mentions=discord.AllowedMentions.none())
        return True
    except discord.HTTPException:
        return False

async def heraldo_kick(member: discord.Member, *, reason: str,
                       send_notice: bool = True) -> None:
    test_notice = send_notice and heraldo_is_test()
    dm_channel = await prepare_removal_dm(member) if test_notice else None
    # Si Discord rechaza la expulsión, no generar invitaciones ni avisos.
    await getattr(member, "kick")(reason=reason)
    if test_notice:
        await send_test_removal_notice(member, "KICK", dm_channel=dm_channel)


async def heraldo_ban(member: discord.Member, *, reason: str,
                      delete_message_seconds: int = 0,
                      duration_minutes: int | None = None,
                      record_case: bool = True) -> int | None:
    effective = moderation_effective_ban_minutes(member.guild.id, duration_minutes)
    test_notice = heraldo_is_test()
    dm_channel = await prepare_removal_dm(member) if test_notice else None
    await getattr(member, "ban")(reason=reason, delete_message_seconds=0)
    # Otras rutas crean su propio caso. No duplicar expedientes.
    if record_case and effective is not None:
        try:
            moderation_case_create(member.guild.id, "BAN", member.id, reason,
                                   duration_minutes=effective, author_id=None)
        except Exception:
            # Discord confirmó la medida: jamás reintentar el baneo por un error en SQLite.
            traceback.print_exc()
    if test_notice:
        await send_test_removal_notice(member, "BAN", effective, dm_channel=dm_channel)
    return effective


def test_dm_notice_embed(embed: discord.Embed) -> discord.Embed:
    """Añade un aviso únicamente en mensajes privados del proyecto Railway Test."""
    if os.getenv("RAILWAY_PROJECT_ID") != "747a1ee0-cdab-4ad5-8e45-a6ddfccc9b61":
        return embed
    result = embed.copy()
    result.add_field(
        name="Aviso sobre el entorno de pruebas",
        value=(
            "Estamos realizando pruebas para mejorar la seguridad y el funcionamiento del servidor. "
            "Es posible que reciba notificaciones de prueba. Le pedimos disculpas por las molestias. "
            "Si este mensaje contiene una medida de moderación, consulte con el equipo del servidor "
            "para confirmar su situación."
        ),
        inline=False,
    )
    return result


async def moderation_send_case_dm(guild: discord.Guild, user_id: int, case_number: int) -> bool:
    row = moderation_case_get(guild.id, case_number)
    member = guild.get_member(user_id)
    if row is None or member is None:
        return False
    try:
        await member.send(embed=test_dm_notice_embed(moderation_case_embed(guild, row)))
        return True
    except discord.HTTPException:
        return False


async def moderation_apply_case_punishment(interaction: discord.Interaction, member: discord.Member, case_type: str, reason: str, duration_minutes: int | None = None, proof: str | None = None) -> tuple[bool, str, int | None]:
    guild = interaction.guild
    case_type = case_type.upper()
    if member.bot:
        return False, "Los bots no se castigan desde Moderation.", None
    if member.id == guild.owner_id:
        return False, "No se puede castigar al dueño del servidor.", None
    if interaction.user.id != guild.owner_id and member.top_role >= interaction.user.top_role:
        return False, "La jerarquía del servidor impide aplicar esta acción.", None
    if member.top_role >= guild.me.top_role:
        return False, "El rol del miembro está al mismo nivel o por encima de El Heraldo.", None
    explicit_permanent = case_type == "BAN" and duration_minutes == 0
    if case_type == "BAN":
        duration_minutes = moderation_effective_ban_minutes(guild.id, duration_minutes)
    verified = await moderation_verified_proof(guild, proof)
    try:
        if case_type == "MUTE":
            minutes = duration_minutes or 30
            await member.timeout(datetime.now(timezone.utc) + timedelta(minutes=min(minutes, 28 * 24 * 60)), reason=reason)
        elif case_type == "KICK":
            await heraldo_kick(member, reason=reason)
        elif case_type == "BAN":
            await heraldo_ban(member, reason=reason, delete_message_seconds=0,
                              duration_minutes=0 if explicit_permanent else duration_minutes,
                              record_case=False)
        elif case_type != "WARN":
            return False, "Tipo de castigo no compatible.", None
    except discord.HTTPException as exc:
        return False, f"Discord rechazó la acción: {exc}", None
    if case_type == "WARN":
        try:
            case_number, active, warn_limit = moderation_warning_create(
                guild.id, member.id, reason, duration_minutes=duration_minutes,
                author_id=interaction.user.id, proof=proof, verified_proof=verified,
            )
        except ModerationWarningLimitReached as exc:
            return False, str(exc) + " Revise las advertencias vigentes.", None
    else:
        case_number = moderation_case_create(
            guild.id, case_type, member.id, reason, duration_minutes=duration_minutes,
            author_id=interaction.user.id, proof=proof, verified_proof=verified,
        )
    # La advertencia se envía ANTES de cualquier expulsión o baneo por acumulación.
    dm_ok = await moderation_send_case_dm(guild, member.id, case_number)
    escalation_note = ""
    if case_type == "WARN" and active == warn_limit:
        escalation_note = await moderation_warning_escalation(
            guild, member, case_number, active, warn_limit,
        )
    await log_embed(
        guild, f"Moderation · {case_type}",
        f"Expediente {moderation_case_code(case_number, guild.id)} · {member.mention} ({member.id})\nMotivo: {reason}\nModerador: {interaction.user.mention}\nDM: {'enviado' if dm_ok else 'no disponible'}"
        + (f"\nAdvertencias vigentes: {active}/{warn_limit}"
           + (f"\n{escalation_note}" if active == warn_limit else "")
           if case_type == "WARN" else ""),
        discord.Color.orange(),
    )
    if case_type == "WARN" and log_member_event_enabled(guild.id, "member_warn"):
        await log_embed(
            guild, "Miembro advertido",
            f"Usuario: {member.mention}\nMotivo: {discord.utils.escape_markdown(reason[:500])}\n"
            f"Responsable: {interaction.user.mention}\n"
            f"Expediente: {moderation_case_code(case_number, guild.id)}",
            discord.Color.orange(), member=member,
        )
    status = ""
    if case_type == "WARN":
        status = f" · Advertencias: {active}/{warn_limit}"
        if active >= warn_limit:
            status += " · " + (escalation_note or "Máximo alcanzado: requiere revisión administrativa")
    return True, f"Expediente {moderation_case_code(case_number, guild.id)} creado{status}.", case_number


async def moderation_close_case_effect(guild: discord.Guild, row: sqlite3.Row, actor: discord.Member) -> str:
    case_type = str(row["type"])
    user_id = int(row["user_id"])
    if case_type == "MUTE":
        member = guild.get_member(user_id)
        if member is not None:
            try:
                await member.timeout(None, reason=f"Cierre del expediente {moderation_case_code(row['case_number'], int(row['guild_id']))}")
                return "Timeout retirado."
            except discord.HTTPException:
                return "Caso cerrado; no pude retirar el timeout."
    if case_type == "BAN":
        try:
            await guild.unban(discord.Object(id=user_id), reason=f"Cierre del expediente {moderation_case_code(row['case_number'], int(row['guild_id']))}")
            return "Ban retirado."
        except (discord.NotFound, discord.HTTPException):
            return "Caso cerrado; el usuario no estaba baneado o no pude retirarlo."
    if case_type == "CONDEMN":
        member = guild.get_member(user_id)
        if member is not None and condemnation_get(guild.id, user_id) is not None:
            ok, note = await release_condemned_member(member, released_by=actor, automatic=False)
            return note if ok else f"No pude levantar la condena: {note}"
    return "Caso cerrado."

MODERATION_REPORT_MAX_REACTIONS = 10
MODERATION_REPORT_ACTIONS = {"report", "warn", "timeout", "kick", "ban", "condemn"}
MODERATION_REPORT_REACTION_DEFAULTS = (
    {"emoji": "❗", "label": "Incumplimiento de reglas", "action": "warn", "duration_minutes": None, "threshold": 1, "purge_minutes": None},
    {"emoji": "📢", "label": "Spam", "action": "timeout", "duration_minutes": 30, "threshold": 2, "purge_minutes": 30},
    {"emoji": "🚩", "label": "Contenido inapropiado / no permitido", "action": "condemn", "duration_minutes": 1440, "threshold": 3, "purge_minutes": 30},
    {"emoji": "🤓", "label": "Sospechoso (posible cuenta falsa o estafa)", "action": "condemn", "duration_minutes": None, "threshold": 2, "purge_minutes": 30},
    {"emoji": "🔞", "label": "Posible menor de edad", "action": "ban", "duration_minutes": None, "threshold": 2, "purge_minutes": 30},
)
_moderation_report_dedupe: dict[tuple[int, int, int, str], float] = {}
_moderation_report_pending: set[tuple[int, int, str]] = set()
_reaction_condemn_pending: set[tuple[int, int]] = set()


def _moderation_emoji_key(value: str) -> str:
    return str(value).replace("\ufe0f", "").strip()


def _moderation_report_default_reactions() -> list[dict[str, object]]:
    return [dict(item) for item in MODERATION_REPORT_REACTION_DEFAULTS]


def _normalize_moderation_report_rule(item: dict) -> dict[str, object] | None:
    emoji = str(item.get("emoji", "")).strip()
    label = str(item.get("label", "")).strip()
    if not emoji or not label:
        return None
    action = str(item.get("action", "report")).strip().lower()
    if action not in MODERATION_REPORT_ACTIONS:
        action = "report"
    try:
        threshold = max(1, min(25, int(item.get("threshold", 1))))
    except (TypeError, ValueError):
        threshold = 1
    duration = item.get("duration_minutes")
    try:
        duration_minutes = int(duration) if duration not in (None, "", 0, "0") else None
    except (TypeError, ValueError):
        duration_minutes = None
    if duration_minutes is not None:
        duration_minutes = max(1, min(28 * 24 * 60, duration_minutes))
    purge_raw = item.get("purge_minutes")
    if purge_raw in (None, "", 0, "0") and item.get("delete_message"):
        # Compatibilidad con la versión anterior: "borrar mensaje" pasa a una purga reciente.
        purge_raw = 30
    try:
        purge_minutes = int(purge_raw) if purge_raw not in (None, "", 0, "0") else None
    except (TypeError, ValueError):
        purge_minutes = None
    if purge_minutes is not None:
        purge_minutes = max(1, min(PURGE_MAX_MINUTES, purge_minutes))
    if action in {"report", "warn"}:
        purge_minutes = None  # Los avisos informativos y advertencias nunca eliminan mensajes.
    if action == "warn":
        threshold = 1  # El aviso lo aplica únicamente un moderador autorizado.
        duration_minutes = None
    return {
        "emoji": emoji[:100],
        "label": label[:100],
        "action": action,
        "duration_minutes": duration_minutes,
        "threshold": threshold,
        "purge_minutes": purge_minutes,
    }


def moderation_report_reactions(guild_id: int) -> list[dict[str, object]]:
    raw = guild_config_get(guild_id, "moderation_report_reactions")
    if raw is None:
        return _moderation_report_default_reactions()
    try:
        data = json.loads(raw)
    except (TypeError, json.JSONDecodeError):
        return _moderation_report_default_reactions()
    result: list[dict[str, object]] = []
    seen: set[str] = set()
    for item in data if isinstance(data, list) else []:
        if not isinstance(item, dict):
            continue
        normalized = _normalize_moderation_report_rule(item)
        if normalized is None:
            continue
        key = _moderation_emoji_key(str(normalized["emoji"]))
        if key in seen:
            continue
        seen.add(key)
        result.append(normalized)
        if len(result) >= MODERATION_REPORT_MAX_REACTIONS:
            break
    # Compatibilidad de los cuatro valores predeterminados anteriores:
    # añadir el aviso nuevo solo si la lista antigua es exactamente el
    # conjunto original sin personalizaciones. No escribir la base al leer.
    old_defaults = [
        _normalize_moderation_report_rule(dict(item))
        for item in MODERATION_REPORT_REACTION_DEFAULTS
        if _moderation_emoji_key(str(item["emoji"])) != _moderation_emoji_key("❗")
    ]
    if result == old_defaults and len(result) < MODERATION_REPORT_MAX_REACTIONS:
        warn_default = _normalize_moderation_report_rule(
            dict(next(item for item in MODERATION_REPORT_REACTION_DEFAULTS
                      if _moderation_emoji_key(str(item["emoji"])) == _moderation_emoji_key("❗")))
        )
        if warn_default is not None:
            result.insert(0, warn_default)
    return result


def set_moderation_report_reactions(guild_id: int, reactions: list[dict]) -> None:
    clean: list[dict[str, object]] = []
    seen: set[str] = set()
    for item in reactions:
        normalized = _normalize_moderation_report_rule(item)
        if normalized is None:
            continue
        key = _moderation_emoji_key(str(normalized["emoji"]))
        if key in seen:
            continue
        seen.add(key)
        clean.append(normalized)
        if len(clean) >= MODERATION_REPORT_MAX_REACTIONS:
            break
    guild_config_set(guild_id, "moderation_report_reactions", json.dumps(clean, ensure_ascii=False))


def moderation_report_rule_for_emoji(guild_id: int, emoji: str) -> dict[str, object] | None:
    key = _moderation_emoji_key(emoji)
    for item in moderation_report_reactions(guild_id):
        if _moderation_emoji_key(str(item["emoji"])) == key:
            return item
    return None


def moderation_report_type_for_emoji(guild_id: int, emoji: str) -> str | None:
    rule = moderation_report_rule_for_emoji(guild_id, emoji)
    return str(rule["label"]) if rule else None


def moderation_report_record(
    guild_id: int, message_id: int, target_id: int, emoji_key: str, reporter_id: int
) -> tuple[int, bool]:
    conn = db_connect()
    now = datetime.now(timezone.utc).isoformat()
    conn.execute(
        "INSERT OR IGNORE INTO moderation_reaction_reports "
        "(guild_id, message_id, target_id, emoji_key, reporter_id, created_at, action_executed) "
        "VALUES (?, ?, ?, ?, ?, ?, 0)",
        (guild_id, message_id, target_id, emoji_key, reporter_id, now),
    )
    row = conn.execute(
        "SELECT COUNT(*), MAX(action_executed) FROM moderation_reaction_reports "
        "WHERE guild_id = ? AND message_id = ? AND target_id = ? AND emoji_key = ?",
        (guild_id, message_id, target_id, emoji_key),
    ).fetchone()
    conn.close()
    return int(row[0]), bool(row[1])


def moderation_report_mark_executed(guild_id: int, message_id: int, target_id: int, emoji_key: str) -> None:
    conn = db_connect()
    conn.execute(
        "UPDATE moderation_reaction_reports SET action_executed = 1 "
        "WHERE guild_id = ? AND message_id = ? AND target_id = ? AND emoji_key = ?",
        (guild_id, message_id, target_id, emoji_key),
    )
    conn.close()


def moderation_report_case_record(
    guild_id: int, message_id: int, target_id: int, emoji_key: str,
    case_type: str, reason: str, *, duration_minutes: int | None,
    proof: str, author_id: int | None = None, return_created: bool = False,
) -> int | tuple[int, bool]:
    """Vincula una sanción ejecutada con un caso, sin duplicarlo por reintentos.

    El guardado se hace atómicamente con la referencia a la reacción.
    No se llama antes de que Discord confirme una sanción.
    """
    conn = db_connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            "SELECT case_number FROM moderation_report_cases "
            "WHERE guild_id=? AND message_id=? AND target_id=? AND emoji_key=?",
            (guild_id, message_id, target_id, emoji_key),
        ).fetchone()
        if existing is not None:
            conn.commit()
            return (int(existing[0]), False) if return_created else int(existing[0])
        if case_type == "WARN":
            limit = moderation_warning_limit(guild_id)
            count = int(conn.execute(
                "SELECT COUNT(*) FROM moderation_cases WHERE guild_id=? AND user_id=? "
                "AND type='WARN' AND open=1 AND (expires_at IS NULL OR expires_at > ?)",
                (guild_id, target_id, datetime.now(timezone.utc).isoformat()),
            ).fetchone()[0])
            if count >= limit:
                raise ModerationWarningLimitReached(
                    f"Máximo de advertencias alcanzado: {count}/{limit}."
                )
        next_number = int(conn.execute(
            "SELECT COALESCE(MAX(case_number), 0) + 1 FROM moderation_cases WHERE guild_id=?",            (guild_id,),
        ).fetchone()[0])
        now = datetime.now(timezone.utc)
        expires = now + timedelta(minutes=duration_minutes) if duration_minutes else None
        # Los enlaces son referencias, no sustituyen a las pruebas archivadas.
        conn.execute(
            "INSERT INTO moderation_cases "
            "(guild_id, case_number, type, user_id, reason, duration_minutes, "
            "created_at, expires_at, author_id, proof, verified_proof, "
            "moderator_notes, message_history, open) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, 1)",
            (guild_id, next_number, case_type, target_id, reason[:1000],
             duration_minutes, now.isoformat(), expires.isoformat() if expires else None,
             author_id, proof[:2000], "Sanción o advertencia por reacción de moderación.",
             moderation_case_message_history(guild_id, target_id)),
        )
        conn.execute(
            "INSERT INTO moderation_report_cases "
            "(guild_id, message_id, target_id, emoji_key, case_number) "
            "VALUES (?, ?, ?, ?, ?)",
            (guild_id, message_id, target_id, emoji_key, next_number),
        )
        conn.commit()
        return (next_number, True) if return_created else next_number
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def moderation_action_label(action: str) -> str:
    return {
        "report": "Solo reportar",
        "warn": "Advertir",
        "timeout": "Timeout / mute",
        "kick": "Expulsar",
        "ban": "Banear",
        "condemn": "Condenar",
    }.get(action, action)


async def execute_moderation_report_action(
    guild: discord.Guild,
    target: discord.Member,
    message: discord.Message,
    rule: dict[str, object],
    reporter_count: int,
    actor: discord.Member | None = None,
) -> tuple[bool, str]:
    action = str(rule.get("action", "report"))
    purge_minutes = rule.get("purge_minutes")
    purge_minutes = int(purge_minutes) if purge_minutes else None
    duration_minutes = rule.get("duration_minutes")
    duration_minutes = int(duration_minutes) if duration_minutes else None
    reason = f"Reporte automático: {rule.get('label', 'reporte')} · {reporter_count} reporte(s) distintos"

    protection = condemnation_protection_reason(target)
    if action != "report" and protection:
        return False, f"Acción bloqueada: {protection}."

    notes: list[str] = []
    if action != "report" and not moderation_report_punishment_enabled(guild.id, action):
        return False, "Acción desactivada en Moderation → Reportes; no se aplicó una sanción."
    if action == "report":
        return True, "Reporte registrado"
    if action == "warn":
        if actor is None or not moderation_can_warn(actor):
            return False, "La advertencia por reacción requiere permiso para moderar miembros."
        if target.id == guild.owner_id or (
            actor.id != guild.owner_id and target.top_role >= actor.top_role
        ):
            return False, "La jerarquía impide advertir a este miembro."
        try:
            case_number, created = moderation_report_case_record(
                guild.id, message.id, target.id,
                _moderation_emoji_key(str(rule["emoji"])), "WARN",
                "Incumplimiento de reglas", duration_minutes=None,
                proof=message.jump_url, author_id=actor.id, return_created=True,
            )
        except ModerationWarningLimitReached as exc:
            return False, str(exc) + " Solicite una revisión administrativa."
        except Exception:
            return False, "No fue posible registrar la advertencia. No se efectuaron cambios."
        active, _ = moderation_warning_counts(guild.id, target.id)
        limit = moderation_warning_limit(guild.id)
        status = f"{active}/{limit}"
        reached = "; máximo alcanzado, revisión administrativa necesaria" if active >= limit else ""
        code = moderation_case_code(case_number, guild.id)
        if created:
            try:
                sent = await moderation_send_case_dm(guild, target.id, case_number)
            except Exception:
                sent = False
            if active == limit:
                reached = "; " + await moderation_warning_escalation(
                    guild, target, case_number, active, limit,
                )
            return True, f"Advertencia {status} en expediente {code}; DM: {'enviado' if sent else 'no disponible'}{reached}"
        return True, f"Advertencia existente en expediente {code}; vigentes: {status}{reached}"

    me = guild.me
    if me is None:
        return False, "No se pudieron verificar los permisos de El Heraldo."
    required = {"timeout": "moderate_members", "kick": "kick_members",
                "ban": "ban_members", "condemn": "manage_roles"}.get(action)
    if required is None:
        return False, "Acción de reporte no admitida."
    if not getattr(me.guild_permissions, required, False):
        return False, "El Heraldo no tiene el permiso necesario para la acción configurada."
    if target.top_role >= me.top_role:
        return False, "El Heraldo no puede actuar sobre un miembro con un rol igual o superior."
    if action == "timeout" and not duration_minutes:
        return False, "La regla de aislamiento no tiene una duración válida."
    if action == "ban":
        duration_minutes = moderation_effective_ban_minutes(guild.id, duration_minutes)

    # No eliminar mensajes antes de comprobar la acción ni antes de archivar
    # la evidencia necesaria para una condena.
    try:
        if action == "timeout":
            until = datetime.now(timezone.utc) + timedelta(minutes=duration_minutes)
            await target.timeout(until, reason=reason)
            notes.append(f"timeout {format_duration(duration_minutes)}")
        elif action == "kick":
            await heraldo_kick(target, reason=reason)
            notes.append("miembro expulsado")
        elif action == "ban":
            await heraldo_ban(target, reason=reason, delete_message_seconds=0,
                              duration_minutes=duration_minutes, record_case=False)
            notes.append("miembro baneado")
        elif action == "condemn":
            ok, note = await condemn_member(
                target,
                reason=reason,
                duration_minutes=duration_minutes,
                purge_spec=("time", purge_minutes) if purge_minutes else None,
                origin="reaction_report",
                applied_by=None,
                source_message_url=message.jump_url,
                source_channel_id=message.channel.id,
            )
            if not ok:
                return False, note
            notes.append("condena aplicada")
    except discord.HTTPException as exc:
        return False, f"Discord rechazó la acción: {type(exc).__name__}."

    # La sanción ya ocurrió: si falla registrar el expediente, JAMÁS reintentar
    # la sanción como consecuencia del error de SQLite.
    if action in {"timeout", "kick", "ban"}:
        case_type = {"timeout": "MUTE", "kick": "KICK", "ban": "BAN"}[action]
        try:
            case_number = moderation_report_case_record(
                guild.id, message.id, target.id, _moderation_emoji_key(str(rule["emoji"])),
                case_type, reason,
                duration_minutes=duration_minutes if action in {"timeout", "ban"} else None,
                proof=message.jump_url,
            )
            notes.append(f"expediente {moderation_case_code(case_number, guild.id)}")
        except Exception:
            # El log del reporte es la constancia alternativa.
            notes.append("advertencia: sanción aplicada pero expediente no registrado; revisión necesaria")

    if purge_minutes and action not in {"condemn", "report"}:
        after = datetime.now(timezone.utc) - timedelta(minutes=purge_minutes)
        try:
            result = await run_purge_job(
                guild,
                target,
                scope_text=f"mensajes de los últimos {format_duration(purge_minutes)}",
                requested_by=f"Moderation · {rule.get('label', 'reporte')}",
                after=after,
                title="Moderation · Purga automática completada",
                log_success=False,
            )
        except Exception:
            notes.append("purga fallida; revise el registro de advertencias")
        else:
            notes.append("purga ya en curso" if result is None else f"purga: {purge_result_text(result)}")
    if action == "condemn" and purge_minutes:
        notes.append("la purga depende del archivo seguro de la evidencia")

    return True, "; ".join(notes) if notes else moderation_action_label(action)


def moderation_report_channel_id(guild_id: int) -> int:
    return guild_setting_int(guild_id, "moderation_report_channel_id", 0)


def set_moderation_report_channel_id(guild_id: int, channel_id: int) -> None:
    guild_config_set(guild_id, "moderation_report_channel_id", str(channel_id))


def moderation_can_warn(member: discord.Member) -> bool:
    perms = member.guild_permissions
    return bool(perms.administrator or perms.moderate_members)


def moderation_can_condemn(actor: discord.Member, target: discord.Member) -> bool:
    """Mismos permisos que /condenar más jerarquía y protección del objetivo."""
    perms = actor.guild_permissions
    return bool(
        (perms.administrator or perms.kick_members)
        and (actor.id == actor.guild.owner_id or actor.top_role > target.top_role)
        and condemnation_protection_reason(target) is None
    )


def moderation_is_staff(member: discord.Member) -> bool:
    perms = member.guild_permissions
    return bool(
        perms.administrator
        or perms.moderate_members
        or perms.manage_messages
        or perms.kick_members
        or perms.ban_members
    )


def moderation_reports_summary(guild: discord.Guild, *, channel_id=None, mappings=None, condemn_emoji=None) -> str:
    channel_id = moderation_report_channel_id(guild.id) if channel_id is None else channel_id
    channel = guild.get_channel(channel_id) if channel_id else None
    mappings = moderation_report_reactions(guild.id) if mappings is None else mappings
    def rule_line(item: dict[str, object]) -> str:
        action = moderation_action_label(str(item.get("action", "report")))
        threshold = int(item.get("threshold", 1))
        duration = item.get("duration_minutes")
        duration_text = f" · {format_duration(int(duration))}" if duration else ""
        purge = item.get("purge_minutes") if item.get("action") != "report" else None
        purge_text = f" · purgar {format_duration(int(purge))}" if purge else ""
        return f"• {item['emoji']} → **{item['label']}** · {action}{duration_text} · {threshold} reporte(s){purge_text}"
    mapping_text = "\n".join(rule_line(item) for item in mappings) or "• Sin reacciones configuradas"
    return (
        f"**Registro de reportes:** {channel.mention if isinstance(channel, discord.TextChannel) else 'Canal general de logs'}\n"
        f"**Reacciones de reporte:**\n{mapping_text}\n"
        f"**Reacción para condenar:** {condemn_emoji or get_condemnation_emoji(guild.id)}\n\n"
        "Las reglas anteriores muestran la configuración efectiva o el borrador actual. "
        "Las advertencias requieren un moderador y no eliminan mensajes. "
        "La reacción de condena directa funciona por separado de las reglas de reportes."
    )


def get_condemnation_max_minutes(guild_id: int | None = None) -> int:
    if guild_id is not None:
        return guild_setting_int(guild_id, "condemnation_max_minutes", CONDEMNATION_MAX_MINUTES)
    return CONDEMNATION_MAX_MINUTES


def set_condemnation_channel_id(channel_id: int, guild_id: int | None = None) -> None:
    if guild_id is not None:
        guild_resource_set(guild_id, "channel", "condemned", channel_id)
        guild_config_set(guild_id, "condemned_channel_id", str(channel_id))
    else:
        db_meta_set("condemned_channel_id", str(channel_id))


def condemnation_duration_text(row: sqlite3.Row) -> str:
    if row["expires_at"] is None:
        return "Indefinida"
    expires = datetime.fromisoformat(row["expires_at"])
    return f"hasta {discord.utils.format_dt(expires, 'R')} ({discord.utils.format_dt(expires, 'f')})"


def condemnation_origin_label(origin: str) -> str:
    return {
        "honeypot": "Honeypot",
        "command": "⌨️ Comando",
        "reaction": "Reacción",
        "role": "Rol otorgado a mano",
        "raid": "Raid Protection",
    }.get(origin, origin)


def condemnation_parse_role_ids(value: str) -> list[int]:
    try:
        return [int(x) for x in json.loads(value)]
    except (TypeError, ValueError, json.JSONDecodeError):
        return []


def hp_log_trigger(member: discord.Member, channel_id: int, action: str,
                   success: bool, note: str) -> None:
    conn = db_connect()
    conn.execute(
        "INSERT INTO honeypot_triggers (guild_id, user_id, username, channel_id, content, action, success, note, "
        "account_created, joined_at, triggered_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
        (
            member.guild.id, member.id, str(member), channel_id, "", action, int(success), note,
            member.created_at.isoformat(),
            member.joined_at.isoformat() if member.joined_at else None,
            datetime.now(timezone.utc).isoformat(),
        ),
    )
    conn.commit()
    conn.close()
    hp_prune_history(member.guild.id)


def hp_retention_minutes(guild_id: int) -> int:
    value = hp_setting_get(guild_id, "honeypot_retention_minutes")
    return int(value) if value else HONEYPOT_RETENTION_DEFAULT_MINUTES


def _hp_history_legacy_allowed(guild_id: int) -> bool:
    return legacy_fallback_allowed(guild_id)


def hp_prune_history(guild_id: int) -> None:
    cutoff = datetime.now(timezone.utc) - timedelta(minutes=hp_retention_minutes(guild_id))
    conn = db_connect()
    if _hp_history_legacy_allowed(guild_id):
        conn.execute(
            "DELETE FROM honeypot_triggers WHERE (guild_id = ? OR guild_id = 0) AND triggered_at < ?",
            (guild_id, cutoff.isoformat()),
        )
    else:
        conn.execute(
            "DELETE FROM honeypot_triggers WHERE guild_id = ? AND triggered_at < ?",
            (guild_id, cutoff.isoformat()),
        )
    conn.commit()
    conn.close()


def hp_recent_triggers(guild_id: int, limit: int = 10) -> list[sqlite3.Row]:
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    if _hp_history_legacy_allowed(guild_id):
        rows = conn.execute(
            "SELECT * FROM honeypot_triggers WHERE guild_id = ? OR guild_id = 0 ORDER BY id DESC LIMIT ?",
            (guild_id, limit),
        ).fetchall()
    else:
        rows = conn.execute(
            "SELECT * FROM honeypot_triggers WHERE guild_id = ? ORDER BY id DESC LIMIT ?",
            (guild_id, limit),
        ).fetchall()
    conn.close()
    return rows


def hp_total_triggers(guild_id: int) -> int:
    conn = db_connect()
    if _hp_history_legacy_allowed(guild_id):
        total = conn.execute(
            "SELECT COUNT(*) FROM honeypot_triggers WHERE success = 1 AND (guild_id = ? OR guild_id = 0)",
            (guild_id,),
        ).fetchone()[0]
    else:
        total = conn.execute(
            "SELECT COUNT(*) FROM honeypot_triggers WHERE success = 1 AND guild_id = ?",
            (guild_id,),
        ).fetchone()[0]
    conn.close()
    return total


# --- Configuración (guardada en meta) ---------------------------------------

def honeypot_enabled(guild_id: int) -> bool:
    return hp_setting_get(guild_id, "honeypot_enabled") == "1"


def honeypot_paused(guild_id: int) -> bool:
    return hp_setting_get(guild_id, "honeypot_paused") == "1"


def hp_action(guild_id: int) -> str:
    value = hp_setting_get(guild_id, "honeypot_action")
    if value in HONEYPOT_DESTRUCTIVE_ACTION_STORAGE.values():
        return "kick" if value == "kick_enabled" else "ban"
    if value in {"log", "role", "timeout"}:
        return value
    # "kick" / "ban" legados siempre equivalen al rol, por seguridad.
    return "role"


def hp_action_storage(action: str) -> str:
    """Escritura explícita de sanciones nuevas, sin reinterpretar valores legados."""
    return HONEYPOT_DESTRUCTIVE_ACTION_STORAGE.get(action, action)


def hp_sanction_permission_problem(
    guild: discord.Guild, action: str, actor_permissions=None,
) -> str | None:
    """Permisos necesarios para habilitar una medida de expulsión o baneo."""
    if action not in {"kick", "ban"}:
        return None
    permission = "kick_members" if action == "kick" else "ban_members"
    label = "Expulsar miembros" if action == "kick" else "Banear miembros"
    if actor_permissions is not None and not (
        getattr(actor_permissions, permission, False)
        or getattr(actor_permissions, "administrator", False)
    ):
        return f"El administrador necesita el permiso {label}."
    bot_member = guild.me
    if bot_member is None:
        return "No se pudo verificar el miembro de El Heraldo en el servidor."
    bot_permissions = getattr(bot_member, "guild_permissions", None)
    if not bot_permissions or not (
        getattr(bot_permissions, permission, False)
        or getattr(bot_permissions, "administrator", False)
    ):
        return f"El Heraldo necesita el permiso {label}."
    return None


def hp_punish_role_id(guild_id: int) -> int:
    configured = get_guild_role_id(guild_id, "condenado")
    if configured:
        return configured
    v = hp_setting_get(guild_id, "honeypot_punish_role")
    return int(v) if v else 0


def hp_protected_channel_reason(channel: discord.abc.GuildChannel) -> str | None:
    """Canales del propio Heraldo que nunca deben ser una trampa."""
    if channel.id == get_log_channel_id(channel.guild.id):
        return "es el canal de logs del Heraldo"
    if channel.id == get_motw_channel_id(channel.guild.id):
        return "es el canal del Miembro de la Semana"
    if channel.id == get_recovery_channel_id(channel.guild.id):
        return "es el canal de recuperación"
    ref = guild_config_get(channel.guild.id, "verify_panel_ref")
    if ref is None and legacy_fallback_allowed(channel.guild.id):
        ref = db_meta_get("verify_panel_ref")
    if ref:
        try:
            if int(ref.split(":")[0]) == channel.id:
                return "es el canal del panel de verificación"
        except ValueError:
            pass
    return None


def hp_role_problem(role: discord.Role, guild: discord.Guild) -> str | None:
    """Motivo por el que el Heraldo no puede usar este rol como rol de castigo, o None."""
    if role.is_default():
        return "es @everyone"
    if role.managed:
        return "es un rol gestionado por una integración o un bot"
    if role >= guild.me.top_role:
        return "está al mismo nivel o por encima del rol más alto del Heraldo"
    return None


_DURATION_RE = re.compile(r"(\d+)\s*(d(?:[ií]as?)?|h(?:oras?)?|m(?:in(?:utos?)?)?)(?![a-záéíóú])", re.IGNORECASE)


def parse_duration(text: str, min_minutes: int, max_minutes: int) -> int:
    """Convierte '30m', '12h', '2d' o '1d 12h 30m' (también 'días/horas/minutos') en minutos.
    '0' significa sin duración (solo válido si min_minutes es 0). Lanza ValueError con
    un mensaje listo para mostrar al usuario."""
    raw = text.strip().lower()
    example = "Usa d (días), h (horas) y m (minutos), por ejemplo `30m`, `12h`, `2d` o `1d 12h 30m`."
    if raw == "0":
        if min_minutes > 0:
            raise ValueError(f"El mínimo es {format_duration(min_minutes)}. {example}")
        return 0
    matches = list(_DURATION_RE.finditer(raw))
    leftover = _DURATION_RE.sub("", raw).replace(",", "").replace(" y ", "").strip()
    if not matches or leftover:
        raise ValueError(f"No entendí `{text}`. {example}")
    total = 0
    for m in matches:
        unit = m.group(2)[0]
        total += int(m.group(1)) * {"d": 1440, "h": 60, "m": 1}[unit]
    if total < min_minutes or total > max_minutes:
        raise ValueError(
            f"`{text}` queda fuera del rango permitido "
            f"({format_duration(min_minutes)} – {format_duration(max_minutes)})."
        )
    return total


def format_duration(minutes: int) -> str:
    if minutes <= 0:
        return "0 min"
    d, rest = divmod(minutes, 1440)
    h, m = divmod(rest, 60)
    parts = [f"{d} d" if d else "", f"{h} h" if h else "", f"{m} min" if m else ""]
    return " ".join(p for p in parts if p)


def hp_purge_spec(guild_id: int) -> tuple[str, int]:
    """(tipo, valor): none | all | count (N mensajes) | time (minutos hacia atrás)."""
    v = hp_setting_get(guild_id, "honeypot_purge_spec")
    if v:
        kind, _, val = v.partition(":")
        return kind, int(val or 0)
    old = hp_setting_get(guild_id, "honeypot_purge_minutes")  # compatibilidad con versiones anteriores
    if old is not None:
        return ("time", int(old)) if int(old) > 0 else ("none", 0)
    old = hp_setting_get(guild_id, "honeypot_purge_hours")
    if old is not None:
        return ("time", int(old) * 60) if int(old) > 0 else ("none", 0)
    return HONEYPOT_PURGE_DEFAULT


def hp_kick_purge_minutes(guild_id: int) -> int:
    """Purga de expulsión: un día por defecto; no se permite menos de 24 horas."""
    raw = hp_setting_get(guild_id, "honeypot_kick_purge_minutes")
    try:
        value = int(raw) if raw is not None else 1440
    except (TypeError, ValueError):
        return 1440
    return value if 1440 <= value <= 30 * 1440 else 1440


def hp_ban_override_minutes(guild_id: int) -> int | None:
    """None = configuración general; 0 = baneo permanente explícito."""
    raw = hp_setting_get(guild_id, "honeypot_ban_minutes")
    if raw is None:
        return None
    try:
        minutes = int(raw)
    except (ValueError, TypeError):
        return None
    return minutes if 0 <= minutes <= 365 * 1440 else None


def hp_ban_duration_minutes(guild_id: int) -> int | None:
    raw = hp_setting_get(guild_id, "honeypot_ban_minutes")
    if raw is None:
        return moderation_default_ban_minutes(guild_id)
    minutes = hp_ban_override_minutes(guild_id)
    return minutes if minutes else None


def hp_timeout_minutes(guild_id: int) -> int:
    v = hp_setting_get(guild_id, "honeypot_timeout_minutes")
    if v is not None:
        return int(v)
    old = hp_setting_get(guild_id, "honeypot_timeout_hours")
    return int(old) * 60 if old is not None else HONEYPOT_TIMEOUT_MINUTES_DEFAULT


def hp_warning_enabled(guild_id: int) -> bool:
    return hp_setting_get(guild_id, "honeypot_warning_enabled") != "0"  # activado por defecto


def hp_warning_style(guild_id: int) -> str:
    value = hp_setting_get(guild_id, "honeypot_warning_style")
    return value if value in ("text", "custom") else "text"


def hp_warning_text(guild_id: int) -> str:
    return hp_setting_get(guild_id, "honeypot_warning_text") or HONEYPOT_WARNING_TEXT_DEFAULT


def hp_warning_custom(guild_id: int) -> dict[str, str]:
    return {
        "title": hp_setting_get(guild_id, "honeypot_warning_title") or "Advertencia: No escribas en este canal",
        "description": hp_setting_get(guild_id, "honeypot_warning_description") or HONEYPOT_WARNING_TEXT_DEFAULT,
        "color": hp_setting_get(guild_id, "honeypot_warning_color") or "F1C40F",
        "image": hp_setting_get(guild_id, "honeypot_warning_image") or "",
        "thumbnail": hp_setting_get(guild_id, "honeypot_warning_thumbnail") or "",
        "footer": hp_setting_get(guild_id, "honeypot_warning_footer") or "",
    }


def hp_ping_role_id(guild_id: int) -> int:
    v = hp_setting_get(guild_id, "honeypot_ping_role")
    return int(v) if v else 0


def hp_is_exempt(member: discord.Member) -> bool:
    """Dueño, administradores y quien tenga Gestionar servidor siempre están exentos."""
    if member.guild.owner_id == member.id:
        return True
    perms = member.guild_permissions
    if (perms.administrator or perms.manage_guild or perms.manage_messages
            or perms.kick_members or perms.ban_members or perms.moderate_members):
        return True  # el equipo de moderación nunca cae en la trampa
    if member.id in hp_exempt_ids(member.guild.id, "member"):
        return True
    exempt_roles = hp_exempt_ids(member.guild.id, "role")
    return any(r.id in exempt_roles for r in member.roles)


def hp_config_summary(guild: discord.Guild) -> str:
    """Resumen conciso también utilizado por /honeypot setup sin argumentos."""
    traps = hp_traps(guild.id)
    action = hp_action(guild.id)
    state = ("Desactivado" if not honeypot_enabled(guild.id) else
             "Pausado" if honeypot_paused(guild.id) else "Activado")
    lines = [
        f"**Estado:** {state}",
        f"**Canales trampa:** {len(traps)}",
        f"**Acción:** {HONEYPOT_ACTION_LABELS.get(action, action)}",
    ]
    if action == "role":
        role_id = hp_punish_role_id(guild.id)
        lines.append(f"**Rol de castigo:** {f'<@&{role_id}>' if role_id else 'No configurado'}")
        lines.append(f"**Purga:** {format_purge_spec(*hp_purge_spec(guild.id))}")
    elif action == "timeout":
        lines.append(f"**Aislamiento:** {format_duration(hp_timeout_minutes(guild.id))}")
        lines.append(f"**Purga:** {format_purge_spec(*hp_purge_spec(guild.id))}")
    elif action == "kick":
        lines.append(f"**Purga:** mensajes de los últimos {format_duration(hp_kick_purge_minutes(guild.id))} (sin archivo de evidencias).")
    elif action == "ban":
        minutes = hp_ban_duration_minutes(guild.id)
        lines.append(f"**Duración del baneo:** {format_duration(minutes) if minutes else 'Permanente'}")
        lines.append("**Purga adicional:** ninguna.")
    lines.append(f"**Aviso:** {'Activado' if hp_warning_enabled(guild.id) else 'Desactivado'}")
    lines.append(
        f"**Historial:** {hp_total_triggers(guild.id)} capturas · "
        f"retención {format_duration(hp_retention_minutes(guild.id))}"
    )
    return "\n".join(lines)


def hp_setup_embed(guild: discord.Guild, pending: list[str] | None = None) -> discord.Embed:
    """Ficha legible: estado guardado separado de cambios pendientes."""
    traps = hp_traps(guild.id)
    enabled, paused = honeypot_enabled(guild.id), honeypot_paused(guild.id)
    state = "Desactivado" if not enabled else "Pausado" if paused else "Activado"
    display_traps = ", ".join(f"<#{cid}>" for cid in list(traps)[:5])
    if len(traps) > 5:
        display_traps += f" y {len(traps) - 5} más"
    state_lines = [
        f"**Protección:** {state}",
        f"**Canales trampa:** {len(traps)}" + (f" · {display_traps}" if traps else ""),
    ]
    if paused and enabled:
        state_lines.append("Pausa de seguridad: revise los canales antes de reanudar.")

    action = hp_action(guild.id)
    measure_lines = [f"**Acción:** {HONEYPOT_ACTION_LABELS.get(action, action)}"]
    if action == "role":
        role_id = hp_punish_role_id(guild.id)
        measure_lines.append(f"**Rol:** {f'<@&{role_id}>' if role_id else 'No configurado'}")
        measure_lines.append(f"**Purga:** {format_purge_spec(*hp_purge_spec(guild.id))}")
    elif action == "timeout":
        measure_lines.append(f"**Duración:** {format_duration(hp_timeout_minutes(guild.id))}")
        measure_lines.append(f"**Purga:** {format_purge_spec(*hp_purge_spec(guild.id))}")
    elif action == "kick":
        measure_lines.append(
            f"**Purga:** mensajes de los últimos {format_duration(hp_kick_purge_minutes(guild.id))} (con evidencias)"
        )
    elif action == "ban":
        minutes = hp_ban_duration_minutes(guild.id)
        measure_lines.append(
            f"**Duración:** {format_duration(minutes) if minutes else 'Permanente'}"
        )
        measure_lines.append("**Purga adicional:** ninguna.")

    enabled_warning = hp_warning_enabled(guild.id)
    style = hp_warning_style(guild.id)
    warning = "Desactivado" if not enabled_warning else (
        "Diseño personalizado" if style == "custom" else
        "Texto personalizado" if hp_setting_get(guild.id, "honeypot_warning_text") else
        "Texto predeterminado"
    )
    exempt_roles = len(hp_exempt_ids(guild.id, "role"))
    exempt_members = len(hp_exempt_ids(guild.id, "member"))
    exemptions = (
        f"{exempt_roles} roles · {exempt_members} miembros"
        if exempt_roles or exempt_members else "Ninguna"
    )
    followup_lines = [
        f"**Aviso fijado:** {warning}",
        f"**Exenciones:** {exemptions}",
        f"**Historial:** {hp_total_triggers(guild.id)} capturas · "
        f"retención {format_duration(hp_retention_minutes(guild.id))}",
    ]

    pending = pending or []
    embed = discord.Embed(
        title="AutoMod — Honeypot",
        description="Protección del servidor mediante canales trampa.",
        color=discord.Color.orange() if paused else discord.Color.blurple(),
    )
    embed.add_field(name="Estado actual", value="\n".join(state_lines), inline=False)
    embed.add_field(name="Medida aplicada", value="\n".join(measure_lines), inline=False)
    embed.add_field(name="Aviso y seguimiento", value="\n".join(followup_lines), inline=False)
    embed.add_field(
        name="Cambios pendientes",
        value="\n".join("• " + line for line in pending) if pending else "Ninguno.",
        inline=False,
    )
    embed.set_footer(text="Los cambios pendientes solo se aplican al guardar.")
    return embed


# --- Aviso fijado -----------------------------------------------------------

def hp_warning_embed(channel: discord.abc.GuildChannel | None = None) -> discord.Embed:
    guild_id = channel.guild.id if channel is not None else 0
    ctx = VarContext(channel.guild if channel is not None else None, None, channel)
    if hp_warning_style(guild_id) == "custom":
        cfg = hp_warning_custom(guild_id)
        try:
            color = discord.Color(int(cfg["color"].lstrip("#"), 16))
        except ValueError:
            color = discord.Color.gold()
        embed = discord.Embed(
            title=render_vars(cfg["title"], ctx, 256),
            description=render_vars(cfg["description"], ctx, 4096), color=color,
        )
        image = render_url_var(cfg["image"], ctx) if cfg["image"] else ""
        if image:
            embed.set_image(url=image)
        thumbnail = render_url_var(cfg["thumbnail"], ctx) if cfg["thumbnail"] else ""
        if thumbnail:
            embed.set_thumbnail(url=thumbnail)
        footer = render_vars(cfg["footer"], ctx, 2048) if cfg["footer"] else ""
        if footer:
            embed.set_footer(text=footer)
        return embed
    return discord.Embed(
        title="Advertencia: No escribas en este canal",
        description=render_vars(hp_warning_text(guild_id), ctx, 4096),
        color=discord.Color.gold(),
    )


async def hp_sync_warning(channel: discord.TextChannel) -> str | None:
    """Publica/actualiza (o borra) el aviso fijado de un canal trampa. Devuelve un
    texto de error o None si todo fue bien."""
    msg_id = hp_traps(channel.guild.id).get(channel.id)
    existing: discord.Message | None = None
    if msg_id:
        try:
            existing = await channel.fetch_message(msg_id)
        except discord.NotFound:
            existing = None
        except discord.HTTPException as e:
            return f"{channel.mention}: no pude leer el aviso (`{e}`)"

    try:
        if not hp_warning_enabled(channel.guild.id):
            if existing:
                await existing.delete()
            hp_set_warning_message(channel.guild.id, channel.id, None)
            return None
        if existing:
            await existing.edit(embed=hp_warning_embed(channel))
            if not existing.pinned:
                await existing.pin()
            return None
        message = await channel.send(embed=hp_warning_embed(channel))
        await message.pin()
        hp_set_warning_message(channel.guild.id, channel.id, message.id)
        # Quita el mensaje de sistema "X ha fijado un mensaje".
        async for m in channel.history(limit=5):
            if m.type == discord.MessageType.pins_add:
                await m.delete()
                break
    except discord.Forbidden:
        return f"{channel.mention}: faltan permisos (Enviar mensajes y Gestionar mensajes)"
    except discord.HTTPException as e:
        return f"{channel.mention}: error al publicar el aviso (`{e}`)"
    return None


async def hp_sync_all_warnings(guild: discord.Guild) -> list[str]:
    errors: list[str] = []
    for channel_id in list(hp_traps(guild.id)):
        channel = guild.get_channel(channel_id)
        if isinstance(channel, discord.TextChannel):
            err = await hp_sync_warning(channel)
            if err:
                errors.append(err)
    return errors


# --- Castigo ----------------------------------------------------------------

# --- Motor de purga (sin límites): lo usan el honeypot y /purge ----------------

PURGE_MAX_MINUTES = 100 * 365 * 24 * 60  # 100 años: en la práctica, sin tope
_purge_running: set[tuple[int, int]] = set()  # (guild_id, user_id) con una purga en curso


@dataclass
class PurgeResult:
    deleted: int = 0
    failed: int = 0
    channels_scanned: int = 0
    channels_skipped: int = 0


def parse_purge_spec(text: str) -> tuple[str, int]:
    """'todo' | '200 mensajes' | '30m' / '12h' / '2d' / '1d 12h' | '0' -> (tipo, valor).
    Tipos: none, all, count (N mensajes), time (minutos hacia atrás)."""
    raw = text.strip().lower()
    if raw in ("0", "ninguno", "nada", "no"):
        return "none", 0
    if raw in ("todo", "todos", "all", "siempre"):
        return "all", 0
    m = re.fullmatch(r"(\d+)\s*(?:msgs?|mensajes?)", raw)
    if m:
        n = int(m.group(1))
        if n < 1:
            raise ValueError("La cantidad de mensajes debe ser al menos 1.")
        return "count", n
    try:
        return "time", parse_duration(raw, 1, PURGE_MAX_MINUTES)
    except ValueError:
        raise ValueError(
            f"No entendí `{text}`. Usa `todo`, una cantidad (`200 mensajes`), un tiempo hacia atrás "
            f"(`30m`, `12h`, `2d`, `1d 12h 30m`) o `0` para no borrar."
        )


def format_purge_spec(kind: str, value: int) -> str:
    if kind == "none":
        return "no borrar"
    if kind == "all":
        return "todos sus mensajes"
    if kind == "count":
        return f"sus últimos {value} mensajes"
    return f"mensajes de los últimos {format_duration(value)}"


async def purge_targets(guild: discord.Guild, only=None, after: datetime | None = None) -> list:
    """Canales y hilos donde buscar mensajes (incluye hilos activos y archivados públicos)."""
    if only is not None:
        if isinstance(only, discord.ForumChannel):
            threads = list(only.threads)
            try:
                async for t in only.archived_threads(limit=None):
                    if after is not None and t.archive_timestamp < after:
                        break  # vienen del más reciente al más antiguo
                    threads.append(t)
            except discord.HTTPException:
                pass
            return threads
        return [only]
    targets: dict[int, object] = {}
    for ch in [*guild.text_channels, *guild.voice_channels, *guild.stage_channels, *guild.threads]:
        targets[ch.id] = ch
    for parent in [*guild.text_channels, *guild.forums]:
        try:
            async for t in parent.archived_threads(limit=None):
                if after is not None and t.archive_timestamp < after:
                    break  # archivado antes del corte: no puede tener mensajes más nuevos
                targets[t.id] = t
        except discord.HTTPException:
            continue  # sin permiso para ver hilos archivados de ese canal
    for forum in guild.forums:
        for t in forum.threads:
            targets[t.id] = t
    return list(targets.values())


_PURGE_URL_RE = re.compile(r"https?://[^\s<>]+|(?:www\.)[^\s<>]+", re.IGNORECASE)


def _purge_message_matches(message: discord.Message, content_type: str) -> bool:
    """Determina si un mensaje entra en el filtro multimedia solicitado por /purge."""
    if content_type == "all":
        return True

    content = (message.content or "").strip()
    if content_type == "links":
        return bool(_PURGE_URL_RE.search(content))

    if content_type == "text":
        if not content:
            return False
        # Texto acompañado de una imagen o vídeo NO cuenta como texto puro.
        has_image_or_video = any(
            (a.content_type or "").lower().startswith(("image/", "video/"))
            or Path(a.filename).suffix.lower() in {
                ".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".tif", ".tiff",
                ".mp4", ".mov", ".webm", ".mkv", ".avi", ".m4v", ".mpeg", ".mpg",
            }
            for a in message.attachments
        )
        return not has_image_or_video

    return True


async def _collect_user_messages(
    ch, user_id: int, after, before, limit: int | None, content_type: str = "all"
) -> list[int]:
    ids: list[int] = []
    kwargs = {"limit": None, "after": after, "before": before}
    if limit is not None:
        kwargs["oldest_first"] = False  # para quedarnos con los más recientes
    async for m in ch.history(**kwargs):
        if m.author.id == user_id and _purge_message_matches(m, content_type):
            ids.append(m.id)
            if limit is not None and len(ids) >= limit:
                break
    return ids


_evidence_delete_inflight: set[tuple[int, int, int]] = set()


async def delete_with_evidence(channel, message_id: int) -> bool:
    """La única ruta de borrado moderativo: copia privada verificada o no borra."""
    guild = channel.guild
    key = (guild.id, channel.id, message_id)
    if key in _evidence_delete_inflight or not bot.intents.message_content:
        return False
    _evidence_delete_inflight.add(key)
    try:
        message = await channel.fetch_message(message_id)
        original_snapshot = evidence_archive.snapshot(message)
        archive = guild.get_channel(get_log_channel_id(guild.id))
        reference = await evidence_archive.preserve(message, archive, DB_PATH)
        if not reference:
            print("Evidencias: borrado bloqueado; archivo privado incompleto o pendiente de revisión.")
            return False
        # Releer: una edición durante la copia exige archivar la nueva versión.
        current = await channel.fetch_message(message_id)
        if evidence_archive.snapshot(current) != original_snapshot:
            return False
        if not evidence_archive.private_channel(guild, archive):
            return False
        await current.delete()
        return True
    except Exception as exc:
        # No volcar contenido, respuestas HTTP ni URLs privadas a stdout.
        print(f"Evidencias: borrado bloqueado ({type(exc).__name__}).")
        return False
    finally:
        _evidence_delete_inflight.discard(key)


async def delete_honeypot_message(
    channel, message_id: int, expected_author_id: int,
    *, after: datetime | None = None, before: datetime | None = None,
) -> bool:
    """Solo Honeypot: borrar sin archivo, verificando servidor, autor y rango vigente."""
    guild = channel.guild
    key = (guild.id, channel.id, message_id)
    if key in _evidence_delete_inflight or expected_author_id <= 0 or guild.me is None:
        return False
    permissions = channel.permissions_for(guild.me)
    if not (permissions.view_channel and permissions.read_message_history and permissions.manage_messages):
        return False
    _evidence_delete_inflight.add(key)
    try:
        message = await channel.fetch_message(message_id)
        if (
            message.guild.id != guild.id or message.channel.id != channel.id
            or message.author.id != expected_author_id
            or (after is not None and message.created_at <= after)
            or (before is not None and message.created_at >= before)
        ):
            return False
        await message.delete()
        return True
    except Exception as exc:
        # No registrar el contenido ni los datos de un mensaje eliminado.
        print(f"Honeypot: borrado omitido ({type(exc).__name__}).")
        return False
    finally:
        _evidence_delete_inflight.discard(key)


async def _delete_ids(
    ch, ids: list[int], *, origin: str = "moderation",
    expected_author_id: int | None = None,
    after: datetime | None = None, before: datetime | None = None,
) -> tuple[int, int]:
    """Conservar evidencia salvo para la excepción explícita de origen Honeypot."""
    deleted = failed = 0
    for message_id in dict.fromkeys(ids):
        if origin == "honeypot":
            ok = (expected_author_id is not None and
                  await delete_honeypot_message(
                      ch, message_id, expected_author_id, after=after, before=before,
                  ))
        else:
            ok = await delete_with_evidence(ch, message_id)
        if ok:
            deleted += 1
        else:
            failed += 1
    return deleted, failed


async def purge_user_messages(
    guild: discord.Guild,
    user_id: int,
    *,
    channel=None,
    after: datetime | None = None,
    before: datetime | None = None,
    limit: int | None = None,
    progress=None,
    content_type: str = "all",
    purge_origin: str = "moderation",
) -> PurgeResult:
    """Borra mensajes de un usuario (aunque ya no esté en el servidor), sin tope propio:
    - sin after/before/limit -> TODOS sus mensajes
    - after/before -> los de ese rango de tiempo
    - limit -> sus N mensajes más recientes (dentro del rango, si lo hay)
    `progress(hechos, total, borrados)` se llama a medida que avanza."""
    result = PurgeResult()
    targets = await purge_targets(guild, channel, after)
    delete_kwargs = (
        {"origin": "honeypot", "expected_author_id": user_id, "after": after, "before": before}
        if purge_origin == "honeypot" else {}
    )
    sem = asyncio.Semaphore(4)  # 4 canales a la vez; discord.py gestiona el rate limit
    collected: list[tuple[object, list[int]]] = []
    done = 0

    async def work(ch) -> None:
        nonlocal done
        perms = ch.permissions_for(guild.me)
        if not (perms.view_channel and perms.read_message_history and perms.manage_messages):
            result.channels_skipped += 1
            return
        async with sem:
            try:
                ids = await _collect_user_messages(ch, user_id, after, before, limit, content_type)
                result.channels_scanned += 1
                if limit is None and ids:  # sin tope global: se borra canal a canal
                    d, f = await _delete_ids(ch, ids, **delete_kwargs)
                    result.deleted += d
                    result.failed += f
                elif ids:
                    collected.append((ch, ids))
            except discord.HTTPException:
                result.channels_skipped += 1
        done += 1
        if progress:
            try:
                await progress(done, len(targets), result.deleted)
            except Exception:
                pass

    await asyncio.gather(*(work(ch) for ch in targets))

    if limit is not None and collected:
        # Los N más recientes entre todos los canales (el id de un mensaje crece con el tiempo).
        pairs = sorted(((i, ch) for ch, ids in collected for i in ids), key=lambda p: p[0], reverse=True)[:limit]
        by_channel: dict[int, tuple[object, list[int]]] = {}
        for message_id, ch in pairs:
            by_channel.setdefault(ch.id, (ch, []))[1].append(message_id)
        for ch, ids in by_channel.values():
            d, f = await _delete_ids(ch, ids, **delete_kwargs)
            result.deleted += d
            result.failed += f
    return result


def purge_result_text(result: PurgeResult) -> str:
    text = f"**{result.deleted}** mensaje(s) borrado(s) en {result.channels_scanned} canal(es)/hilo(s)"
    if result.failed:
        text += f"; {result.failed} no se pudieron borrar (evidencia o permisos insuficientes)"
    if result.channels_skipped:
        text += f"; {result.channels_skipped} omitido(s) por falta de permisos"
    return text


async def run_purge_job(
    guild: discord.Guild,
    user: discord.abc.User,
    *,
    scope_text: str,
    requested_by: str,
    channel=None,
    after: datetime | None = None,
    before: datetime | None = None,
    limit: int | None = None,
    progress=None,
    content_type: str = "all",
    title: str = "Purga completada",
    log_success: bool = True,
    purge_origin: str = "moderation",
) -> PurgeResult | None:
    """Ejecuta una purga con control de duplicados; el llamador puede integrar el aviso de éxito."""
    key = (guild.id, user.id)
    if key in _purge_running:
        return None
    _purge_running.add(key)
    try:
        result = await purge_user_messages(
            guild, user.id, channel=channel, after=after, before=before, limit=limit,
            progress=progress, content_type=content_type,
            **({"purge_origin": "honeypot"} if purge_origin == "honeypot" else {}),
        )
    except Exception:
        traceback.print_exc()
        await log_embed(
            guild, "Advertencia: Purga fallida",
            f"{requested_by} · {user.mention} · {scope_text}\nOcurrió un error; revisa los logs del bot.",
            discord.Color.red(),
        )
        raise
    finally:
        _purge_running.discard(key)
    if log_success:
        await log_embed(
            guild, title,
            f"{requested_by} · {user.mention} (`{user.id}`)\nAlcance: {scope_text}\n{purge_result_text(result)}",
            discord.Color.green(),
        )
    return result


async def _complete_condemnation_purge_log(
    guild: discord.Guild,
    user: discord.Member,
    *,
    scope_text: str,
    requested_by: str,
    after: datetime | None,
    limit: int | None,
    base_description: str,
    log_message: discord.Message | None,
    purge_origin: str = "moderation",
) -> None:
    """Actualiza el registro de condena al finalizar su purga, sin perder la auditoría."""
    try:
        result = await run_purge_job(
            guild, user, scope_text=scope_text, requested_by=requested_by,
            after=after, limit=limit, title="Purga de condena completada",
            log_success=log_message is None,
            **({"purge_origin": "honeypot"} if purge_origin == "honeypot" else {}),
        )
    except Exception:
        # run_purge_job ya deja una advertencia independiente cuando falla.
        if log_message is not None:
            try:
                await log_message.edit(
                    embed=build_log_template_embed(
                        guild, "Condena aplicada",
                        base_description + "\nPurga: fallida; consulte la advertencia de purga.",
                        discord.Color.dark_red(),
                    )
                )
            except discord.HTTPException:
                pass
        return

    if log_message is None:
        # Sin registro inicial, se conserva el aviso original de purga.
        return
    if result is None:
        status = "Purga: omitida porque ya había otra purga en curso."
    else:
        status = f"Purga: {scope_text}\n{purge_result_text(result)}"
    try:
        await log_message.edit(
            embed=build_log_template_embed(
                guild, "Condena aplicada", base_description + "\n" + status,
                discord.Color.dark_red(),
            )
        )
    except discord.HTTPException:
        # La edición puede fallar si el mensaje o los permisos desaparecieron.
        # En ese caso no se oculta la eliminación efectuada.
        if result is not None:
            await log_embed(
                guild, "Purga de condena completada",
                f"{requested_by} · {user.mention}\nAlcance: {scope_text}\n{purge_result_text(result)}",
                discord.Color.green(),
            )

def hp_start_kick_purge(member: discord.Member) -> str:
    """Purga solo al expulsado, desde hace 24 horas o más, sin archivo de evidencias.

    Verificar cada autor y mensaje; los canales sin acceso se omiten y se registran.
    """
    minutes = hp_kick_purge_minutes(member.guild.id)
    scope = format_purge_spec("time", minutes)
    asyncio.create_task(
        run_purge_job(
            member.guild, member, scope_text=scope,
            requested_by="Honeypot · Expulsión", after=datetime.now(timezone.utc) - timedelta(minutes=minutes),
            title="Purga de expulsión Honeypot completada", purge_origin="honeypot",
        )
    )
    return f"purga solicitada en segundo plano ({scope}; sin archivo de evidencias)"


def hp_start_purge(member: discord.Member) -> str | None:
    """Lanza la purga del honeypot en segundo plano (sin tope: puede tardar). Devuelve un texto
    para el reporte, o None si la purga está desactivada."""
    kind, value = hp_purge_spec(member.guild.id)
    if kind == "none":
        return None
    after = datetime.now(timezone.utc) - timedelta(minutes=value) if kind == "time" else None
    limit = value if kind == "count" else None
    scope = format_purge_spec(kind, value)
    asyncio.create_task(
        run_purge_job(
            member.guild, member, scope_text=scope, requested_by="Honeypot",
            after=after, limit=limit, title="Purga del honeypot completada",
            purge_origin="honeypot",
        )
    )
    return f"purga en segundo plano ({scope})"


class _SyncGuard:
    """Marca los cambios de rol hechos por el propio Heraldo. Al terminar, la marca se mantiene unos
    segundos de gracia: el evento de gateway on_member_update puede llegar DESPUÉS de que
    member.edit() haya devuelto, y sin la gracia el Heraldo reaccionaría a sus propios cambios."""
    GRACE = 5.0

    def __init__(self) -> None:
        self._until: dict[tuple[int, int], float] = {}

    def add(self, user_id: tuple[int, int]) -> None:
        self._until[user_id] = float("inf")

    def discard(self, user_id: tuple[int, int]) -> None:
        if user_id in self._until:
            self._until[user_id] = time.monotonic() + self.GRACE

    def __contains__(self, user_id: object) -> bool:
        until = self._until.get(user_id)  # type: ignore[arg-type]
        if until is None:
            return False
        if time.monotonic() >= until:
            self._until.pop(user_id, None)  # type: ignore[arg-type]
            return False
        return True


_condemn_sync_busy = _SyncGuard()
_condemn_inflight: set[tuple[int, int]] = set()
_pardon_inflight: set[tuple[int, int]] = set()


def condemnation_protection_reason(member: discord.Member) -> str | None:
    """Motivo por el que no se puede condenar a este miembro."""
    guild = member.guild
    if member.id == guild.owner_id:
        return "es el dueño del servidor"
    if member.guild_permissions.administrator:
        return "tiene el permiso Administrador y está exento"
    if member.top_role >= guild.me.top_role:
        return "su rol más alto es igual o superior al del Heraldo"
    if hp_is_exempt(member):
        return "es staff o está en la lista de exentos"
    return None



async def condemnation_fetch_source_message(
    guild: discord.Guild, source_message_url: str | None,
) -> discord.Message | None:
    if not source_message_url:
        return None
    match = re.search(r"discord(?:app)?\.com/channels/(\d+)/(\d+)/(\d+)", source_message_url)
    if not match or int(match.group(1)) != guild.id:
        return None
    channel = guild.get_channel_or_thread(int(match.group(2)))
    if channel is None or not hasattr(channel, "fetch_message"):
        return None
    try:
        return await channel.fetch_message(int(match.group(3)))
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        return None


async def condemnation_archive_evidence(
    guild: discord.Guild,
    member: discord.Member,
    *,
    source_message_url: str | None,
    reason: str,
    applied_by: discord.abc.User | None,
) -> tuple[str | None, str | None]:
    """Conserva el contrato de expedientes usando el archivo verificable común."""
    message = await condemnation_fetch_source_message(guild, source_message_url)
    if message is None or message.author.id != member.id:
        return None, None
    archive_channel = guild.get_channel(get_log_channel_id(guild.id))
    if not bot.intents.message_content or not evidence_archive.private_channel(guild, archive_channel):
        return None, None
    try:
        reference = await evidence_archive.preserve(message, archive_channel, DB_PATH)
        return reference, (message.content or "(sin texto)")[:3500]
    except Exception as exc:
        print(f"Evidencias: archivo de condena bloqueado ({type(exc).__name__}).")
        return None, None


async def condemnation_send_pardon_dm(
    member: discord.Member,
    row: sqlite3.Row,
    pardoned_by: discord.abc.User,
    restored_count: int,
    lost_count: int,
) -> bool:
    condemned_at = datetime.fromisoformat(row["condemned_at"])
    pardoned_at = datetime.now(timezone.utc)
    linked_case = (
        int(row["moderation_case_number"])
        if "moderation_case_number" in row.keys() and row["moderation_case_number"] is not None
        else None
    )
    case_id = condemnation_case_id(member, condemned_at, linked_case)
    embed = discord.Embed(
        title="CONDENA PERDONADA",
        description=(
            f"Tu condena del expediente **{case_id}** ha sido levantada. "
            "Tus roles guardados fueron restaurados en la medida permitida por la jerarquía del servidor."
        ),
        color=discord.Color.green(),
        timestamp=pardoned_at,
    )
    embed.set_thumbnail(url=member.display_avatar.url)
    embed.add_field(name="Expediente", value=case_id, inline=True)
    embed.add_field(name="Condenado", value=f"{member.mention}\n{member}", inline=True)
    embed.add_field(name="Motivo original", value=str(row["reason"])[:1024], inline=False)
    embed.add_field(name="Condenado el", value=discord.utils.format_dt(condemned_at, "F"), inline=True)
    embed.add_field(name="Perdonado por", value=pardoned_by.mention, inline=True)
    embed.add_field(name="Perdonado el", value=discord.utils.format_dt(pardoned_at, "F"), inline=True)
    embed.add_field(name="Resultado", value=(f"Condena levantada. **{restored_count}** rol(es) restaurado(s)" + (f"; **{lost_count}** no se pudieron restaurar." if lost_count else ".")), inline=False)
    embed.add_field(name="Duración original", value=condemnation_duration_text(row), inline=True)
    embed.set_footer(text=f"{member.guild.name} · El Heraldo")
    try:
        await member.send(embed=test_dm_notice_embed(embed))
        return True
    except discord.HTTPException:
        return False


def _build_condemnation_embed(
    guild: discord.Guild, member: discord.Member, reason: str,
    duration_minutes: int | None, origin: str, applied_by: discord.abc.User | None,
    *, source_message_url: str | None = None, source_channel_id: int | None = None,
    removed_role_ids: list[int] | None = None, when: datetime | None = None, case_id: str | None = None,
    include_pardon_button: bool = False, evidence_url: str | None = None, evidence_text: str | None = None,
) -> tuple[discord.Embed, discord.ui.View | None]:
    """Construye la MISMA tarjeta que se usa tanto en el canal de castigo como en el DM."""
    when = when or datetime.now(timezone.utc)
    case_id = case_id or condemnation_case_id(member, when)
    source_channel = guild.get_channel(source_channel_id) if source_channel_id else None

    render = lambda value: _condemnation_render_template(
        value, member=member, guild=guild, case_id=case_id, applied_by=applied_by,
        reason=reason, when=when, source_channel=source_channel,
        duration_minutes=duration_minutes, origin=origin, source_message_url=source_message_url,
        evidence_url=evidence_url,
    )

    embed = discord.Embed(
        title=render(condemnation_template_get(guild.id, "title"))[:256],
        description=render(condemnation_template_get(guild.id, "description"))[:4096],
        color=condemnation_template_color(guild.id),
        timestamp=when,
    )
    embed.set_thumbnail(url=member.display_avatar.url)

    def field(label_key: str, value: str, inline: bool = True) -> None:
        embed.add_field(name=condemnation_template_get(guild.id, label_key)[:256], value=value[:1024] or "—", inline=inline)

    field("label_case", f"`{case_id}`", True)
    field("label_user", f"{member.mention}\n`{member}`", True)
    field("label_by", applied_by.mention if applied_by else "El Heraldo", True)
    field("label_reason", reason, False)
    field("label_when", f"{discord.utils.format_dt(when, 'F')}\n{discord.utils.format_dt(when, 'R')}", True)

    where = source_channel.mention if source_channel else ("Canal del mensaje original" if source_message_url else "No registrado")
    field("label_where", where, True)
    field("label_duration", format_duration(duration_minutes) if duration_minutes else "Indefinida", True)

    role_mentions = []
    for rid in removed_role_ids or []:
        role = guild.get_role(rid)
        if role is not None:
            role_mentions.append(f"`{role.name}`")
    field("label_roles", ", ".join(role_mentions) if role_mentions else "Ninguno (o no asignable)", False)

    if evidence_url:
        value = f"[Abrir evidencia preservada]({evidence_url})"
        if evidence_text:
            value += "\n" + evidence_text[:700]
        field("label_message", value, False)
    elif evidence_text:
        field("label_message", "**Copia de texto preservada:**\n" + evidence_text[:850], False)
    elif source_message_url:
        field(
            "label_message",
            f"[Referencia al mensaje original]({source_message_url}) · no se considera evidencia preservada.",
            False,
        )

    embed.set_footer(text=render(condemnation_template_get(guild.id, "footer"))[:2048])

    button_url = condemnation_template_get(guild.id, "button_url").strip()
    button_label = render(condemnation_template_get(guild.id, "button_label")).strip()[:80]
    valid_button_url = button_url if re.match(r"^https?://", button_url, re.IGNORECASE) else None
    if include_pardon_button:
        view = CondemnationPardonView(
            link_label=button_label or "Ver información del caso",
            link_url=valid_button_url,
        )
    elif valid_button_url:
        view = discord.ui.View(timeout=None)
        view.add_item(
            discord.ui.Button(
                label=button_label or "Ver información del caso",
                style=discord.ButtonStyle.link,
                url=valid_button_url,
            )
        )
    else:
        view = None
    return embed, view


class CondemnationPardonView(discord.ui.View):
    def __init__(self, *, link_label: str | None = None, link_url: str | None = None,
                 thread_url: str | None = None) -> None:
        super().__init__(timeout=None)
        if link_url:
            self.add_item(
                discord.ui.Button(
                    label=(link_label or "Ver información del caso")[:80],
                    style=discord.ButtonStyle.link,
                    url=link_url,
                )
            )
        if thread_url:
            self.add_item(discord.ui.Button(
                label="Conversación privada",
                style=discord.ButtonStyle.link,
                url=thread_url,
            ))
        pardon_button = discord.ui.Button(
            label="Perdonar",
            style=discord.ButtonStyle.success,
            custom_id="heraldo:condemnation:pardon",
        )
        pardon_button.callback = self.pardon_callback
        self.add_item(pardon_button)
        for action, label, style in (
            ("WARN", "Advertir", discord.ButtonStyle.danger),
            ("BAN", "Banear", discord.ButtonStyle.danger),
            ("KICK", "Expulsar", discord.ButtonStyle.danger),
        ):
            button = discord.ui.Button(
                label=label, style=style,
                custom_id=f"heraldo:condemnation:action:{action.lower()}",
            )
            button.callback = lambda interaction, selected=action: self.action_callback(interaction, selected)
            self.add_item(button)

    async def action_callback(self, interaction: discord.Interaction, action: str) -> None:
        if interaction.guild is None or interaction.message is None:
            await interaction.response.send_message("Este botón solo funciona en el servidor.", ephemeral=True)
            return
        permission = {"WARN": "moderate_members", "BAN": "ban_members", "KICK": "kick_members"}[action]
        if not getattr(interaction.user.guild_permissions, permission, False):
            await interaction.response.send_message("No tienes permisos para aplicar esta medida.", ephemeral=True)
            return
        row = condemnation_get_by_announcement_message(interaction.guild.id, interaction.message.id)
        if row is None or not condemnation_linked_case_is_open(row):
            await interaction.response.send_message("Este expediente ya no está abierto.", ephemeral=True)
            return
        await interaction.response.send_modal(
            CondemnationCaseActionModal(interaction.guild.id, interaction.message.id, action)
        )

    async def pardon_callback(
        self,
        interaction: discord.Interaction,
    ) -> None:
        # Acknowledge the interaction immediately. Si cualquier paso posterior
        # falla, Discord no mostrará "La aplicación no respondió".
        if interaction.guild is None or interaction.message is None:
            await interaction.response.send_message(
                "Error: Este botón solo funciona dentro del servidor.",
                ephemeral=True,
            )
            return

        try:
            await interaction.response.defer(ephemeral=True)

            row = condemnation_get_by_announcement_message(
                interaction.guild.id,
                interaction.message.id,
            )
            if row is None:
                await interaction.followup.send(
                    "Información: Este expediente ya no tiene una condena activa o ya fue resuelto.",
                    ephemeral=True,
                )
                return

            member_id = int(row["user_id"])
            member = interaction.guild.get_member(member_id)
            if member is None:
                try:
                    member = await interaction.guild.fetch_member(member_id)
                except discord.HTTPException:
                    member = None

            if member is None:
                await interaction.followup.send(
                    "Error: El miembro asociado a este expediente ya no está disponible en el servidor.",
                    ephemeral=True,
                )
                return

            if (member.guild.id, member.id) in _pardon_inflight:
                await interaction.followup.send(
                    "Este perdón ya se está procesando.",
                    ephemeral=True,
                )
                return
            if condemnation_case_action_in_progress(interaction.guild.id, interaction.message.id):
                await interaction.followup.send(
                    "Hay una medida moderadora pendiente de confirmar o revisar en este expediente.",
                    ephemeral=True,
                )
                return

            is_admin = bool(
                getattr(interaction.user.guild_permissions, "administrator", False)
            )
            is_condemner = (
                row["applied_by"] is not None
                and int(row["applied_by"]) == interaction.user.id
            )
            if not (is_admin or is_condemner):
                await interaction.followup.send(
                    "No puedes perdonar esta condena. Solo puede hacerlo quien la aplicó o un administrador.",
                    ephemeral=True,
                )
                return

            _pardon_inflight.add((member.guild.id, member.id))
            try:
                ok, note = await release_condemned_member(
                    member,
                    released_by=interaction.user,
                    pardon=True,
                    announcement_message=interaction.message,
                )
            finally:
                _pardon_inflight.discard((member.guild.id, member.id))

            await interaction.followup.send(
                ("" if ok else "Error: ") + note,
                ephemeral=True,
            )
        except Exception:
            traceback.print_exc()
            try:
                if interaction.response.is_done():
                    await interaction.followup.send(
                        "Error: Ocurrió un error al procesar el perdón. El error quedó registrado en los logs del bot.",
                        ephemeral=True,
                    )
                else:
                    await interaction.response.send_message(
                        "Error: Ocurrió un error al procesar el perdón. El error quedó registrado en los logs del bot.",
                        ephemeral=True,
                    )
            except Exception:
                traceback.print_exc()


def condemnation_linked_case_is_open(row: sqlite3.Row) -> bool:
    number = row["moderation_case_number"] if "moderation_case_number" in row.keys() else None
    if number is None:
        return True
    case = moderation_case_get(int(row["guild_id"]), int(number))
    return case is not None and bool(case["open"])


def condemnation_case_action_claim(guild_id: int, message_id: int, action: str) -> bool:
    """Persistent at-most-once guard; a restart cannot repeat a sanction by button."""
    conn = db_connect()
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS condemnation_case_actions ("
            "guild_id INTEGER NOT NULL, message_id INTEGER NOT NULL, action TEXT NOT NULL, "
            "state TEXT NOT NULL, resulting_case INTEGER, created_at TEXT NOT NULL, "
            "PRIMARY KEY(guild_id, message_id, action))"
        )
        conn.execute("BEGIN IMMEDIATE")
        ongoing = conn.execute(
            "SELECT 1 FROM condemnation_case_actions "
            "WHERE guild_id=? AND message_id=? AND state='pending' LIMIT 1",
            (guild_id, message_id),
        ).fetchone()
        if ongoing:
            conn.rollback()
            return False
        result = conn.execute(
            "INSERT OR IGNORE INTO condemnation_case_actions "
            "(guild_id,message_id,action,state,created_at) VALUES(?,?,?,'pending',?)",
            (guild_id, message_id, action, datetime.now(timezone.utc).isoformat()),
        )
        conn.commit()
        return result.rowcount == 1
    finally:
        conn.close()


def condemnation_case_action_in_progress(guild_id: int, message_id: int) -> bool:
    conn = db_connect()
    try:
        # Los servidores antiguos no tienen esta tabla hasta que se utiliza
        # un botón de medida. Crear el esquema sin modificar acciones previas.
        conn.execute(
            "CREATE TABLE IF NOT EXISTS condemnation_case_actions ("
            "guild_id INTEGER NOT NULL, message_id INTEGER NOT NULL, action TEXT NOT NULL, "
            "state TEXT NOT NULL, resulting_case INTEGER, created_at TEXT NOT NULL, "
            "PRIMARY KEY(guild_id, message_id, action))"
        )
        return conn.execute(
            "SELECT 1 FROM condemnation_case_actions "
            "WHERE guild_id=? AND message_id=? AND state='pending' LIMIT 1",
            (guild_id, message_id),
        ).fetchone() is not None
    except sqlite3.OperationalError:
        # No permitir un perdón concurrente si SQLite no permite comprobar
        # que otra sanción por botón está pendiente. El llamador informará del error.
        raise
    finally:
        conn.close()


def condemnation_case_action_finish(
    guild_id: int, message_id: int, action: str, successful: bool, case_number: int | None
) -> None:
    conn = db_connect()
    try:
        conn.execute(
            "UPDATE condemnation_case_actions SET state=?, resulting_case=? "
            "WHERE guild_id=? AND message_id=? AND action=?",
            ("applied" if successful else "failed", case_number, guild_id, message_id, action),
        )
    finally:
        conn.close()


class CondemnationCaseActionModal(discord.ui.Modal):
    reason_input = discord.ui.TextInput(
        label="Motivo adicional", style=discord.TextStyle.paragraph,
        required=False, max_length=500, placeholder="En Railway Test es opcional",
    )

    def __init__(self, guild_id: int, message_id: int, action: str):
        label = {"WARN": "Advertir", "KICK": "Expulsar", "BAN": "Banear"}[action]
        super().__init__(title=f"Expediente · {label}")
        self.guild_id, self.message_id, self.action = guild_id, message_id, action

    async def on_submit(self, interaction: discord.Interaction) -> None:
        if interaction.guild is None or interaction.guild.id != self.guild_id:
            await interaction.response.send_message("Servidor incorrecto.", ephemeral=True)
            return
        row = condemnation_get_by_announcement_message(self.guild_id, self.message_id)
        if row is None or not condemnation_linked_case_is_open(row):
            await interaction.response.send_message("El expediente ya está cerrado.", ephemeral=True)
            return
        reason = str(self.reason_input).strip()
        if not reason:
            if os.getenv("RAILWAY_PROJECT_ID") == "747a1ee0-cdab-4ad5-8e45-a6ddfccc9b61":
                reason = "Prueba funcional autorizada de El Heraldo Test."
            else:
                await interaction.response.send_message(
                    "El motivo es obligatorio fuera de El Heraldo Test.", ephemeral=True,
                )
                return
        code = (moderation_case_code(int(row["moderation_case_number"]), self.guild_id)
                if row["moderation_case_number"] else f"expediente {self.message_id}")
        action_label = {"WARN": "Advertir", "KICK": "Expulsar", "BAN": "Banear"}[self.action]
        await interaction.response.send_message(
            f"Confirma **{action_label}** a <@{row['user_id']}> desde {code}.\n"
            f"Motivo: {discord.utils.escape_markdown(reason)}\n"
            + ("Una advertencia puede activar la sanción automática por acumulación.\n" if self.action == "WARN" else "")
            + "**La medida puede afectar realmente al usuario.**",
            view=CondemnationCaseConfirmView(
                self.guild_id, self.message_id, self.action, reason, interaction.user.id),
            ephemeral=True,
            allowed_mentions=discord.AllowedMentions.none(),
        )


class CondemnationCaseConfirmView(discord.ui.View):
    def __init__(self, guild_id: int, message_id: int, action: str, reason: str, owner_id: int):
        super().__init__(timeout=180)
        self.guild_id, self.message_id, self.action = guild_id, message_id, action
        self.reason, self.owner_id = reason, owner_id

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.guild is None or interaction.guild.id != self.guild_id or interaction.user.id != self.owner_id:
            await interaction.response.send_message("Esta confirmación corresponde a otro moderador.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Confirmar medida", style=discord.ButtonStyle.danger)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        permission = {"WARN": "moderate_members", "KICK": "kick_members", "BAN": "ban_members"}[self.action]
        if not getattr(interaction.user.guild_permissions, permission, False):
            await interaction.response.send_message("Ya no tienes permiso para esa acción.", ephemeral=True)
            return
        row = condemnation_get_by_announcement_message(self.guild_id, self.message_id)
        if row is None or not condemnation_linked_case_is_open(row):
            await interaction.response.send_message("El expediente se cerró o dejó de estar disponible.", ephemeral=True)
            return
        await interaction.response.defer(ephemeral=True, thinking=True)
        member = interaction.guild.get_member(int(row["user_id"]))
        if member is None:
            try:
                member = await interaction.guild.fetch_member(int(row["user_id"]))
            except discord.HTTPException:
                member = None
        if member is None:
            await interaction.followup.send(
                "El usuario ya no está en el servidor; no se aplicó la medida.", ephemeral=True)
            return
        if (self.guild_id, member.id) in _pardon_inflight:
            await interaction.followup.send("Se está procesando un perdón para este miembro.", ephemeral=True)
            return
        # Recheck after the network fetch so a closed case is not acted on.
        fresh = condemnation_get_by_announcement_message(self.guild_id, self.message_id)
        if fresh is None or not condemnation_linked_case_is_open(fresh):
            await interaction.followup.send("El expediente ya se cerró.", ephemeral=True)
            return
        # This atomic claim also protects retries after a crashed worker.
        if not condemnation_case_action_claim(self.guild_id, self.message_id, self.action):
            await interaction.followup.send(
                "Esta medida ya fue procesada o está pendiente de revisión. "
                "No se repetirá automáticamente.", ephemeral=True)
            return
        linked = row["moderation_case_number"]
        origin = (moderation_case_code(int(linked), self.guild_id)
                  if linked else f"mensaje {self.message_id}")
        try:
            ok, note, created = await moderation_apply_case_punishment(
                interaction, member, self.action, self.reason, None,
                f"Expediente de condena de origen: {origin}",
            )
        except Exception:
            traceback.print_exc()
            await interaction.followup.send(
                "No se pudo verificar el resultado. Se bloqueó el reintento automático "
                "para evitar sanciones duplicadas; revisa los registros.", ephemeral=True,
            )
            return
        condemnation_case_action_finish(
            self.guild_id, self.message_id, self.action, ok, created,
        )
        await interaction.followup.send(
            (f"{note}\nEl expediente de condena original permanece abierto "
             "hasta su resolución." if ok
             else f"No se aplicó la medida: {note}. "
             "No se repetirá desde este botón sin revisión administrativa."),
            ephemeral=True,
        )
        self.stop()

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        self.stop()
        await interaction.response.edit_message(content="Medida cancelada. No se aplicó ninguna sanción.", view=None)


async def condemnation_send_dm(
    member: discord.Member, reason: str, duration_minutes: int | None, origin: str,
    applied_by: discord.abc.User | None = None,
    *, source_message_url: str | None = None, source_channel_id: int | None = None,
    removed_role_ids: list[int] | None = None, when: datetime | None = None, case_id: str | None = None,
    evidence_url: str | None = None, evidence_text: str | None = None,
) -> bool:
    """Envía por DM la misma tarjeta de condena, incluido el botón configurable."""
    embed, view = _build_condemnation_embed(
        member.guild, member, reason, duration_minutes, origin, applied_by,
        source_message_url=source_message_url, source_channel_id=source_channel_id,
        removed_role_ids=removed_role_ids, when=when, case_id=case_id,
        include_pardon_button=False, evidence_url=evidence_url, evidence_text=evidence_text,
    )
    try:
        await member.send(embed=test_dm_notice_embed(embed), view=view)
        return True
    except discord.HTTPException:
        return False


def condemnation_template_get(guild_id: int, key: str) -> str:
    value = guild_config_get(guild_id, f"condemnation_template_{key}")
    if value is not None:
        return value
    if legacy_fallback_allowed(guild_id):
        legacy = db_meta_get(f"condemnation_template_{key}")
        if legacy is not None:
            return legacy
    return CONDEMNATION_TEMPLATE_DEFAULTS[key]


def condemnation_template_set(guild_id: int, key: str, value: str) -> None:
    guild_config_set(guild_id, f"condemnation_template_{key}", value[:1024])


def condemnation_template_reset(guild_id: int) -> None:
    conn = db_connect()
    for key in CONDEMNATION_TEMPLATE_DEFAULTS:
        conn.execute(
            "DELETE FROM guild_settings WHERE guild_id = ? AND key = ?",
            (guild_id, f"condemnation_template_{key}"),
        )
    conn.commit()
    conn.close()


def condemnation_template_color(guild_id: int) -> discord.Color:
    raw = condemnation_template_get(guild_id, "color").strip().lstrip("#")
    try:
        value = int(raw, 16)
        if not 0 <= value <= 0xFFFFFF:
            raise ValueError
        return discord.Color(value)
    except ValueError:
        return discord.Color.dark_red()


def condemnation_case_id(
    member: discord.Member, when: datetime, moderation_case_number: int | None = None,
) -> str:
    # Las condenas nuevas usan el mismo identificador único que Moderation Cases.
    if moderation_case_number is not None:
        return moderation_case_code(moderation_case_number, member.guild.id)
    # Compatibilidad para expedientes antiguos creados antes de Moderation Cases.
    return f"C-{when.astimezone(STREAK_TZ):%Y%m%d}-{member.id % 100000:05d}"


def _condemnation_render_template(text: str, *, member: discord.Member, guild: discord.Guild,
                                  case_id: str, applied_by: discord.abc.User | None,
                                  reason: str, when: datetime, source_channel: discord.abc.GuildChannel | None,
                                  duration_minutes: int | None, origin: str,
                                  source_message_url: str | None, evidence_url: str | None = None) -> str:
    values = {
        "{usuario}": member.mention,
        "{servidor}": guild.name,
        "{caso}": case_id,
        "{moderador}": applied_by.mention if applied_by else "El Heraldo",
        "{motivo}": reason,
        "{fecha}": discord.utils.format_dt(when, "F"),
        "{fecha_relativa}": discord.utils.format_dt(when, "R"),
        "{canal}": source_channel.mention if source_channel else "No registrado",
        "{duracion}": format_duration(duration_minutes) if duration_minutes else "Indefinida",
        "{mensaje}": (
            f"[Abrir evidencia preservada]({evidence_url})"
            if evidence_url
            else f"[Referencia original]({source_message_url})" if source_message_url else "No disponible"
        ),
    }
    for key, value in values.items():
        text = text.replace(key, value)
    return text


def condemnation_thread_view(message: discord.Message, thread: discord.Thread) -> discord.ui.View:
    """Conservar la tarjeta y enlaces anteriores; solo sumar el acceso al hilo."""
    previous_link = None
    for action_row in message.components:
        for component in action_row.children:
            if (getattr(component, "style", None) == discord.ButtonStyle.link
                    and getattr(component, "url", None)
                    and getattr(component, "label", None) != "Conversación privada"):
                previous_link = component
                break
        if previous_link is not None:
            break
    return CondemnationPardonView(
        link_label=getattr(previous_link, "label", None),
        link_url=getattr(previous_link, "url", None),
        thread_url=thread.jump_url,
    )


async def condemnation_fetch_private_thread(guild: discord.Guild, thread_id: int) -> discord.Thread | None:
    channel = guild.get_thread(thread_id)
    if channel is None:
        try:
            channel = await guild.fetch_channel(thread_id)
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            return None
    return channel if isinstance(channel, discord.Thread) and channel.type == discord.ChannelType.private_thread else None


async def condemnation_ensure_private_thread(
    guild: discord.Guild, member: discord.Member, message_id: int, case_id: str,
) -> bool:
    """Reintento idempotente del hilo; jamás crea uno público como alternativa."""
    row = condemnation_get(guild.id, member.id)
    if row is None or not row["thread_requested"] or int(row["announcement_message_id"] or 0) != message_id:
        return False
    channel = guild.get_channel(condemnation_channel_id(guild.id))
    if not isinstance(channel, discord.TextChannel):
        return False

    me = guild.me
    if me is None:
        return False
    bot_perms = channel.permissions_for(me)
    if not (bot_perms.view_channel and bot_perms.read_message_history
            and bot_perms.create_private_threads and bot_perms.send_messages_in_threads):
        await log_embed(guild, "Advertencia: Conversación privada no disponible",
                        "El Heraldo necesita Ver canal, Leer historial, Crear hilos privados "
                        "y Enviar mensajes en hilos en el canal de condenados.", discord.Color.orange())
        return False
    try:
        current_member = await guild.fetch_member(member.id)
        member_perms = channel.permissions_for(current_member)
        missing = []
        if not member_perms.view_channel:
            missing.append("Ver canal")
        if not member_perms.read_message_history:
            missing.append("Leer historial")
        if not member_perms.send_messages_in_threads:
            missing.append("Enviar mensajes en hilos")
        if member_perms.manage_threads:
            missing.append("tiene Gestionar hilos (no compatible con privacidad estricta)")
        if missing:
            await log_embed(
                guild, "Advertencia: Acceso a expediente no disponible",
                "Permisos del condenado en el canal de condenados: " + ", ".join(missing)
                + ". Ajusta permisos de forma explícita; no se abrirá un hilo público.",
                discord.Color.orange(),
            )
            return False
        message = await channel.fetch_message(message_id)
        thread = None
        if row["thread_id"]:
            thread = await condemnation_fetch_private_thread(guild, int(row["thread_id"]))
            if thread is None or thread.parent_id != channel.id:
                await log_embed(guild, "Advertencia: Hilo privado del expediente inaccesible",
                                "La conversación registrada no está disponible. "
                                "No se creará automáticamente otra para evitar expedientes duplicados.",
                                discord.Color.orange())
                return False
        else:
            thread = await channel.create_thread(
                name=f"Expediente {case_id} · {member.display_name}"[:100],
                type=discord.ChannelType.private_thread,
                invitable=False,
                auto_archive_duration=1440,
                reason="El Heraldo: conversación privada de expediente",
            )
            if not condemnation_thread_save_id(guild.id, member.id, message_id, thread.id):
                await thread.edit(archived=True, locked=True,
                                  reason="Expediente reemplazado antes de completar el hilo")
                return False
        # Un reinicio tras crear el hilo no debe dejarlo sin acceso.
        if thread.archived and not thread.locked:
            await thread.edit(archived=False, reason="Reapertura de conversación activa")
        await thread.add_user(current_member)
        # La conversación arranca con el vínculo al expediente, sin otra mención/ping.
        if not row["thread_id"]:
            await thread.send(
                f"Conversación privada del expediente {case_id}. "
                f"La resolución principal está disponible en {message.jump_url}. "
                "El condenado puede comunicarse aquí con los administradores.",
                allowed_mentions=discord.AllowedMentions.none(),
            )
        # No editar el embed ni el texto de mención: se mantienen sin cambios.
        await message.edit(view=condemnation_thread_view(message, thread))
        return True
    except (discord.Forbidden, discord.HTTPException) as exc:
        print(f"Expedientes: no se pudo preparar conversación privada ({type(exc).__name__}).")
        await log_embed(guild, "Advertencia: Conversación privada pendiente",
                        "No se completó la invitación o el enlace del expediente. "
                        "Verifica permisos y disponibilidad de hilos privados.", discord.Color.orange())
        return False




async def condemnation_mark_closed_card(
    guild: discord.Guild, row: sqlite3.Row, status: str,
) -> None:
    """Remove the persistent staff actions from resolved cases without losing evidence."""
    message_id = row["announcement_message_id"]
    if not message_id:
        return
    channel = guild.get_channel(condemnation_channel_id(guild.id))
    if not isinstance(channel, discord.TextChannel):
        return
    try:
        message = await channel.fetch_message(int(message_id))
        embed = message.embeds[0].copy() if message.embeds else None
        if embed is not None:
            index = next((i for i, field in enumerate(embed.fields)
                          if field.name == "Estado del expediente"), None)
            if index is None:
                embed.add_field(name="Estado del expediente", value=status[:1024], inline=False)
            else:
                embed.set_field_at(index, name="Estado del expediente",
                                   value=status[:1024], inline=False)
        await message.edit(
            embed=embed, view=None,
            allowed_mentions=discord.AllowedMentions.none(),
        )
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        print("Advertencia: no se pudo cerrar visualmente la tarjeta del expediente.")


async def condemnation_close_private_thread(guild: discord.Guild, thread_id: int | None) -> None:
    if not thread_id:
        return
    thread = await condemnation_fetch_private_thread(guild, int(thread_id))
    if thread is None:
        return
    try:
        if not thread.archived:
            await thread.send("La condena ha finalizado. Este hilo queda cerrado y archivado.",
                              allowed_mentions=discord.AllowedMentions.none())
        await thread.edit(archived=True, locked=True, reason="Resolución del expediente")
    except (discord.Forbidden, discord.HTTPException):
        await log_embed(guild, "Advertencia: Conversación privada sin cerrar",
                        "No se pudo archivar el hilo privado de un expediente resuelto.",
                        discord.Color.orange())


async def condemnation_recover_private_threads(guild: discord.Guild) -> None:
    """Reparar únicamente expedientes nuevos marcados, nunca migrar tarjetas históricas."""
    for row in condemnation_list(guild.id):
        if not row["thread_requested"] or not row["announcement_message_id"]:
            continue
        member = guild.get_member(int(row["user_id"]))
        if member is None:
            continue
        case_id = condemnation_case_id(
            member, datetime.fromisoformat(row["condemned_at"]),
            int(row["moderation_case_number"]) if row["moderation_case_number"] else None,
        )
        await condemnation_ensure_private_thread(
            guild, member, int(row["announcement_message_id"]), case_id,
        )
        await asyncio.sleep(0.25)


async def condemnation_announce(
    guild: discord.Guild, member: discord.Member, reason: str,
    duration_minutes: int | None, origin: str, applied_by: discord.abc.User | None,
    *, source_message_url: str | None = None, source_channel_id: int | None = None,
    removed_role_ids: list[int] | None = None, when: datetime | None = None, case_id: str | None = None,
    evidence_url: str | None = None, evidence_text: str | None = None,
) -> int | None:
    channel = guild.get_channel(condemnation_channel_id(guild.id))
    if not isinstance(channel, discord.TextChannel):
        return None
    embed, view = _build_condemnation_embed(
        guild, member, reason, duration_minutes, origin, applied_by,
        source_message_url=source_message_url, source_channel_id=source_channel_id,
        removed_role_ids=removed_role_ids, when=when, case_id=case_id,
        include_pardon_button=True, evidence_url=evidence_url, evidence_text=evidence_text,
    )
    try:
        message = await channel.send(
            content=member.mention, embed=embed, view=view,
            allowed_mentions=discord.AllowedMentions(users=[member], roles=False, everyone=False),
        )
        return message.id
    except discord.HTTPException:
        return None


async def condemnation_update_pardoned_card(
    member: discord.Member,
    row: sqlite3.Row,
    pardoned_by: discord.abc.User,
    restored_count: int,
    lost_count: int,
    message: discord.Message | None = None,
) -> bool:
    """Actualiza la tarjeta original en el sitio; conserva el identificador del expediente."""
    message_id = row["announcement_message_id"] if "announcement_message_id" in row.keys() else None
    expected_channel_id = condemnation_channel_id(member.guild.id)

    try:
        if message is None:
            if not message_id or not expected_channel_id:
                return False
            channel = member.guild.get_channel(expected_channel_id)
            if not isinstance(channel, discord.TextChannel):
                channel = await member.guild.fetch_channel(expected_channel_id)
            if not isinstance(channel, discord.TextChannel):
                return False
            message = await channel.fetch_message(int(message_id))
        elif message.channel.id != expected_channel_id:
            return False

        condemned_at = datetime.fromisoformat(row["condemned_at"])
        linked_case = (
            int(row["moderation_case_number"])
            if "moderation_case_number" in row.keys() and row["moderation_case_number"] is not None
            else None
        )
        case_id = condemnation_case_id(member, condemned_at, linked_case)
        pardoned_at = datetime.now(timezone.utc)

        resolution = discord.Embed(
            title="CONDENA PERDONADA",
            description=(
                f"El expediente **{case_id}** ha sido resuelto mediante perdón. "
                "Esta tarjeta registra la resolución del caso."
            ),
            color=discord.Color.green(),
            timestamp=pardoned_at,
        )
        resolution.set_thumbnail(url=member.display_avatar.url)
        resolution.add_field(name="Expediente", value=f"`{case_id}`", inline=True)
        resolution.add_field(name="Condenado", value=f"{member.mention}\n`{member}`", inline=True)
        resolution.add_field(name="Motivo original", value=(HERALDO_TEST_REASON if heraldo_is_test() else str(row["reason"]))[:1024], inline=False)
        resolution.add_field(name="Condenado el", value=discord.utils.format_dt(condemned_at, "F"), inline=True)
        resolution.add_field(name="Perdonado por", value=pardoned_by.mention, inline=True)
        resolution.add_field(name="Perdonado el", value=discord.utils.format_dt(pardoned_at, "F"), inline=True)

        result = f"Condena levantada. **{restored_count}** rol(es) restaurado(s)"
        if lost_count:
            result += f"; **{lost_count}** no se pudieron restaurar."
        else:
            result += "."
        resolution.add_field(name="Resultado", value=result, inline=False)
        resolution.add_field(name="Duración original", value=condemnation_duration_text(row), inline=True)
        resolution.set_footer(text=f"{member.guild.name} · El Heraldo · Resolución {case_id}")

        # Keep the original case message (and private thread reference).
        await message.edit(
            embed=resolution,
            view=None,
            allowed_mentions=discord.AllowedMentions.none(),
        )
        return True
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        traceback.print_exc()
        return False
    except Exception:
        traceback.print_exc()
        return False

def condemnation_role_id(row: sqlite3.Row | None = None, guild_id: int | None = None) -> int:
    if row is not None and row["role_id"]:
        return int(row["role_id"])
    if guild_id is None and row is not None and "guild_id" in row.keys():
        guild_id = int(row["guild_id"])
    return hp_punish_role_id(guild_id) if guild_id is not None else 0


async def condemnation_sync_roles(
    member: discord.Member,
    *,
    preserve_role_ids: list[int] | None = None,
    save_snapshot: bool = False,
    reason: str = "Condena de El Heraldo",
    role_id: int | None = None,
) -> tuple[bool, list[int], str]:
    """Deja solo el rol de condenado entre los roles asignables y conserva roles gestionados."""
    guild = member.guild
    punish_role = guild.get_role(role_id or hp_punish_role_id(guild.id))
    if punish_role is None:
        return False, [], "No hay rol Condenado configurado; usa `/honeypot setup rol_castigo` para elegirlo."
    problem = hp_role_problem(punish_role, guild)
    if problem:
        return False, [], f"El rol Condenado {problem}."

    source = preserve_role_ids if preserve_role_ids is not None else [r.id for r in member.roles]
    excluded = {punish_role.id}
    saved_ids = []
    for rid in source:
        role = guild.get_role(rid)
        # Solo se guardan roles que el Heraldo puede devolver (no @everyone ni gestionados).
        if rid in excluded or role is None or role.is_default() or role.managed or not role.is_assignable():
            continue
        saved_ids.append(rid)

    removed = [
        r for r in member.roles
        if r.id not in excluded and r.is_assignable() and not r.managed
    ]
    managed = [r for r in member.roles if not r.is_default()
               and (r.managed or not r.is_assignable()) and r.id != punish_role.id]
    if save_snapshot:
        # Persistir antes de la llamada remota: una interrupción después de retirar
        # roles no debe destruir la única copia disponible para recuperarlos.
        hp_save_punished(member.guild.id, member.id, saved_ids)
    try:
        await member.edit(roles=managed + [punish_role], reason=reason)
    except discord.Forbidden:
        return False, [], "Faltan permisos para cambiar roles o la jerarquía del Heraldo no alcanza al usuario."
    except discord.HTTPException as e:
        return False, [], f"Error al cambiar roles: `{e}`"

    return True, saved_ids, f"{len(removed)} rol(es) asignable(s) retirado(s); Tentad@ y Sin Verificar retirados."


async def condemn_member(
    member: discord.Member,
    *,
    reason: str,
    duration_minutes: int | None,
    purge_spec: tuple[str, int] | None,
    origin: str,
    applied_by: discord.abc.User | None,
    preserve_role_ids: list[int] | None = None,
    source_message_url: str | None = None,
    source_channel_id: int | None = None,
    send_dm: bool = True,
    announce: bool = True,
) -> tuple[bool, str]:
    """Motor único de condena. Lo usan honeypot, comando, reacción, rol manual y raid protection."""
    if member.bot:
        return False, "Los bots no se condenan."
    reason = HERALDO_TEST_REASON if heraldo_is_test() else (reason or "").strip()
    if not reason:
        automatic_reasons = {
            "raid": "Protección RAID: ingreso detectado durante un patrón de incursión masiva.",
            "honeypot": "Honeypot: el miembro activó un canal trampa de seguridad.",
            "role": "El rol Condenado fue otorgado manualmente y activó el motor de condenas.",
            "reaction": "Condena aplicada mediante la reacción de moderación.",
        }
        reason = automatic_reasons.get(origin, "Advertencia: Condena automática de seguridad de El Heraldo.")
    if (member.guild.id, member.id) in _condemn_inflight:
        return False, "Ya hay una condena en proceso para este miembro."
    protection = condemnation_protection_reason(member)
    if protection:
        return False, f"No se puede condenar: {protection}."

    _condemn_inflight.add((member.guild.id, member.id))
    try:
        return await _condemn_member_inner(
            member, reason=reason, duration_minutes=duration_minutes, purge_spec=purge_spec,
            origin=origin, applied_by=applied_by, preserve_role_ids=preserve_role_ids,
            source_message_url=source_message_url, source_channel_id=source_channel_id, send_dm=send_dm, announce=announce,
        )
    finally:
        _condemn_inflight.discard((member.guild.id, member.id))


async def _condemn_member_inner(
    member: discord.Member,
    *,
    reason: str,
    duration_minutes: int | None,
    purge_spec: tuple[str, int] | None,
    origin: str,
    applied_by: discord.abc.User | None,
    preserve_role_ids: list[int] | None,
    source_message_url: str | None,
    source_channel_id: int | None,
    send_dm: bool,
    announce: bool,
) -> tuple[bool, str]:
    existing = condemnation_get(member.guild.id, member.id)
    active_role_id = condemnation_role_id(existing, member.guild.id)
    snapshot = preserve_role_ids
    if snapshot is None and existing is None:
        snapshot = [r.id for r in member.roles]

    _condemn_sync_busy.add((member.guild.id, member.id))
    try:
        ok, saved_ids, role_note = await condemnation_sync_roles(
            member, preserve_role_ids=snapshot, save_snapshot=(existing is None),
            reason=f"{reason[:400]} — {condemnation_origin_label(origin)}",
            role_id=active_role_id,
        )
    finally:
        _condemn_sync_busy.discard((member.guild.id, member.id))
    if not ok:
        return False, role_note
    removed_role_ids = [
        rid for rid in (snapshot or [])
        if rid != active_role_id
        and (member.guild.get_role(rid) is not None)
        and member.guild.get_role(rid).is_assignable()
        and not member.guild.get_role(rid).managed
    ]

    if existing is not None and existing["thread_id"]:
        await condemnation_close_private_thread(member.guild, int(existing["thread_id"]))
    if existing is None:
        condemnation_save(member.id, member.guild.id, active_role_id, saved_ids, reason[:1000], duration_minutes, origin,
                           applied_by.id if applied_by else None)
    else:
        # Una nueva orden sobre una condena activa actualiza motivo/duración/origen, pero NO pisa la fotografía original de roles.
        condemnation_save(member.id, member.guild.id, active_role_id, condemnation_parse_role_ids(existing["role_ids"]),
                           reason[:1000], duration_minutes, origin, applied_by.id if applied_by else None,
                           condemned_at=datetime.fromisoformat(existing["condemned_at"]))

    db_clear_tentado(member.guild.id, member.id)
    db_clear_sin_verificado(member.guild.id, member.id)
    db_clear_verify_pending(member.guild.id, member.id)
    db_zero_week_messages(member.guild.id, member.id)

    if origin == "honeypot":
        evidence_url, evidence_text = None, None
    else:
        evidence_url, evidence_text = await condemnation_archive_evidence(
            member.guild, member, source_message_url=source_message_url,
            reason=reason, applied_by=applied_by,
        )

    # Ambos destinos reciben la misma resolución y el mismo Moderation Case.
    condemnation_when = datetime.now(timezone.utc)
    linked_case_number: int | None = None
    if send_dm or announce:
        try:
            verified = (
                None if origin == "honeypot"
                else evidence_text or await moderation_verified_proof(member.guild, source_message_url)
            )
            linked_case_number = moderation_case_create(
                member.guild.id, "CONDEMN", member.id, reason,
                duration_minutes=duration_minutes,
                author_id=applied_by.id if applied_by else None,
                proof=evidence_url or source_message_url,
                verified_proof=verified,
            )
            conn = db_connect()
            conn.execute(
                "UPDATE guild_cases SET moderation_case_number = ? WHERE guild_id = ? AND user_id = ?",
                (linked_case_number, member.guild.id, member.id),
            )
            conn.close()
        except Exception:
            traceback.print_exc()
    elif existing is not None and "moderation_case_number" in existing.keys() and existing["moderation_case_number"]:
        linked_case_number = int(existing["moderation_case_number"])

    condemnation_case = condemnation_case_id(member, condemnation_when, linked_case_number)
    dm_ok = await condemnation_send_dm(
        member, reason, duration_minutes, origin, applied_by,
        source_message_url=source_message_url, source_channel_id=source_channel_id,
        removed_role_ids=removed_role_ids, when=condemnation_when, case_id=condemnation_case,
        evidence_url=evidence_url, evidence_text=evidence_text,
    ) if send_dm else None
    if announce:
        announcement_message_id = await condemnation_announce(
            member.guild, member, reason, duration_minutes, origin, applied_by,
            source_message_url=source_message_url, source_channel_id=source_channel_id,
            removed_role_ids=removed_role_ids, when=condemnation_when, case_id=condemnation_case,
            evidence_url=evidence_url, evidence_text=evidence_text,
        )
        if announcement_message_id:
            condemnation_thread_mark_requested(member.guild.id, member.id, announcement_message_id)
            thread_ready = await condemnation_ensure_private_thread(
                member.guild, member, announcement_message_id, condemnation_case,
            )
            if not thread_ready:
                role_note += "; hilo privado pendiente: revisa los permisos del canal de condenados"
    if origin != "honeypot" and purge_spec and purge_spec[0] != "none" and source_message_url and not evidence_url:
        role_note += "; purga cancelada: no se pudo conservar íntegramente la evidencia en un canal privado"
        purge_spec = None
    purge_scope: str | None = None
    purge_after: datetime | None = None
    purge_limit: int | None = None
    if purge_spec and purge_spec[0] != "none":
        kind, value = purge_spec
        purge_scope = format_purge_spec(kind, value)
        purge_after = datetime.now(timezone.utc) - timedelta(minutes=value) if kind == "time" else None
        purge_limit = value if kind == "count" else None

    log_description = (
        f"{member.mention} (`{member.id}`)\n"
        f"Motivo: {reason}\n"
        f"Duración: {format_duration(duration_minutes) if duration_minutes else 'Indefinida'}\n"
        f"Origen: {condemnation_origin_label(origin)}\n"
        f"Aplicó: {applied_by.mention if applied_by else 'El Heraldo'}\n"
        f"{role_note}\n"
        f"DM: {'enviado' if dm_ok else 'Advertencia: no enviado' if dm_ok is not None else '—'}"
    )
    log_message: discord.Message | None = None
    # La tarjeta del canal de condenas es el aviso principal si Logs usa el mismo canal.
    if get_log_channel_id(member.guild.id) != condemnation_channel_id(member.guild.id):
        log_message = await log_embed(
            member.guild, "Condena aplicada",
            log_description + (f"\nPurga: {purge_scope} (en proceso)." if purge_scope else ""),
            discord.Color.dark_red(),
        )
    if purge_scope is not None:
        asyncio.create_task(
            _complete_condemnation_purge_log(
                member.guild, member, scope_text=purge_scope,
                requested_by=f"Condena ({condemnation_origin_label(origin)})",
                after=purge_after, limit=purge_limit,
                base_description=log_description, log_message=log_message,
                **({"purge_origin": "honeypot"} if origin == "honeypot" else {}),
            )
        )
    return True, role_note + ("; DM enviado" if dm_ok else "; DM no disponible" if dm_ok is not None else "")


async def release_condemned_member(
    member: discord.Member, *, released_by: discord.abc.User | None = None,
    automatic: bool = False, pardon: bool = False,
    announcement_message: discord.Message | None = None,
) -> tuple[bool, str]:
    key = (member.guild.id, member.id)
    if key in _condemn_inflight:
        return False, "Ya hay una operación de condena en proceso para este miembro."
    _condemn_inflight.add(key)
    try:
        return await _release_condemned_member_inner(
            member, released_by=released_by, automatic=automatic, pardon=pardon,
            announcement_message=announcement_message)
    finally:
        _condemn_inflight.discard(key)


async def _release_condemned_member_inner(
    member: discord.Member, *, released_by: discord.abc.User | None = None,
    automatic: bool = False, pardon: bool = False,
    announcement_message: discord.Message | None = None,
) -> tuple[bool, str]:
    row = condemnation_get(member.guild.id, member.id)
    punish_role = member.guild.get_role(condemnation_role_id(row, member.guild.id))
    if row is None and not (punish_role and punish_role in member.roles):
        return False, "Ese miembro no tiene una condena activa."

    saved = condemnation_parse_role_ids(row["role_ids"]) if row else (hp_get_punished(member.guild.id, member.id) or [])
    restore: list[discord.Role] = []
    missing_role_ids: list[int] = []
    for rid in saved:
        role = member.guild.get_role(rid)
        if role is not None and role.is_assignable() and not role.managed:
            restore.append(role)
        else:
            missing_role_ids.append(rid)
    lost = len(missing_role_ids)

    current = [
        r for r in member.roles
        if not r.is_default() and (punish_role is None or r.id != punish_role.id)
    ]
    new_roles = list({r.id: r for r in current + restore}.values())
    _condemn_sync_busy.add((member.guild.id, member.id))
    try:
        await member.edit(roles=new_roles, reason=("Condena expirada" if automatic else f"Liberado por {released_by}"))
    except discord.HTTPException as e:
        return False, f"No pude cambiar sus roles: `{e}`"
    finally:
        _condemn_sync_busy.discard((member.guild.id, member.id))

    # La liberación ya tuvo éxito en Discord. Conservar los roles irrecuperables
    # aunque se cierre el expediente, para permitir un reintento administrativo.
    previous_pending = condemnation_pending_roles_get(member.guild.id, member.id)
    assigned_ids = {role.id for role in new_roles}
    new_pending = sorted((set(previous_pending) | set(missing_role_ids)) - assigned_ids)
    condemnation_pending_roles_set(member.guild.id, member.id, new_pending)

    linked_case_number = (
        int(row["moderation_case_number"])
        if row is not None and "moderation_case_number" in row.keys() and row["moderation_case_number"] is not None
        else None
    )
    if pardon and row is not None and released_by is not None:
        condemnation_deactivate(member.guild.id, member.id, resolution="pardoned", resolved_by=released_by.id)
        if linked_case_number is not None:
            moderation_case_close(
                member.guild.id, linked_case_number,
                closed_by=released_by.id, resolution="Perdonado",
            )
    else:
        condemnation_deactivate(member.guild.id, member.id, resolution="expired" if automatic else None)
        if automatic and linked_case_number is not None:
            moderation_case_close(
                member.guild.id, linked_case_number,
                closed_by=None, resolution="Expirado automáticamente",
            )
    db_clear_tentado(member.guild.id, member.id)
    db_clear_sin_verificado(member.guild.id, member.id)
    db_clear_verify_pending(member.guild.id, member.id)
    # Resolver la tarjeta principal ANTES de archivar el hilo o enviar avisos
    # secundarios: un fallo de esos pasos no debe dejar controles antiguos visibles.
    card_ok: bool | None = None
    if pardon and row is not None and released_by is not None:
        card_ok = await condemnation_update_pardoned_card(
            member, row, released_by, len(restore), lost, message=announcement_message,
        )
        if not card_ok:
            # Si Discord rechazó la edición completa, intentar al menos retirar
            # los controles activos sin crear publicaciones ni sanciones nuevas.
            await condemnation_mark_closed_card(
                member.guild, row, "Condena perdonada — actualización visual pendiente",
            )
    # La condena ya se levantó. El hilo permanece como expediente archivado.
    if row is not None and row["thread_id"]:
        await condemnation_close_private_thread(member.guild, int(row["thread_id"]))
    if row is not None and not pardon:
        await condemnation_mark_closed_card(
            member.guild, row, "Condena expirada" if automatic else "Condena levantada",
        )

    # Si entre los roles originales estaban los de verificación, vuelven a su flujo normal
    # desde cero; mientras la condena estuvo activa nunca corrió ninguna evaluación.
    restored_ids = {r.id for r in restore}
    if (orientation_enabled(member.guild.id) and personality_required(member.guild.id)
            and not verification_is_exempt(member)
            and get_tentado_role_id(member.guild.id) in restored_ids):
        now = datetime.now(timezone.utc)
        db_set_tentado(member.guild.id, member.id, now)
        asyncio.create_task(schedule_check(member.guild.id, member.id, now))
    if (verify_enabled(member.guild.id)
            and not verification_is_exempt(member)
            and get_sin_verificado_role_id(member.guild.id) in restored_ids
            and get_verify_role_id(member.guild.id) not in {r.id for r in member.roles}
            and not ({r.id for r in member.roles} & get_eval_role_ids(member.guild.id))):
        # Un rol Sin Verificar restaurado recibe el plazo principal completo.
        now = datetime.now(timezone.utc)
        db_set_verify_pending(member.guild.id, member.id, now)
        asyncio.create_task(schedule_verify_timeout(member.guild.id, member.id, now))

    pending_role_details = ", ".join(str(rid) for rid in missing_role_ids[:15])
    if lost > 15:
        pending_role_details += f" y {lost - 15} más"
    text = f"{len(restore)} rol(es) restaurado(s)" + (f"; {lost} no se pudieron restaurar" if lost else "")
    if pardon and row is not None and released_by is not None:
        condemned_at = datetime.fromisoformat(row["condemned_at"])
        case_id = condemnation_case_id(member, condemned_at, linked_case_number)
        dm_ok = await condemnation_send_pardon_dm(member, row, released_by, len(restore), lost)
        await log_embed(
            member.guild, "Condena perdonada",
            f"Expediente: {case_id}\nUsuario: {member.mention} ({member.id})\n"
            f"Motivo original: {row['reason']}\nOrigen: {condemnation_origin_label(row['origin'])}\n"
            f"Perdonó: {released_by.mention}\nRoles: {text}\n"
            f"Roles sin restaurar (IDs): {pending_role_details if lost else 'Ninguno'}\n"
            f"Tarjeta original: {'actualizada' if card_ok else 'Advertencia: actualización pendiente'}\n"
            f"DM: {'enviado' if dm_ok else 'Advertencia: no enviado'}",
            discord.Color.green(),
        )
        return True, text + (
            "; tarjeta original actualizada" if card_ok else "; actualización de tarjeta pendiente"
        ) + ("; DM de perdón enviado" if dm_ok else "; DM de perdón no disponible")
    await log_embed(member.guild, "Condena levantada", f"{member.mention} — {text}. Por: {released_by.mention if released_by else 'El Heraldo'}.", discord.Color.green())
    return True, text


async def check_expired_condemnations() -> None:
    now = datetime.now(timezone.utc)
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    rows = conn.execute(
        "SELECT * FROM guild_cases WHERE active = 1 AND expires_at IS NOT NULL AND expires_at <= ?",
        (now.isoformat(),),
    ).fetchall()
    conn.close()
    for row in rows:
        guild_id = int(row["guild_id"])
        user_id = int(row["user_id"])
        guild = bot.get_guild(guild_id)
        if guild is None:
            # La indisponibilidad temporal del servidor no resuelve el expediente.
            continue
        member = guild.get_member(user_id)
        if member is None:
            try:
                member = await guild.fetch_member(user_id)
            except discord.NotFound:
                pass
            except discord.HTTPException:
                continue  # Reintentar sin perder la fotografía de roles.
        if member is not None:
            await release_condemned_member(member, automatic=True)
        else:
            condemnation_deactivate(guild_id, user_id, resolution="expired")
            if row["thread_id"]:
                await condemnation_close_private_thread(guild, int(row["thread_id"]))
            await condemnation_mark_closed_card(guild, row, "Condena expirada")
            linked_case = (
                int(row["moderation_case_number"])
                if "moderation_case_number" in row.keys() and row["moderation_case_number"] is not None
                else None
            )
            if linked_case is not None:
                moderation_case_close(
                    guild_id, linked_case, closed_by=None, resolution="Expirado automáticamente"
                )


async def condemnation_reconcile(guild: discord.Guild) -> None:
    """Al arrancar, el rol Condenado vuelve a ser la fuente de verdad por si cambió con el bot apagado:
    - condena activa pero sin el rol: si el miembro reingresó después, se le reaplica; si no, se le libera.
    - rol Condenado sin condena registrada: se condena como si lo hubieran puesto a mano."""
    for row in condemnation_list(guild.id):
        role = guild.get_role(condemnation_role_id(row, guild.id))
        member = guild.get_member(row["user_id"])
        if role is None or member is None or role in member.roles:
            continue
        condemned_at = datetime.fromisoformat(row["condemned_at"])
        if member.joined_at and member.joined_at > condemned_at:
            _condemn_sync_busy.add((member.guild.id, member.id))
            try:
                await condemnation_sync_roles(member, save_snapshot=False, reason="Condena activa reaplicada al arrancar", role_id=role.id)
            finally:
                _condemn_sync_busy.discard((member.guild.id, member.id))
        else:
            await release_condemned_member(member, automatic=False)
        await asyncio.sleep(1)

    punish_role = guild.get_role(hp_punish_role_id(guild.id))
    if punish_role is None:
        return
    for member in list(punish_role.members):
        if member.bot or condemnation_get(member.guild.id, member.id) is not None:
            continue
        await condemn_member(
            member, reason="El rol Condenado fue otorgado manualmente (detectado al arrancar).",
            duration_minutes=condemnation_default_duration_minutes(guild.id), purge_spec=None, origin="role", applied_by=None,
            send_dm=True, announce=True,
        )
        await asyncio.sleep(1)



async def moderation_expire_mute_safely(
    guild: discord.Guild, member: discord.Member | None, row: sqlite3.Row, now: datetime,
) -> str:
    """Decidir si el MUTE vencido puede cerrarse sin retirar otro aislamiento."""
    conn = None
    try:
        conn = db_connect()
        newer = conn.execute(
            "SELECT 1 FROM moderation_cases WHERE guild_id=? AND user_id=? "
            "AND type='MUTE' AND open=1 AND case_number>? LIMIT 1",
            (guild.id, int(row["user_id"]), int(row["case_number"])),
        ).fetchone()
    except sqlite3.Error:
        traceback.print_exc()
        return "pending"  # No actuar si SQLite impide conocer sanciones posteriores.
    finally:
        if conn is not None:
            conn.close()
    if newer is not None:
        return "superseded"
    if member is None:
        return "expired"  # Ya no forma parte del servidor.
    try:
        latest = await guild.fetch_member(member.id)
    except discord.NotFound:
        return "expired"
    except discord.HTTPException:
        traceback.print_exc()
        return "pending"
    until = latest.timed_out_until
    expires = datetime.fromisoformat(row["expires_at"])
    if until is None or until <= now:
        return "expired"  # Discord ya levantó el aislamiento.
    if until > expires + timedelta(seconds=30):
        return "different"  # Timeout posterior, posiblemente manual: no levantarlo.
    try:
        await latest.timeout(
            None,
            reason=f"Expiró el expediente {moderation_case_code(row['case_number'], guild.id)}",
        )
    except discord.HTTPException:
        traceback.print_exc()
        return "pending"  # Sin confirmación de Discord, no cerrar el expediente.
    return "expired"


@tasks.loop(minutes=1)
async def moderation_case_expiry_loop() -> None:
    now = datetime.now(timezone.utc)
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    rows = conn.execute("SELECT * FROM moderation_cases WHERE open = 1 AND expires_at IS NOT NULL").fetchall()
    conn.close()
    for row in rows:
        try:
            expires = datetime.fromisoformat(row["expires_at"])
            guild = bot.get_guild(int(row["guild_id"]))
            if guild is None:
                continue
            member = guild.get_member(int(row["user_id"]))
            case_type = str(row["type"])
            if case_type == "MUTE" and member is not None and expires > now + timedelta(days=27):
                current = member.timed_out_until
                if current is None or current < now + timedelta(days=27):
                    await member.timeout(min(expires, now + timedelta(days=28)), reason=f"Extensión del expediente {moderation_case_code(row['case_number'], int(row['guild_id']))}")
            if expires > now:
                continue
            if case_type == "MUTE":
                outcome = await moderation_expire_mute_safely(guild, member, row, now)
                if outcome == "pending":
                    continue
                if outcome in {"superseded", "different"}:
                    moderation_case_close(
                        guild.id, int(row["case_number"]), closed_by=None,
                        resolution=("Sustituido por aislamiento posterior" if outcome == "superseded"
                                    else "Aislamiento modificado; requiere revisión administrativa"),
                    )
                    continue
            elif case_type == "BAN":
                # Un expediente antiguo nunca debe levantar otro baneo posterior.
                conn = db_connect()
                try:
                    newer = conn.execute(
                        "SELECT 1 FROM moderation_cases WHERE guild_id=? AND user_id=? "
                        "AND type='BAN' AND open=1 AND case_number>? LIMIT 1",
                        (guild.id, int(row["user_id"]), int(row["case_number"])),
                    ).fetchone()
                except sqlite3.Error:
                    traceback.print_exc()
                    continue  # Ante duda, no levantar sanciones.
                finally:
                    conn.close()
                if newer is not None:
                    moderation_case_close(
                        guild.id, int(row["case_number"]), closed_by=None,
                        resolution="Sustituido por un baneo posterior",
                    )
                    continue
                try:
                    current = await guild.fetch_ban(discord.Object(id=int(row["user_id"])))
                except discord.NotFound:
                    current = None  # El baneo ya fue retirado por otra vía.
                except discord.HTTPException:
                    traceback.print_exc()
                    continue  # Sin estado confirmado, mantener expediente abierto.
                if (current is not None and heraldo_is_test()
                        and current.reason and current.reason != row["reason"]):
                    moderation_case_close(
                        guild.id, int(row["case_number"]), closed_by=None,
                        resolution="Baneo diferente al expediente vencido; revisión administrativa",
                    )
                    continue
                if current is not None:
                    try:
                        await guild.unban(
                            discord.Object(id=int(row["user_id"])),
                            reason=f"Expiró el expediente {moderation_case_code(row['case_number'], int(row['guild_id']))}",
                        )
                    except discord.NotFound:
                        pass
                    except discord.HTTPException:
                        traceback.print_exc()
                        continue  # Reintentar desbaneo; no cerrar expediente antes de completarlo.
            moderation_case_close(guild.id, int(row["case_number"]), closed_by=None, resolution="Expirado automáticamente")
        except Exception:
            traceback.print_exc()

@tasks.loop(minutes=1)
async def condemnation_expiry_loop() -> None:
    try:
        await check_expired_condemnations()
    except Exception:
        traceback.print_exc()


async def hp_punish(member: discord.Member, action: str, source_channel_id: int | None = None) -> tuple[bool, str]:
    guild = member.guild
    reason = "Honeypot: escribió en un canal trampa"
    if action == "log":
        return True, "Solo registrado (sin castigo)"
    me = guild.me
    if me is None:
        return False, "No se pudo comprobar la identidad del bot en el servidor"
    if member.id == guild.owner_id:
        return False, "No se puede sancionar al propietario del servidor"
    if member.top_role >= me.top_role:
        return False, "Su rol es igual o superior al del bot (jerarquía de roles)"
    if action in {"kick", "ban"}:
        if getattr(member, "bot", False):
            return False, "Las sanciones automáticas de Honeypot no se aplican a otros bots"
        problem = hp_sanction_permission_problem(guild, action)
        if problem:
            return False, problem

    try:
        if action == "timeout":
            minutes = hp_timeout_minutes(member.guild.id)
            await member.timeout(timedelta(minutes=minutes), reason=reason)
            purge_note = hp_start_purge(member)
            return True, f"Aislado {format_duration(minutes)}" + (f"; {purge_note}" if purge_note else "")
        if action == "role":
            purge_spec = hp_purge_spec(member.guild.id)
            return await condemn_member(
                member,
                reason="Honeypot: escribió en un canal trampa",
                duration_minutes=condemnation_default_duration_minutes(member.guild.id),
                purge_spec=purge_spec,
                origin="honeypot",
                applied_by=None,
                source_channel_id=source_channel_id,
                send_dm=True,
                announce=True,
            )
        if action in {"kick", "ban"}:
            # Reutilizar las mismas rutas de Discord y el aviso previo de Test.
            # Nunca aplicar la purga de condena a una expulsión ni a un baneo.
            duration = None
            purge_note = ""
            if action == "kick":
                await heraldo_kick(member, reason=reason)
                # Nunca borrar por el mecanismo de expulsión de Discord.
                # La purga asíncrona utiliza delete_with_evidence por mensaje.
                try:
                    purge_note = hp_start_kick_purge(member)
                except Exception:
                    traceback.print_exc()
                    purge_note = "purga no iniciada; requiere revisión"
            else:
                duration = await heraldo_ban(
                    member, reason=reason, delete_message_seconds=0,
                    duration_minutes=hp_ban_override_minutes(guild.id), record_case=False,
                )
            # Discord ya confirmó la medida. Un fallo posterior de SQLite
            # nunca debe volver a ejecutar kick/ban; informar la falta del caso.
            try:
                case_number = moderation_case_create(
                    guild.id, action.upper(), member.id, reason,
                    duration_minutes=duration, author_id=None,
                    moderator_notes=(
                        "Medida automática de Honeypot."
                        + (f" Canal de origen: {source_channel_id}." if source_channel_id else "")
                    ),
                )
                code = moderation_case_code(case_number, guild.id)
                return True, (
                    f"{'Expulsado' if action == 'kick' else 'Baneado'} · "
                    f"Expediente {code}"
                    + (f" · Duración {format_duration(duration)}" if duration else "")
                    + (f" · {purge_note}" if purge_note else "")
                )
            except Exception:
                traceback.print_exc()
                return True, (
                    f"{'Expulsión' if action == 'kick' else 'Baneo'} aplicado, "
                    "pero no se pudo registrar el expediente. Requiere revisión administrativa."
                    + (f" {purge_note}" if purge_note else "")
                )
    except discord.Forbidden:
        return False, "Faltan permisos del bot o jerarquía para aplicar la medida"
    except discord.HTTPException as exc:
        return False, f"Discord rechazó la medida: `{exc}`"
    return False, f"Acción desconocida: {action}"


async def hp_report(guild: discord.Guild, member: discord.Member, channel: discord.abc.GuildChannel,
                    action: str, success: bool, note: str) -> None:
    log_channel = guild.get_channel(get_log_channel_id(guild.id))
    if log_channel is None:
        return
    embed = discord.Embed(
        title="Honeypot: miembro atrapado" if success else "Honeypot: castigo FALLIDO",
        color=discord.Color.orange() if success else discord.Color.red(),
        timestamp=datetime.now(timezone.utc),
    )
    embed.add_field(name="Usuario", value=f"{member.mention} (`{member}` · {member.id})", inline=False)
    embed.add_field(name="Cuenta creada", value=discord.utils.format_dt(member.created_at, "R"), inline=True)
    embed.add_field(
        name="Se unió",
        value=discord.utils.format_dt(member.joined_at, "R") if member.joined_at else "—",
        inline=True,
    )
    embed.add_field(name="Canal", value=channel.mention, inline=True)
    embed.add_field(name="Acción", value=f"{HONEYPOT_ACTION_LABELS.get(action, action)} — {note}", inline=False)
    embed.set_thumbnail(url=member.display_avatar.url)
    role_id = hp_ping_role_id(guild.id)
    try:
        await log_channel.send(
            content=f"<@&{role_id}>" if role_id else None,
            embed=embed,
            allowed_mentions=discord.AllowedMentions(roles=True, users=False, everyone=False),
        )
    except discord.HTTPException as e:
        print(f"Honeypot: no pude reportar en el canal de logs: {e}")


async def hp_handle_trigger(message: discord.Message, member: discord.Member) -> None:
    guild = member.guild
    action = hp_action(guild.id)

    # Comprobar primero la protección antifallos: el mensaje que activa
    # la pausa debe permanecer intacto, sin borrado ni sanción.
    # Protección contra fallos: varios miembros veteranos atrapados en pocos minutos.
    now = datetime.now(timezone.utc)
    if member.joined_at and now - member.joined_at > HONEYPOT_MISFIRE_MEMBER_AGE:
        _hp_veteran_hits.append((now, guild.id, member.id))
    _hp_veteran_hits[:] = [
        (t, guild_id, user_id)
        for t, guild_id, user_id in _hp_veteran_hits
        if now - t <= HONEYPOT_MISFIRE_WINDOW
    ]
    if len({user_id for _, guild_id, user_id in _hp_veteran_hits if guild_id == guild.id}) >= HONEYPOT_MISFIRE_THRESHOLD:
        hp_setting_set(guild.id, "honeypot_paused", "1")
        _hp_veteran_hits[:] = [
            entry for entry in _hp_veteran_hits if entry[1] != guild.id
        ]
        await log_embed(
            guild, "Honeypot pausado — protección contra fallos",
            f"{HONEYPOT_MISFIRE_THRESHOLD} miembros con más de 30 días en el servidor escribieron "
            f"en canales trampa durante los últimos 5 minutos. La configuración podría ser incorrecta.\n"
            f"Se conservó el mensaje de {member.mention} en {message.channel.mention} "
            f"y no se aplicó ninguna sanción a este miembro.\n"
            "Revise los canales trampa con `/honeypot setup` y reactive la protección "
            "con `/honeypot resume` tras corregir la configuración.",
            discord.Color.red(),
        )
        return

    # Honeypot solo elimina el mensaje del autor detectado, sin archivarlo.
    try:
        await delete_honeypot_message(message.channel, message.id, member.id)
    except discord.HTTPException:
        pass

    success, note = await hp_punish(member, action, message.channel.id)
    hp_log_trigger(member, message.channel.id, action, success, note)
    await hp_report(guild, member, message.channel, action, success, note)


@bot.listen("on_message")
async def honeypot_listener(message: discord.Message) -> None:
    if message.guild is None or message.webhook_id is not None or message.author.bot:
        return  # DMs, webhooks y otros bots se ignoran (tus integraciones están a salvo)
    if not honeypot_enabled(message.guild.id) or honeypot_paused(message.guild.id):
        return
    if message.channel.id not in hp_trap_ids(message.guild.id):
        return
    member = message.author
    if not isinstance(member, discord.Member) or hp_is_exempt(member):
        return
    punish_id = hp_punish_role_id(message.guild.id)
    if punish_id and any(r.id == punish_id for r in member.roles):
        try:
            await delete_honeypot_message(message.channel, message.id, member.id)
        except discord.HTTPException:
            pass
        return
    busy_key = (message.guild.id, member.id)
    if busy_key in _hp_busy:
        try:
            await delete_honeypot_message(message.channel, message.id, member.id)
        except discord.HTTPException:
            pass
        return
    _hp_busy.add(busy_key)
    try:
        await hp_handle_trigger(message, member)
    except Exception:
        traceback.print_exc()
    finally:
        _hp_busy.discard(busy_key)


@bot.listen("on_guild_channel_delete")
async def honeypot_channel_deleted(channel: discord.abc.GuildChannel) -> None:
    if channel.id not in hp_traps(channel.guild.id):
        return
    hp_remove_trap(channel.guild.id, channel.id)
    await log_embed(
        channel.guild, "Canal trampa eliminado",
        f"Se borró `#{channel.name}` en Discord y se quitó del honeypot automáticamente. "
        f"Quedan {len(hp_traps(channel.guild.id))} canal(es) trampa.",
        discord.Color.orange(),
    )



