@bot.listen("on_raw_reaction_add")
async def moderation_reaction_add(payload: discord.RawReactionActionEvent) -> None:
    if payload.guild_id is None or payload.user_id == getattr(bot.user, "id", None):
        return

    guild = bot.get_guild(payload.guild_id)
    if guild is None:
        return
    actor = payload.member or guild.get_member(payload.user_id)
    if actor is None:
        try:
            actor = await guild.fetch_member(payload.user_id)
        except discord.HTTPException:
            return
    if actor.bot:
        return

    emoji = str(payload.emoji)
    condemn_emoji = get_condemnation_emoji(guild.id)
    is_condemn = _moderation_emoji_key(emoji) == _moderation_emoji_key(condemn_emoji)
    if is_condemn and not moderation_report_punishment_enabled(guild.id, "condemn"):
        return
    report_rule = moderation_report_rule_for_emoji(guild.id, emoji)
    # Dos acciones configuradas con el mismo emoji no deben ejecutarse juntas.
    # En caso de conflicto se falla cerrado, sin aplicar condena ni advertencia.
    if is_condemn and report_rule is not None:
        return
    report_type = str(report_rule["label"]) if report_rule else None
    if not is_condemn and report_rule is None:
        return
    # Advertir no es una encuesta pública: solo puede iniciarlo el personal autorizado.
    if report_rule and report_rule.get("action") == "warn" and not moderation_can_warn(actor):
        return

    channel = guild.get_channel_or_thread(payload.channel_id)
    if channel is None or not hasattr(channel, "fetch_message"):
        return
    try:
        message = await channel.fetch_message(payload.message_id)
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        return
    # fetch_message puede devolver User sin el objeto Member; no descartar por ello
    # una reacción válida. Resolver el miembro real antes de evaluar sus roles.
    target = message.author
    if not isinstance(target, discord.Member):
        target = guild.get_member(message.author.id)
        if target is None:
            try:
                target = await guild.fetch_member(message.author.id)
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                return
    if target.bot or target.id == actor.id:
        return

    if report_rule and report_rule.get("action") == "warn":
        # El relevo de reacción debe ser viable antes de abrir un expediente WARN.
        me = guild.me
        perms = channel.permissions_for(me) if me and hasattr(channel, "permissions_for") else None
        if perms is None or not (
            perms.view_channel and perms.read_message_history
            and perms.add_reactions and perms.manage_messages
        ):
            await log_embed(
                guild, "Advertencia por reacción no aplicada",
                "El Heraldo necesita Ver canal, Leer historial, Añadir reacciones "
                "y Gestionar mensajes para sustituir la reacción del moderador.",
                discord.Color.orange(),
            )
            return

    if is_condemn:
        if not moderation_can_condemn(actor, target) or target.id == actor.id:
            return
        if condemnation_get(guild.id, target.id) is not None:
            return
        pending_key = (guild.id, message.id)
        if pending_key in _reaction_condemn_pending:
            return
        _reaction_condemn_pending.add(pending_key)
        view = ReactionCondemnReasonView(
            guild_id=guild.id,
            actor_id=actor.id,
            channel_id=message.channel.id,
            message_id=message.id,
            target_id=target.id,
            pending_key=pending_key,
        )
        try:
            prompt = await actor.send(
                f"**Condenar por reacción**\n"
                f"Servidor: **{guild.name}**\n"
                f"Miembro: **{target}** (`{target.id}`)\n"
                f"Canal: {message.channel.mention}\n"
                f"[Abrir mensaje]({message.jump_url})\n\n"
                "La razón es obligatoria. Pulsa **Indicar razón** para continuar.",
                view=view,
                allowed_mentions=discord.AllowedMentions.none(),
            )
            view.prompt_message = prompt
        except discord.HTTPException:
            _reaction_condemn_pending.discard(pending_key)
        return

    # Si no hay un destino exclusivo, reutilizar los registros del servidor.
    # Una configuración incompleta no debe desactivar silenciosamente las reglas.
    report_channel_id = moderation_report_channel_id(guild.id) or get_log_channel_id(guild.id)
    report_channel = guild.get_channel(report_channel_id)
    if not isinstance(report_channel, discord.TextChannel):
        return

    now = time.monotonic()
    dedupe_key = (guild.id, message.id, actor.id, _moderation_emoji_key(emoji))
    last = _moderation_report_dedupe.get(dedupe_key)
    if last is not None and now - last < 3600:
        return
    _moderation_report_dedupe[dedupe_key] = now
    emoji_key = _moderation_emoji_key(emoji)
    reporter_count, action_executed = moderation_report_record(
        guild.id, message.id, target.id, emoji_key, actor.id
    )
    threshold = int(report_rule.get("threshold", 1)) if report_rule else 1
    if len(_moderation_report_dedupe) > 5000:
        cutoff = now - 3600
        for key, stamp in list(_moderation_report_dedupe.items()):
            if stamp < cutoff:
                _moderation_report_dedupe.pop(key, None)

    # Publicar únicamente el primer aviso y el resultado final del umbral.
    # No emitir además un segundo embed de logs por la misma acción.
    if action_executed or (1 < reporter_count < threshold):
        return

    action_result: tuple[bool, str] | None = None
    if report_rule and reporter_count >= threshold and not action_executed:
        action_key = (guild.id, message.id, emoji_key)
        if action_key in _moderation_report_pending:
            return
        _moderation_report_pending.add(action_key)
        try:
            action_result = await execute_moderation_report_action(
                guild, target, message, report_rule, reporter_count,
                actor=actor if report_rule.get("action") == "warn" else None,
            )
            if action_result[0]:
                moderation_report_mark_executed(guild.id, message.id, target.id, emoji_key)
                if report_rule.get("action") == "warn":
                    # Solo tras registrar el WARN: el bot añade su reacción y
                    # elimina la del moderador; el mensaje original no se toca.
                    # Ante error de permisos, el expediente se conserva.
                    try:
                        await message.add_reaction(emoji)
                    except discord.HTTPException:
                        action_result = (True, action_result[1] + "; no pude marcar con mi reacción")
                    else:
                        try:
                            await message.remove_reaction(emoji, actor)
                        except discord.HTTPException:
                            action_result = (True, action_result[1] + "; no pude retirar la reacción del moderador")
        except Exception:
            traceback.print_exc()
            action_result = (False, "Error al ejecutar la acción; revise permisos y configuración.")
        finally:
            _moderation_report_pending.discard(action_key)

    embed = discord.Embed(
        title="Reporte por reacción",
        description=f"**Motivo:** {report_type}",
        color=discord.Color.orange(),
        timestamp=datetime.now(timezone.utc),
    )
    embed.add_field(name="Miembro", value=target.mention, inline=True)
    embed.add_field(name="Reportado por", value=actor.mention, inline=True)
    embed.add_field(name="Canal", value=message.channel.mention, inline=True)
    embed.add_field(name="Reportes recibidos", value=f"{reporter_count}/{threshold}", inline=True)
    embed.add_field(
        name="Acción prevista",
        value=moderation_action_label(str(report_rule.get("action", "report"))) if report_rule else "Solo reportar",
        inline=True,
    )
    if action_result is not None:
        success, explanation = action_result
        embed.add_field(
            name="Resultado",
            value=("Completada: " if success else "No completada: ") + explanation[:950],
            inline=False,
        )
        embed.color = discord.Color.green() if success else discord.Color.orange()
    if message.content:
        embed.add_field(name="Mensaje", value=message.content[:1000], inline=False)
    embed.add_field(name="Referencia", value=f"[Abrir mensaje]({message.jump_url})", inline=False)
    try:
        await report_channel.send(embed=embed, allowed_mentions=discord.AllowedMentions.none())
    except discord.HTTPException:
        _moderation_report_dedupe.pop(dedupe_key, None)
        # Nunca informar como ejecutada una acción cuya trazabilidad no se pudo publicar.
        # El estado real de la acción se conserva para no aplicarla dos veces.
        print("Moderation: no se pudo publicar el resultado de reporte en su canal.")


class ReactionCondemnReasonModal(discord.ui.Modal, title="Condenar por reacción"):
    reason = discord.ui.TextInput(
        label="Razón de la condena",
        style=discord.TextStyle.paragraph,
        required=True,
        min_length=3,
        max_length=1000,
        placeholder="Explica obligatoriamente por qué se aplica la condena.",
    )

    def __init__(self, view: "ReactionCondemnReasonView") -> None:
        super().__init__()
        self.parent_view = view

    async def on_submit(self, interaction: discord.Interaction) -> None:
        view = self.parent_view
        if interaction.user.id != view.actor_id:
            await interaction.response.send_message("Este proceso de condena no te pertenece.")
            return
        guild = bot.get_guild(view.guild_id)
        if guild is None:
            await interaction.response.send_message("Ya no puedo acceder al servidor donde se inició esta condena.")
            _reaction_condemn_pending.discard(view.pending_key)
            return
        actor = guild.get_member(view.actor_id)
        if actor is None or not (actor.guild_permissions.administrator or actor.guild_permissions.kick_members):
            await interaction.response.send_message("Ya no tienes permisos suficientes para aplicar esta condena.")
            _reaction_condemn_pending.discard(view.pending_key)
            return
        channel = guild.get_channel_or_thread(view.channel_id)
        if channel is None or not hasattr(channel, "fetch_message"):
            await interaction.response.send_message("El mensaje original ya no está disponible.")
            _reaction_condemn_pending.discard(view.pending_key)
            return
        try:
            message = await channel.fetch_message(view.message_id)
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            await interaction.response.send_message("El mensaje original ya no está disponible.")
            _reaction_condemn_pending.discard(view.pending_key)
            return
        target = guild.get_member(view.target_id)
        if target is None or target.bot or target.id != message.author.id:
            await interaction.response.send_message("El miembro objetivo ya no está disponible.")
            _reaction_condemn_pending.discard(view.pending_key)
            return
        if not moderation_report_punishment_enabled(guild.id, "condemn") or not moderation_can_condemn(actor, target):
            await interaction.response.send_message(
                "La condena por reacción fue desactivada o ya no tiene permisos suficientes."
            )
            _reaction_condemn_pending.discard(view.pending_key)
            return
        reason = str(self.reason).strip()
        if not reason:
            await interaction.response.send_message("La razón es obligatoria.")
            return

        await interaction.response.defer(thinking=True)
        ok, note = await condemn_member(
            target,
            reason=reason,
            duration_minutes=condemnation_default_duration_minutes(guild.id),
            purge_spec=HONEYPOT_PURGE_DEFAULT,
            origin="reaction",
            applied_by=actor,
            source_message_url=message.jump_url,
            source_channel_id=message.channel.id,
        )
        _reaction_condemn_pending.discard(view.pending_key)
        if view.prompt_message is not None:
            try:
                await view.prompt_message.edit(
                    content=(
                        f"Condena aplicada a **{target}**. {note}"
                        if ok else f"No pude aplicar la condena: {note}"
                    ),
                    view=None,
                )
            except discord.HTTPException:
                await interaction.followup.send(
                    f"Condena aplicada a **{target}**. {note}"
                    if ok else f"No pude aplicar la condena: {note}"
                )
        else:
            await interaction.followup.send(
                f"Condena aplicada a **{target}**. {note}"
                if ok else f"No pude aplicar la condena: {note}"
            )


class ReactionCondemnReasonView(discord.ui.View):
    def __init__(
        self, *, guild_id: int, actor_id: int, channel_id: int, message_id: int,
        target_id: int, pending_key: tuple[int, int],
    ) -> None:
        super().__init__(timeout=120)
        self.guild_id = guild_id
        self.actor_id = actor_id
        self.channel_id = channel_id
        self.message_id = message_id
        self.target_id = target_id
        self.pending_key = pending_key
        self.prompt_message: discord.Message | None = None

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.actor_id:
            await interaction.response.send_message("Solo el moderador que inició esta condena puede continuar.")
            return False
        return True

    @discord.ui.button(label="Indicar razón", style=discord.ButtonStyle.primary)
    async def enter_reason(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        await interaction.response.send_modal(ReactionCondemnReasonModal(self))

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        _reaction_condemn_pending.discard(self.pending_key)
        await interaction.response.edit_message(content="Condena por reacción cancelada.", view=None)
        self.stop()

    async def on_timeout(self) -> None:
        _reaction_condemn_pending.discard(self.pending_key)
        if self.prompt_message is not None:
            try:
                await self.prompt_message.edit(content="La solicitud de condena por reacción expiró.", view=None)
            except discord.HTTPException:
                pass




# --- Comandos /honeypot -----------------------------------------------------

class HoneypotGroup(discord.app_commands.Group):
    """Además de default_permissions (que un admin puede ampliar en Integraciones), el código
    exige Gestionar servidor en cada subcomando."""

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        perms = getattr(interaction.user, "guild_permissions", None)
        if perms is None or not perms.manage_guild:
            raise discord.app_commands.MissingPermissions(["manage_guild"])
        return True


honeypot_group = HoneypotGroup(
    name="honeypot",
    description="Canales trampa que atrapan bots de spam.",
    guild_only=True,
    default_permissions=discord.Permissions(manage_guild=True),
)


class HoneypotWarningModal(discord.ui.Modal, title="Texto del aviso fijado"):
    text = discord.ui.TextInput(
        label="Aviso (vacío = texto por defecto)",
        style=discord.TextStyle.paragraph,
        required=False,
        max_length=1500,
        default="",
    )

    def __init__(self, guild_id: int) -> None:
        super().__init__()
        self.guild_id = guild_id
        self.text.default = hp_setting_get(guild_id, "honeypot_warning_text") or HONEYPOT_WARNING_TEXT_DEFAULT

    async def on_submit(self, interaction: discord.Interaction) -> None:
        value = str(self.text).strip()
        await confirm_configuration(interaction, self.guild_id, {
            "honeypot_warning_text": value if value != HONEYPOT_WARNING_TEXT_DEFAULT else "",
            "honeypot_warning_style": "text",
        })


@honeypot_group.command(name="setup", description="Ver o cambiar la configuración del honeypot.")
@discord.app_commands.describe(
    activado="Activar o desactivar el honeypot",
    accion="Qué hacer con quien caiga en la trampa",
    rol_castigo="Rol Condenado: se le quitan todos los demás roles asignables (incluidos Tentad@ y Sin Verificar)",
    purga="Qué borrar: todo, una cantidad (200 mensajes) o un rango (30m, 2d…); 0 = nada",
    timeout="Duración del timeout si la acción es Aislar: 30m, 12h, 2d… (1m a 28d)",
    aviso="Publicar un aviso fijado en cada canal trampa",
    ping_rol="Rol a mencionar en cada reporte",
    retencion="Cuánto guardar el historial y los textos capturados: 12h, 7d, 30d… (por defecto 30d)",
)
@discord.app_commands.choices(accion=[
    discord.app_commands.Choice(name="Purgar y aplicar rol de castigo", value="role"),
    discord.app_commands.Choice(name="Solo registrar (prueba segura)", value="log"),
    discord.app_commands.Choice(name="Aislar (timeout)", value="timeout"),
    discord.app_commands.Choice(name="Expulsar", value="kick_enabled"),
    discord.app_commands.Choice(name="Banear", value="ban_enabled"),
])
async def honeypot_config(
    interaction: discord.Interaction,
    activado: Optional[bool] = None,
    accion: Optional[discord.app_commands.Choice[str]] = None,
    rol_castigo: Optional[discord.Role] = None,
    purga: Optional[str] = None,
    timeout: Optional[str] = None,
    aviso: Optional[bool] = None,
    ping_rol: Optional[discord.Role] = None,
    retencion: Optional[str] = None,
) -> None:
    if not await configuration_access(interaction):
        return
    guild = interaction.guild
    if all(v is None for v in (activado, accion, rol_castigo, purga, timeout, aviso, ping_rol, retencion)):
        await interaction.response.send_message(hp_config_summary(guild), ephemeral=True)
        return
    if activado and not hp_traps(guild.id):
        await interaction.response.send_message(
            "Error: No lo activé: añade al menos un canal trampa con `/honeypot add` o `/honeypot create`.",
            ephemeral=True,
        )
        return

    if rol_castigo is not None:
        problem = hp_role_problem(rol_castigo, guild)
        if problem:
            await interaction.response.send_message(f"Error: No guardé nada: {rol_castigo.mention} {problem}.", ephemeral=True)
            return
    effective_action = (
        next(
            (key for key, value in HONEYPOT_DESTRUCTIVE_ACTION_STORAGE.items()
             if value == accion.value),
            accion.value,
        ) if accion is not None else hp_action(guild.id)
    )
    if effective_action in {"kick", "ban"} and (accion is not None or activado):
        problem = hp_sanction_permission_problem(
            guild, effective_action, interaction.user.guild_permissions,
        )
        if problem:
            await interaction.response.send_message(
                problem + " No se guardó la configuración.", ephemeral=True,
            )
            return
    effective_role_id = rol_castigo.id if rol_castigo is not None else hp_punish_role_id(guild.id)
    if effective_action == "role" and (activado or accion is not None) and guild.get_role(effective_role_id) is None:
        await interaction.response.send_message(
            "Error: No guardé nada: la acción «rol de castigo» necesita un rol. Elígelo con `rol_castigo`.",
            ephemeral=True,
        )
        return

    # Validar duraciones antes de guardar nada.
    purga_spec = None
    timeout_min = None
    retencion_min = None
    try:
        if purga is not None:
            purga_spec = parse_purge_spec(purga)
        if timeout is not None:
            timeout_min = parse_duration(timeout, HONEYPOT_TIMEOUT_MIN_MINUTES, HONEYPOT_TIMEOUT_MAX_MINUTES)
        if retencion is not None:
            retencion_min = parse_duration(retencion, 1, PURGE_MAX_MINUTES)
    except ValueError as e:
        await interaction.response.send_message(f"Error: No guardé nada: {e}", ephemeral=True)
        return

    changes: dict[str, str] = {}
    if activado is not None:
        changes["honeypot_enabled"] = "1" if activado else "0"
        if activado:
            changes["honeypot_paused"] = "0"
    if accion is not None:
        changes["honeypot_action"] = accion.value
    if rol_castigo is not None:
        changes["honeypot_punish_role"] = str(rol_castigo.id)
    if purga_spec is not None:
        changes["honeypot_purge_spec"] = f"{purga_spec[0]}:{purga_spec[1]}"
    if timeout_min is not None:
        changes["honeypot_timeout_minutes"] = str(timeout_min)
    if retencion_min is not None:
        changes["honeypot_retention_minutes"] = str(retencion_min)
    if ping_rol is not None:
        changes["honeypot_ping_role"] = str(ping_rol.id)
    if aviso is not None:
        changes["honeypot_warning_enabled"] = "1" if aviso else "0"

    # Todos los cambios pasan por un borrador efímero. Cancelar no escribe.
    await confirm_configuration(interaction, guild.id, changes)

class HoneypotTrapActionConfirmView(discord.ui.View):
    """Confirma y revalida cambios de canales trampa antes de ejecutarlos."""
    def __init__(self, guild_id: int, owner_id: int, action: str,
                 channel_id: int | None = None, *, from_setup: bool = False):
        super().__init__(timeout=300)
        self.guild_id, self.owner_id = guild_id, owner_id
        self.action, self.channel_id = action, channel_id
        self.from_setup = from_setup
        self.finished = False
        # Al confirmar se distingue crear/registrar de retirar un canal trampa.
        self.confirm.style = (discord.ButtonStyle.danger if action == "remove"
                              else discord.ButtonStyle.success)

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        return await configuration_access(interaction, self.guild_id, self.owner_id)

    @discord.ui.button(label="Confirmar cambios", style=discord.ButtonStyle.danger)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.response.send_message("La solicitud ya se resolvió.", ephemeral=True)
            return
        guild = interaction.guild
        me = guild.me
        channel = guild.get_channel(self.channel_id) if self.channel_id is not None else None
        if self.action == "create":
            if not interaction.user.guild_permissions.manage_channels or (
                me is None or not me.guild_permissions.manage_channels
            ):
                await interaction.response.send_message(
                    "Se requiere Gestionar canales tanto para el administrador como para el Heraldo.",
                    ephemeral=True,
                )
                return
        else:
            if not isinstance(channel, discord.TextChannel):
                await interaction.response.send_message("El canal ya no existe.", ephemeral=True)
                return
            registered = channel.id in hp_traps(guild.id)
            if (self.action == "add" and registered) or (self.action == "remove" and not registered):
                await interaction.response.send_message("La configuración cambió. Abre una nueva propuesta.", ephemeral=True)
                return
            if self.action == "add":
                reason = hp_protected_channel_reason(channel)
                perms = channel.permissions_for(me) if me is not None else None
                if reason or perms is None or not (
                    perms.view_channel and perms.send_messages and perms.manage_messages
                ):
                    await interaction.response.send_message(
                        "El canal ya no cumple las condiciones o permisos necesarios.", ephemeral=True
                    )
                    return
        self.finished = True
        self.stop()
        await interaction.response.defer(ephemeral=True)
        if self.action == "add":
            if self.from_setup:
                note = await _setup_apply_system_channel(
                    guild, "honeypot", channel, publish_messages=True,
                )
                warning = None if "pero " not in note else note
            else:
                hp_add_trap(guild.id, channel.id)
                warning = await hp_sync_warning(channel)
            await interaction.followup.send(
                f"{channel.mention} se añadió como canal trampa."
                + (f"\nAdvertencia: {warning}" if warning else ""), ephemeral=True,
            )
            await log_embed(guild, "Canal trampa añadido",
                            f"{interaction.user.mention} confirmó {channel.mention}.")
        elif self.action == "remove":
            old_message_id = hp_traps(guild.id).get(channel.id)
            if old_message_id:
                try:
                    await (await channel.fetch_message(old_message_id)).delete()
                except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                    pass
            hp_remove_trap(guild.id, channel.id)
            extra = ""
            if not hp_traps(guild.id) and honeypot_enabled(guild.id):
                hp_setting_set(guild.id, "honeypot_enabled", "0")
                extra = " Se desactivó el honeypot porque no quedan canales trampa."
            await interaction.followup.send(
                f"{channel.mention} dejó de ser canal trampa.{extra}", ephemeral=True
            )
            await log_embed(guild, "Canal trampa quitado",
                            f"{interaction.user.mention} confirmó la retirada de {channel.mention}.")
        elif self.action == "create":
            overwrites = {
                guild.default_role: discord.PermissionOverwrite(
                    view_channel=True, send_messages=True, create_public_threads=False,
                    create_private_threads=False, send_messages_in_threads=False,
                )
            }
            try:
                channel = await guild.create_text_channel(
                    "honeypot", overwrites=overwrites, reason="Creación de honeypot confirmada"
                )
            except discord.HTTPException:
                await interaction.followup.send(
                    "No se pudo crear el canal trampa. Revise los permisos y reintente.", ephemeral=True
                )
                return
            if self.from_setup:
                note = await _setup_apply_system_channel(
                    guild, "honeypot", channel, publish_messages=True,
                )
                warning = None if "pero " not in note else note
            else:
                hp_add_trap(guild.id, channel.id)
                warning = await hp_sync_warning(channel)
            await interaction.followup.send(
                f"Se creó {channel.mention} como canal trampa."
                + (f"\nAdvertencia: {warning}" if warning else "")
                + "\nPara activarlo, use /honeypot setup y confirme los cambios.",
                ephemeral=True,
            )
            await log_embed(guild, "Canal trampa creado",
                            f"{interaction.user.mention} confirmó la creación de {channel.mention}.")

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if not await self.interaction_check(interaction):
            return
        if self.finished:
            await interaction.response.send_message("La solicitud ya se resolvió.", ephemeral=True)
            return
        self.finished = True
        self.stop()
        await interaction.response.edit_message(
            content="Operación cancelada. No se realizaron cambios.", view=None,
        )


@honeypot_group.command(name="add", description="Convertir un canal de texto existente en canal trampa.")
@discord.app_commands.describe(canal="Canal de texto que todos puedan ver y en el que puedan escribir")
async def honeypot_add(interaction: discord.Interaction, canal: discord.TextChannel) -> None:
    if not await configuration_access(interaction):
        return
    if canal.id in hp_traps(interaction.guild.id):
        await interaction.response.send_message("El canal ya está registrado como trampa.", ephemeral=True)
        return
    if hp_protected_channel_reason(canal):
        await interaction.response.send_message("Este canal está protegido y no puede usarse como trampa.", ephemeral=True)
        return
    me = interaction.guild.me
    perms = canal.permissions_for(me) if me is not None else None
    if perms is None or not (perms.view_channel and perms.send_messages and perms.manage_messages):
        await interaction.response.send_message("Faltan permisos del bot en el canal.", ephemeral=True)
        return
    await interaction.response.send_message(
        f"¿Confirma añadir {canal.mention} como canal trampa?",
        view=HoneypotTrapActionConfirmView(interaction.guild.id, interaction.user.id, "add", canal.id),
        ephemeral=True,
    )

